insert into public.subjects (id, slug, name, short_name, level, description, sort_order) values
  ('sub-bahasa-indonesia-sd', 'bahasa-indonesia-sd', 'Bahasa Indonesia SD', 'Bahasa Indonesia', 'SD', 'Latihan dan tryout TKA Bahasa Indonesia tingkat SD sesuai matriks asesmen Pusmendik: Pemahaman Tekstual, Pemahaman Inferensial, serta Evaluasi dan Apresiasi. Seluruhnya menguji keterampilan membaca teks informasi dan teks fiksi.', 4)
insert into public.content_series (id, slug, title, description, is_active, sort_order) values
  ('series-latihan-tka-bahasa-indonesia-sd', 'latihan-tka-bahasa-indonesia-sd', 'Latihan TKA Bahasa Indonesia SD', 'Seri latihan diagnostik TKA Bahasa Indonesia SD berdasarkan matriks asesmen Pusmendik. Satu paket untuk satu subkompetensi.', true, 5)
insert into public.products (id, slug, title, subject_id, series_id, description, is_active, sort_order) values
  ('prd-latihan-tka-bahasa-indonesia-sd', 'latihan-tka-bahasa-indonesia-sd', 'Latihan TKA Bahasa Indonesia SD', 'sub-bahasa-indonesia-sd', 'series-latihan-tka-bahasa-indonesia-sd', 'Membuka seluruh paket latihan Bahasa Indonesia SD dalam seri Latihan TKA Bahasa Indonesia SD.', true, 5)
insert into public.topics (id, subject_id, slug, name, description, sort_order) values
  ('top-bi-sd-tekstual', 'sub-bahasa-indonesia-sd', 'pemahaman-tekstual', 'Pemahaman Tekstual', 'Memahami informasi yang dikemukakan secara eksplisit, mengelompokkan, menyusun ulang, dan menyajikan kembali informasi dari teks.', 0),
  ('top-bi-sd-inferensial', 'sub-bahasa-indonesia-sd', 'pemahaman-inferensial', 'Pemahaman Inferensial', 'Menarik kesimpulan berdasarkan informasi yang tersirat dalam teks.', 1),
  ('top-bi-sd-evaluasi', 'sub-bahasa-indonesia-sd', 'evaluasi-dan-apresiasi', 'Evaluasi dan Apresiasi', 'Menilai ide dalam teks serta menanggapinya secara emosional dan estetis dengan mempertimbangkan dampaknya terhadap perasaan, imajinasi, dan penggunaan bahasa oleh penulis.', 2)
insert into public.subtopics (id, topic_id, slug, name, description, sort_order) values
  ('st-bi-sd-kosakata-umum-khusus', 'top-bi-sd-tekstual', 'kosakata-umum-dan-khusus', 'Kosakata Umum dan Khusus', 'Mengidentifikasi penggunaan kosakata umum dan khusus dalam berbagai bidang.', 0),
  ('st-bi-sd-objek-kosakata', 'top-bi-sd-tekstual', 'objek-berdasarkan-kosakata', 'Objek Berdasarkan Kosakata', 'Mengidentifikasi objek berdasarkan kosakata yang digunakan dalam teks fiksi atau nonfiksi.', 1),
  ('st-bi-sd-ikhtisar-bagan', 'top-bi-sd-tekstual', 'ikhtisar-dan-bagan', 'Ikhtisar dan Bagan', 'Menyusun kembali informasi dari teks dalam bentuk ikhtisar atau bagan.', 2),
  ('st-bi-sd-informasi-tersurat', 'top-bi-sd-tekstual', 'informasi-tersurat', 'Informasi Tersurat', 'Mengidentifikasi informasi tersurat dalam teks.', 3),
  ('st-bi-sd-ide-pokok', 'top-bi-sd-inferensial', 'ide-pokok-amanat-dan-nilai', 'Ide Pokok, Amanat, dan Nilai', 'Menyimpulkan ide pokok, gagasan pendukung, amanat, tokoh, peristiwa, dan/atau nilai-nilai dalam teks.', 4),
  ('st-bi-sd-perubahan-unsur', 'top-bi-sd-inferensial', 'perubahan-objek-karakter-dan-latar', 'Perubahan Objek, Karakter, dan Latar', 'Menyimpulkan perubahan sederhana pada objek, karakter, dan/atau latar dalam teks fiksi atau nonfiksi.', 5),
  ('st-bi-sd-makna-ungkapan', 'top-bi-sd-inferensial', 'makna-ungkapan', 'Makna Ungkapan', 'Menjelaskan makna ungkapan yang digunakan dalam teks.', 6),
  ('st-bi-sd-relevansi-peristiwa', 'top-bi-sd-evaluasi', 'relevansi-peristiwa', 'Relevansi Peristiwa dengan Kehidupan Sehari-hari', 'Menilai relevansi peristiwa dalam teks dengan kehidupan sehari-hari berdasarkan pengalaman atau pengetahuan pribadi.', 7),
  ('st-bi-sd-kesesuaian-antarunsur', 'top-bi-sd-evaluasi', 'kesesuaian-antarunsur', 'Kesesuaian Antarunsur dan Antarinformasi', 'Menilai kesesuaian antarunsur dan/atau antarinformasi dalam teks.', 8),
  ('st-bi-sd-respons-emosional', 'top-bi-sd-evaluasi', 'respons-emosional', 'Respons Emosional terhadap Teks Fiksi', 'Menyimpulkan respons emosional terhadap unsur teks fiksi.', 9)
insert into public.concepts (id, subtopic_id, name, description, sort_order) values
  ('con-bi-sd-kosakata-umum-khusus', 'st-bi-sd-kosakata-umum-khusus', 'Kosakata umum dan khusus bidang pertanian, kesehatan, dan perbengkelan', 'Menentukan makna kata khusus berdasarkan konteks teks informasi dan teks fiksi, serta memilah kata umum dari kata khusus pada bidang yang sama.', 1),
  ('con-bi-sd-objek-kosakata', 'st-bi-sd-objek-kosakata', 'Objek berdasarkan kosakata pada teks fiksi, teks informasi, dan puisi', 'Menentukan benda yang dimaksud penulis dengan mengumpulkan kata-kata penciri bentuk, bahan, bagian, dan kegunaan yang tersebar di dalam teks.', 2),
  ('con-bi-sd-ikhtisar-bagan', 'st-bi-sd-ikhtisar-bagan', 'Bagan pengelompokan, bagan urutan, dan ikhtisar teks informasi', 'Memindahkan isi teks ke dalam bentuk bagan atau ikhtisar dengan menjaga hubungan kelompok–contoh dan urutan langkah tetap seperti pada teks.', 3),
  ('con-bi-sd-informasi-tersurat', 'st-bi-sd-informasi-tersurat', 'Informasi tersurat pada fabel, teks sejarah sederhana, dan cerita kegiatan', 'Menemukan kembali informasi yang tertulis apa adanya di dalam teks serta memeriksa pernyataan yang tampak mirip tetapi mengubah isinya.', 4),
  ('con-bi-sd-ide-pokok', 'st-bi-sd-ide-pokok', 'Ide pokok, gagasan pendukung, amanat, tokoh, peristiwa, dan nilai', 'Menyimpulkan pikiran utama sebuah paragraf maupun seluruh teks, serta menyimpulkan amanat, sifat tokoh, dan nilai dari rangkaian peristiwa dalam cerita.', 5),
  ('con-bi-sd-perubahan-unsur', 'st-bi-sd-perubahan-unsur', 'Perubahan objek pada teks proses serta perubahan karakter dan latar pada cerita', 'Menyimpulkan apa yang berubah, dari keadaan apa menjadi apa, dan peristiwa mana yang menyebabkan perubahan tersebut.', 6),
  ('con-bi-sd-makna-ungkapan', 'st-bi-sd-makna-ungkapan', 'Makna ungkapan dalam cerita, kisah nyata, dan puisi', 'Menentukan makna ungkapan dengan membaca kalimat sebelum dan sesudahnya, bukan dengan mengartikan katanya satu per satu.', 7),
  ('con-bi-sd-relevansi-peristiwa', 'st-bi-sd-relevansi-peristiwa', 'Relevansi peristiwa dalam teks dengan pengalaman sehari-hari', 'Menilai kejadian sehari-hari mana yang sejalan dengan peristiwa dan pesan dalam teks, dengan bukti dari teks dan pengalaman pribadi.', 8),
  ('con-bi-sd-kesesuaian-antarunsur', 'st-bi-sd-kesesuaian-antarunsur', 'Kesesuaian gambar, judul, data, dan kalimat dalam satu teks', 'Memeriksa apakah setiap unsur teks — gambar, warna, judul, data, dan tiap kalimat — sudah mendukung isi yang sama, lalu menandai bagian yang tidak cocok.', 9),
  ('con-bi-sd-respons-emosional', 'st-bi-sd-respons-emosional', 'Respons emosional terhadap cerita dan puisi', 'Menyimpulkan perasaan yang wajar dirasakan pembaca terhadap tokoh, peristiwa, dan pilihan kata dalam teks fiksi, disertai bukti kalimat atau lariknya.', 10)
insert into public.passages (id, subject_id, label, body_html, sort_order) values
  ('psg-bisd-kosakata-kebun', 'sub-bahasa-indonesia-sd', 'Teks untuk soal nomor 1 s.d. 3', '<p><strong>Kebun Sayur di Belakang Sekolah</strong></p><p>Sekolah kami mempunyai kebun kecil di belakang. Kebun itu dirawat siswa kelas lima. Setiap Jumat pagi, kami bekerja di sana.</p><p>Kegiatan pertama adalah menyemai benih bayam. Benih ditabur di kotak berisi tanah halus. Kotak itu diletakkan di tempat teduh. Setelah tujuh hari, muncul bibit kecil berdaun dua.</p><p>Bibit lalu dipindahkan ke bedeng. Bedeng dibuat memanjang dan sedikit meninggi. Bentuk seperti itu membuat air tidak menggenang. Jarak antarbibit diatur agar daunnya tidak berdesakan.</p><p>Pak Karta, penjaga sekolah, mengajari kami membuat kompos. Bahannya daun kering dan sisa sayur dapur. Bahan itu ditumpuk lalu dibiarkan tiga pekan. Kompos menyuburkan tanah tanpa membeli pupuk pabrik.</p><p>Sebulan kemudian, kami panen bayam pertama. Panen dilakukan pada pagi hari. Daunnya masih segar karena matahari belum terik. Hasilnya dibagikan kepada guru dan penjaga sekolah.</p><p>Kata Pak Karta, kebun butuh perawatan setiap hari. Kami pun membuat jadwal menyiram bergiliran.</p>', 0),
  ('psg-bisd-kosakata-posyandu', 'sub-bahasa-indonesia-sd', 'Teks untuk soal nomor 4, 5, dan 8', '<p><strong>Hari Posyandu di Balai Desa</strong></p><p>Setiap tanggal sepuluh, Balai Desa Sukamaju ramai. Hari itu adalah hari posyandu. Ibu-ibu datang membawa anak balita.</p><p>Kegiatan dimulai di meja pertama. Nama anak dicatat pada buku besar. Setelah itu, anak ditimbang di meja kedua. Berat badannya ditulis pada Kartu Menuju Sehat.</p><p>Di meja ketiga, kader mengisi grafik pada kartu itu. Kader adalah warga desa yang membantu petugas kesehatan. Titik-titik pada grafik dihubungkan dengan garis. Garis yang naik menandakan berat badan bertambah.</p><p>Di meja keempat, ibu-ibu mendapat penyuluhan. Petugas menjelaskan menu sehat untuk balita. Menu itu berisi nasi, lauk, sayur, dan buah. Ibu-ibu boleh bertanya tentang makanan anaknya. Pertanyaan mereka dicatat pada buku kegiatan.</p><p>Meja kelima dijaga bidan desa. Di sana anak menerima imunisasi. Bayi juga mendapat vitamin A pada bulan tertentu.</p><p>Bu Rina, bidan desa, selalu mengingatkan satu hal. Balita perlu ditimbang setiap bulan. Dengan begitu, gangguan pertumbuhan diketahui lebih awal.</p>', 1),
  ('psg-bisd-kosakata-bengkel', 'sub-bahasa-indonesia-sd', 'Teks untuk soal nomor 6, 7, dan 9', '<p><strong>Sepeda Ayah dan Kunci Pas</strong></p><p>Sore itu aku ikut Ayah ke bengkel Pak Rusdi. Sepeda kami rusak sejak kemarin. Rantainya lepas saat menuruni jalan.</p><p>Pak Rusdi menyambut kami sambil tersenyum. Ia membalik sepeda hingga sadelnya menyentuh lantai. Tangannya cekatan memutar pedal.</p><p>“Rantainya kendur, Pak,” katanya kepada Ayah.</p><p>Pak Rusdi mengambil kunci pas dari kotak kayu. Baut pada roda belakang ia longgarkan. Roda ditarik sedikit ke belakang. Rantai pun kembali tegang.</p><p>Aku memperhatikan pelek roda yang berkilau. Jari-jari roda tersusun rapi seperti benang laba-laba. Pak Rusdi mengetuk jari-jari itu satu per satu. Bunyinya nyaring dan seragam.</p><p>“Kalau ada yang kendur, bunyinya berbeda,” ujarnya kepadaku.</p><p>Setelah itu, ban depan diisi angin. Pentilnya diperiksa dengan air sabun. Tidak ada gelembung yang keluar. Berarti ban tidak bocor. Pak Rusdi lalu melumasi rantai dengan oli. Kain lapnya menghitam oleh sisa oli.</p><p>Ayah membayar ongkos perbaikan. Aku mengayuh sepeda pulang bersama Ayah. Rantainya tidak berbunyi lagi.</p>', 2),
  ('psg-bisd-objek-gudang', 'sub-bahasa-indonesia-sd', 'Teks untuk soal nomor 1, 2, 3, dan 8', '<p><strong>Sore di Gudang Nenek</strong></p><p>Liburan kemarin aku menginap di rumah Nenek. Sore itu Nenek mengajakku ke gudang belakang. Pintunya berderit ketika dibuka.</p><p>Di sudut gudang ada benda kayu memanjang. Bagian tengahnya berlubang seperti perahu kecil. Di sampingnya tergeletak batang kayu sebesar lengan. “Dulu padi ditumbuk di situ,” kata Nenek.</p><p>Aku juga melihat bambu panjang tergantung di dinding. Bambu itu berlubang memanjang di satu sisi. Nenek memukulnya pelan dengan sepotong kayu. Bunyinya nyaring sampai ke halaman. Dulu bunyi itu memanggil warga berkumpul.</p><p>Di rak bawah ada wadah tembaga besar. Bentuknya seperti kerucut terbalik. Nenek biasa memakainya untuk mengukus nasi. Uap panas keluar dari mulutnya yang lebar.</p><p>Yang paling kusuka adalah lampu kecil berbahan kaca. Sumbunya menjulur dari wadah minyak. Nenek menyalakannya saat listrik padam. Nyalanya bergoyang bila ada angin.</p><p>“Barang lama boleh usang,” kata Nenek. “Namun ceritanya tetap hidup.” Aku mengangguk sambil memegang lampu itu.</p>', 0),
  ('psg-bisd-objek-pasar', 'sub-bahasa-indonesia-sd', 'Teks untuk soal nomor 4 dan 5', '<p><strong>Alat-Alat di Pasar Pagi</strong></p><p>Pasar pagi selalu ramai sebelum matahari tinggi. Para pedagang memakai alat yang berbeda-beda.</p><p>Pedagang beras memakai alat takar dari kaleng. Kaleng itu diisi beras sampai rata bibirnya. Satu kaleng biasa disebut satu liter.</p><p>Pedagang sayur memakai alat berlengan dua. Di lengan kiri diletakkan barang dagangan. Di lengan kanan diletakkan bandul besi. Lengan akan mendatar bila beratnya sama.</p><p>Pedagang ikan memakai wadah dari anyaman bambu. Wadah itu lebar, bundar, dan tidak dalam. Ikan disusun rapi agar terlihat semua.</p><p>Pedagang buah memakai kantong jala. Kantong itu digantung pada kait besi. Angka pada papan bulat menunjukkan berat buah.</p><p>Pedagang bumbu memakai lumpang kecil dari batu. Bumbu ditumbuk halus di dalamnya. Penumbuknya pendek dan terasa berat di tangan.</p><p>Setiap alat mempunyai kegunaan sendiri. Pembeli merasa yakin bila alat dipakai dengan jujur. Petugas pasar memeriksa alat itu setiap bulan. Pasar pagi biasanya tutup menjelang siang.</p>', 1),
  ('psg-bisd-objek-puisi', 'sub-bahasa-indonesia-sd', 'Puisi untuk soal nomor 6, 7, dan 9', '<p><strong>Sahabat Musim Hujan</strong></p><p>Kau terlipat diam di sudut lemari<br />Menunggu langit berubah kelabu<br />Rangkamu ramping dari besi<br />Kainmu terbentang seperti sayap kelelawar</p><p>Bila titik air mulai berjatuhan<br />Aku menggenggam gagangmu erat<br />Kau berdiri di atas kepalaku<br />Menahan yang turun dari langit</p><p>Jalan berubah menjadi cermin panjang<br />Sepatuku basah di tepiannya<br />Namun bahuku tetap kering<br />Karena kau setia di atasku</p><p>Ketika hujan reda<br />Kau kukibaskan pelan-pelan<br />Butir-butir air berhamburan<br />Lalu kau terlipat lagi, menunggu</p>', 2),
  ('psg-bisd-bagan-sampah', 'sub-bahasa-indonesia-sd', 'Teks untuk soal nomor 1, 2, dan 7', '<p><strong>Sampah di Sekitar Kita</strong></p><p>Setiap hari kita menghasilkan sampah. Sampah dapat dibagi menjadi dua kelompok. Kelompok itu adalah sampah organik dan sampah anorganik.</p><p>Sampah organik berasal dari makhluk hidup. Contohnya sisa sayur, kulit buah, dan daun kering. Sampah ini mudah membusuk. Sampah organik dapat diolah menjadi kompos.</p><p>Sampah anorganik tidak berasal dari makhluk hidup. Contohnya botol plastik, kaleng, dan pecahan kaca. Sampah ini sulit membusuk. Sampah anorganik masih dapat didaur ulang.</p><p>Sampah sebaiknya dipisahkan sejak dari rumah. Dua tempat sampah disediakan di dapur. Tempat pertama untuk sampah organik. Tempat kedua untuk sampah anorganik. Warna kedua tempat itu sengaja dibedakan. Dengan begitu, isinya tidak mudah tertukar.</p><p>Di sekolah kami, pemisahan dilakukan setiap hari. Petugas piket membawa sampah organik ke lubang kompos. Sampah anorganik dikumpulkan di bank sampah. Hasil penjualannya menjadi kas kelas.</p><p>Memisahkan sampah tampak sepele. Namun, kebiasaan itu membuat sampah lebih mudah diolah.</p>', 0),
  ('psg-bisd-bagan-telur', 'sub-bahasa-indonesia-sd', 'Teks untuk soal nomor 3, 4, dan 8', '<p><strong>Cara Membuat Telur Asin</strong></p><p>Telur asin banyak dijual di pasar. Ternyata, telur asin dapat dibuat sendiri di rumah. Bahannya pun mudah didapat.</p><p>Bahan yang disiapkan adalah telur bebek, garam, abu gosok, dan air. Alat yang dipakai berupa baskom, amplas halus, dan wadah tertutup. Telur bebek dipilih karena kulitnya lebih tebal. Kulit yang tebal membuat telur tidak mudah pecah.</p><p>Langkah pertama, telur bebek dicuci bersih. Telur digosok pelan dengan amplas halus. Penggosokan membuat pori-pori kulit telur terbuka.</p><p>Langkah kedua, garam dicampur dengan abu gosok. Air ditambahkan sedikit demi sedikit. Campuran diaduk sampai menjadi adonan liat.</p><p>Langkah ketiga, telur dibalut adonan. Tebal balutan kira-kira satu sentimeter. Telur lalu disusun di dalam wadah tertutup.</p><p>Langkah keempat, telur disimpan selama dua pekan. Wadah diletakkan di tempat sejuk. Setelah itu, balutan dibersihkan dan telur direbus.</p><p>Telur asin siap disantap bersama nasi hangat. Rasanya gurih dan tidak amis.</p>', 1),
  ('psg-bisd-bagan-kelapa', 'sub-bahasa-indonesia-sd', 'Teks untuk soal nomor 5, 6, 9, dan 10', '<p><strong>Pohon Serbaguna dari Pantai</strong></p><p>Pohon kelapa banyak tumbuh di tepi pantai. Batangnya tinggi dan daunnya melambai terkena angin. Hampir semua bagiannya berguna. Karena itu, kelapa disebut pohon serbaguna.</p><p>Daun kelapa yang muda disebut janur. Janur dipakai membuat hiasan dan ketupat. Daun yang tua dianyam menjadi atap gubuk. Tulang daunnya, yaitu lidi, dijadikan sapu. Pelepah daun yang kering dipakai menyalakan tungku.</p><p>Batang kelapa keras dan lurus. Batang itu dipakai membuat jembatan kecil. Batang juga dijadikan tiang rumah dan bangku.</p><p>Buah kelapa mempunyai banyak bagian. Air kelapa muda menjadi minuman segar. Daging buahnya diparut menjadi santan. Tempurungnya dibuat menjadi gayung dan arang. Sabutnya dijadikan keset dan tali.</p><p>Akar kelapa pun berguna. Akarnya berbentuk serabut dan menyebar luas. Akar itu menahan pasir agar tidak longsor.</p><p>Warga pantai merawat pohon kelapa dengan telaten. Pohon itu memberi bahan makanan sekaligus bahan bangunan. Karena itu, warga menanam pohon kelapa baru setiap tahun.</p>', 2),
  ('psg-bisd-tersurat-semut', 'sub-bahasa-indonesia-sd', 'Teks untuk soal nomor 1, 2, dan 8', '<p><strong>Semut dan Burung Pipit</strong></p><p>Di tepi sungai kecil hiduplah seekor semut. Namanya Simut. Ia rajin mencari remah makanan setiap pagi.</p><p>Suatu hari Simut berjalan di batang kayu. Angin bertiup kencang dan menggoyang batang itu. Simut terjatuh ke dalam sungai. Ia berusaha berpegang pada sehelai daun kecil.</p><p>Seekor burung pipit melihat kejadian itu dari dahan. Burung itu bernama Pipi. Ia segera memetik daun yang lebar. Daun itu dijatuhkan tepat di dekat Simut. Simut naik ke atas daun lalu terbawa ke tepi.</p><p>Beberapa hari kemudian, Pipi hinggap di semak. Seorang pemburu mengendap-endap membawa jaring. Simut melihat pemburu itu dari balik akar. Ia berlari cepat lalu menggigit kaki pemburu.</p><p>Pemburu itu terkejut dan berteriak keras. Pipi mendengar suara itu lalu terbang menjauh. Pemburu itu pergi sambil menahan sakit di kakinya. Malam harinya keduanya bertemu di dahan rendah.</p><p>“Terima kasih, Simut,” ujar Pipi. “Dulu kau lebih dahulu menolongku,” jawab Simut.</p>', 0),
  ('psg-bisd-tersurat-kereta', 'sub-bahasa-indonesia-sd', 'Teks untuk soal nomor 3, 4, 5, dan 10', '<p><strong>Kereta Api Pertama di Indonesia</strong></p><p>Kereta api sudah lama ada di Indonesia. Jalur pertamanya dibangun di Jawa Tengah. Pembangunan itu dimulai pada tahun 1864.</p><p>Pencangkulan pertama dilakukan di Desa Kemijen, Semarang. Pada masa itu wilayah kita masih dijajah Belanda. Pekerjaannya ditangani sebuah perusahaan kereta swasta.</p><p>Jalur pertama menghubungkan Semarang dan Tanggung. Panjangnya kira-kira dua puluh enam kilometer. Jalur itu mulai dipakai pada 10 Agustus 1867.</p><p>Kereta pertama menarik gerbong barang dan gerbong penumpang. Hasil bumi berupa gula dan kopi diangkut ke pelabuhan. Perjalanan menjadi lebih cepat daripada memakai pedati. Pedagang pun tidak perlu menunggu berhari-hari. Barang dagangan sampai di pelabuhan dalam keadaan lebih baik.</p><p>Setelah itu, jalur kereta dibangun di daerah lain. Jalur muncul di Jawa Timur, Jawa Barat, dan Sumatra.</p><p>Sekarang kereta api mengangkut jutaan penumpang setiap tahun. Stasiun tua di Semarang masih berdiri sampai kini. Bangunan itu menjadi tanda awal perjalanan kereta api Indonesia.</p>', 1),
  ('psg-bisd-tersurat-layangan', 'sub-bahasa-indonesia-sd', 'Teks untuk soal nomor 6, 7, dan 9', '<p><strong>Lomba Layang-Layang di Lapangan Kampung</strong></p><p>Minggu pagi lapangan kampung penuh anak-anak. Hari itu ada lomba layang-layang. Lomba tersebut diadakan setiap bulan Agustus.</p><p>Panitia membagi peserta menjadi dua kelompok. Kelompok pertama untuk kelas satu sampai kelas tiga. Kelompok kedua untuk kelas empat sampai kelas enam.</p><p>Rangga membawa layang-layang berwarna merah. Layang-layang itu ia buat bersama kakaknya. Kerangkanya dari bambu tipis dan kertas minyak. Ekornya dibuat panjang agar layang-layang tidak oleng. Rangga berlatih menerbangkannya sejak dua pekan lalu.</p><p>Pukul delapan pagi lomba dimulai. Peluit ditiup Pak Lurah sebagai tanda. Sepuluh layang-layang naik hampir bersamaan.</p><p>Angin bertiup dari arah timur. Layang-layang Rangga naik paling tinggi. Namun, benangnya tersangkut dahan pohon. Rangga menarik benang itu perlahan agar tidak putus.</p><p>Juara pertama diraih Bima dari kelas lima. Rangga mendapat juara kedua. Hadiahnya berupa buku tulis dan tas sekolah.</p><p>Pukul sepuluh acara selesai. Anak-anak pulang sambil menenteng layang-layang.</p>', 2),
  ('psg-bisd-idepokok-kotakpensil', 'sub-bahasa-indonesia-sd', 'Teks untuk soal nomor 1, 2, dan 8', '<p><strong>Kotak Pensil di Bawah Bangku</strong></p><p>Bel istirahat berbunyi nyaring. Anak-anak berhamburan ke halaman sekolah. Rani tinggal sebentar untuk membereskan mejanya.</p><p>Di bawah bangku paling belakang, Rani menemukan kotak pensil. Kotak itu berwarna biru dengan gambar bintang. Isinya pensil, penghapus, dan uang lima ribu rupiah.</p><p>Rani sempat ragu sejenak. Uang itu cukup untuk membeli semangkuk bakso. Namun, ia teringat pesan ibunya. Barang yang bukan milik kita harus dikembalikan.</p><p>Rani membawa kotak itu ke ruang guru. Bu Sinta mencatat temuan itu pada buku. Nama penemunya ikut ditulis di sana. Setelah istirahat, Bu Sinta bertanya di depan kelas. Ia menyebutkan warna dan gambar pada kotak itu.</p><p>Rupanya kotak itu milik Damar. Damar mencarinya sejak pagi tadi. Wajahnya cerah ketika menerima kotaknya kembali.</p><p>“Terima kasih, Rani,” kata Damar. “Uang itu untuk membayar iuran seragam.”</p><p>Rani hanya tersenyum lalu duduk di bangkunya. Ia merasa lega, walaupun tidak jadi membeli bakso.</p>', 0),
  ('psg-bisd-idepokok-lebah', 'sub-bahasa-indonesia-sd', 'Teks untuk soal nomor 3, 4, 5, dan 10', '<p><strong>Lebah Kecil, Jasanya Besar</strong></p><p>Lebah sering ditakuti karena sengatnya. Padahal, lebah memberi jasa besar bagi manusia. Tanpa lebah, banyak tanaman sulit berbuah.</p><p>Lebah mencari makan berupa nektar bunga. Saat hinggap, serbuk sari menempel pada kakinya. Serbuk itu terbawa ke bunga berikutnya. Peristiwa tersebut disebut penyerbukan.</p><p>Penyerbukan membuat bunga berubah menjadi buah. Pohon mangga, jambu, dan kopi sangat bergantung pada lebah. Kebun yang sering dikunjungi lebah berbuah lebih lebat. Petani pun dapat memanen buah lebih banyak.</p><p>Sayangnya, jumlah lebah semakin berkurang. Racun hama yang berlebihan ikut membunuh lebah. Bunga liar di tepi ladang juga banyak ditebang. Lebah pun kehilangan tempat mencari makan.</p><p>Ada beberapa cara untuk menjaga lebah. Petani dapat mengurangi racun hama. Warga dapat menanam bunga di halaman rumah. Sarang lebah liar sebaiknya tidak dibakar.</p><p>Menjaga lebah berarti menjaga kebun kita. Kebun yang sehat memberi buah bagi semua orang. Karena itu, lebah tidak perlu ditakuti berlebihan.</p>', 1),
  ('psg-bisd-idepokok-bakulkue', 'sub-bahasa-indonesia-sd', 'Teks untuk soal nomor 6, 7, dan 9', '<p><strong>Bakul Kue Bu Sari</strong></p><p>Setiap pagi Bu Sari berjualan kue di depan sekolah. Bakulnya penuh lemper, risoles, dan kue lapis. Anak-anak biasa membeli sebelum bel berbunyi.</p><p>Pagi itu hujan turun sangat deras. Jalan menuju sekolah tergenang air. Bu Sari tetap datang dengan payung besar.</p><p>Sampai di depan gerbang, kakinya terpeleset. Bakul kuenya terjatuh ke genangan. Sebagian kue basah dan tidak dapat dijual.</p><p>Bu Sari duduk termenung di teras sekolah. Kue yang basah ia pisahkan ke dalam kantong. Sampai siang ia belum menerima uang sama sekali.</p><p>Melihat hal itu, Dimas mengajak teman-temannya berkumpul. Mereka berunding sebentar di dekat tiang bendera. Mereka lalu mengumpulkan uang jajan seadanya. Uang yang terkumpul lima puluh ribu rupiah. Kue yang masih kering mereka beli semua.</p><p>Bu Sari terkejut dan matanya berkaca-kaca. “Terima kasih, Nak,” ucapnya lirih.</p><p>Sejak hari itu, Dimas selalu ingat satu hal. Menolong tidak harus menunggu menjadi orang kaya.</p>', 2),
  ('psg-bisd-perubahan-tempe', 'sub-bahasa-indonesia-sd', 'Teks untuk soal nomor 1, 2, 3, dan 8', '<p><strong>Dari Kedelai Menjadi Tempe</strong></p><p>Tempe dibuat dari biji kedelai. Mula-mula kedelai keras dan berwarna kuning. Setelah diolah, kedelai berubah menjadi tempe yang padat dan putih.</p><p>Kedelai direbus lebih dahulu selama satu jam. Biji yang tadinya keras menjadi lunak. Setelah dingin, kulit arinya dikupas. Kedelai lalu dicuci sampai bersih.</p><p>Kedelai yang bersih direndam semalaman. Air rendaman menjadi asam pada keesokan harinya. Rasa asam itu membantu jamur tempe tumbuh.</p><p>Kedelai kemudian ditiriskan sampai kering. Ragi tempe ditaburkan lalu diaduk rata. Kedelai dibungkus daun pisang atau plastik berlubang. Lubang kecil itu dibuat dengan ujung lidi.</p><p>Bungkusan disimpan dua hari di tempat hangat. Benang-benang putih mulai tumbuh di sela kedelai. Benang itu adalah jamur tempe. Butiran kedelai pun menyatu menjadi satu balok padat.</p><p>Tempe yang baru jadi berbau segar. Bila disimpan terlalu lama, tempe berubah menjadi kehitaman. Baunya pun menjadi tajam dan tidak sedap. Tempe seperti itu sebaiknya tidak dimakan.</p>', 0),
  ('psg-bisd-perubahan-rio', 'sub-bahasa-indonesia-sd', 'Teks untuk soal nomor 4, 5, dan 9', '<p><strong>Rio dan Jam Weker</strong></p><p>Dahulu Rio dikenal sebagai anak yang sering terlambat. Ia bangun ketika matahari sudah tinggi. Sarapan pun sering ia tinggalkan.</p><p>Setiap pagi ibunya membangunkan berkali-kali. Rio hanya menarik selimut lalu tidur lagi. Ia baru bergegas saat mendengar bel sekolah dari kejauhan.</p><p>Suatu hari sekolah mengadakan lomba baris-berbaris. Rio dipilih menjadi pemimpin regu. Ia berlatih setiap sore dengan gembira. Aba-abanya terdengar lantang di halaman sekolah.</p><p>Pada hari lomba, Rio datang terlambat setengah jam. Regunya terpaksa maju tanpa pemimpin. Nilai mereka pun berkurang banyak.</p><p>Rio duduk di pojok lapangan tanpa suara. Ia memandangi regunya yang berbaris rapi. Teman-temannya tidak menyalahkan, tetapi ia tetap merasa bersalah.</p><p>Malam itu Rio meminta jam weker kepada ayahnya. Ia menaruh jam itu di dekat bantal. Ia juga menyiapkan seragam sebelum tidur.</p><p>Sejak saat itu Rio berangkat lebih pagi. Ia bahkan sempat membuka jendela kelas. Teman-temannya kini memanggilnya ketua regu.</p>', 1),
  ('psg-bisd-perubahan-kampung', 'sub-bahasa-indonesia-sd', 'Teks untuk soal nomor 6, 7, dan 10', '<p><strong>Kampung Kami Dahulu dan Kini</strong></p><p>Kakek sering bercerita tentang kampung kami. Dahulu di depan rumah terbentang sawah luas. Airnya mengalir dari sungai kecil di utara.</p><p>Pada sore hari, anak-anak bermain layang-layang di pematang. Suara katak terdengar sampai ke teras rumah. Jalan kampung masih berupa tanah berbatu.</p><p>Sekarang keadaannya sudah berbeda. Sawah di depan rumah berubah menjadi deretan toko. Jalan kampung pun sudah dilapisi aspal halus.</p><p>Toko-toko itu buka sejak pagi sampai malam. Anak-anak kini bermain di lapangan kecil dekat balai desa. Suara katak berganti dengan suara kendaraan. Sungai kecil di utara menyempit karena tepinya ditutup bangunan.</p><p>Kakek tidak melarang perubahan itu. Menurutnya, kampung memang tumbuh seperti anak-anak. Ia hanya berpesan satu hal. Sungai dan pepohonan harus tetap dijaga.</p><p>Bersama warga, ayah menanam pohon di tepi jalan. Bibit pohon itu diberi pagar bambu. Setiap sore anak-anak ikut menyiraminya. Lima tahun lagi, jalan kampung akan kembali rindang.</p>', 2),
  ('psg-bisd-ungkapan-ketuakelas', 'sub-bahasa-indonesia-sd', 'Teks untuk soal nomor 1, 2, 3, dan 8', '<p><strong>Ketua Kelas Baru</strong></p><p>Pemilihan ketua kelas berlangsung Senin pagi. Dua nama diusulkan teman-teman, yaitu Galih dan Sekar. Keduanya berdiri di depan papan tulis.</p><p>Galih dikenal ringan tangan. Ia sering membantu piket walaupun bukan gilirannya. Sekar pandai berhitung dan rapi menulis. Keduanya sama-sama disukai teman sekelas.</p><p>Pemungutan suara berlangsung tertib. Suara terbanyak akhirnya jatuh kepada Galih. Sekar tersenyum lalu menyalami Galih.</p><p>Setelah terpilih, sikap Galih sempat berubah. Ia mulai memerintah teman-temannya. Ketika ditegur, ia menjawab dengan suara tinggi. “Jangan besar kepala, Lih,” bisik Sekar pelan.</p><p>Suatu pagi kelas kedapatan kotor saat penilaian kebersihan. Bu Guru bertanya siapa yang bertugas hari itu. Anak-anak diam seribu bahasa.</p><p>Galih akhirnya maju ke depan. Ia mengaku lupa mengatur jadwal piket. Bu Guru menasihatinya dengan kepala dingin.</p><p>Sejak hari itu Galih menempel jadwal di papan kelas. Nama petugas ditulis besar-besar agar terbaca. Ia juga ikut menyapu bersama regunya.</p>', 0),
  ('psg-bisd-ungkapan-sapu', 'sub-bahasa-indonesia-sd', 'Teks untuk soal nomor 4, 5, dan 9', '<p><strong>Sapu Ijuk Pak Warno</strong></p><p>Pak Warno membuat sapu ijuk di teras rumahnya. Ia mulai bekerja sejak pukul enam pagi. Ijuk diikat, dirapikan, lalu dipasangi gagang bambu. Dalam sehari ia dapat menyelesaikan dua puluh sapu.</p><p>Dahulu Pak Warno berjualan keliling kampung. Ia banting tulang agar anaknya tetap bersekolah. Kakinya menempuh puluhan kilometer setiap pekan.</p><p>Suatu tahun sapu plastik membanjiri pasar. Harganya jauh lebih murah daripada sapu ijuk. Banyak perajin sapu ijuk gulung tikar. Pak Warno pun hampir ikut berhenti.</p><p>Anaknya lalu mengunggah foto sapu itu ke media sosial. Tak disangka, sapu buatan Pak Warno naik daun. Pesanan berdatangan dari luar kota.</p><p>Kini banyak tamu singgah ke rumahnya. Mereka membawa pulang sapu kecil sebagai buah tangan. Pak Warno juga melatih pemuda kampung membuat sapu. Teras rumahnya berubah menjadi tempat belajar bersama.</p><p>“Ijuk itu awet dan ramah lingkungan,” katanya. Ia berharap kerajinan ini tidak punah.</p>', 1),
  ('psg-bisd-ungkapan-puisi', 'sub-bahasa-indonesia-sd', 'Puisi untuk soal nomor 6 dan 7', '<p><strong>Tangan Ibu</strong></p><p>Tangan ibu tidak pernah diam<br />Sejak ayam berkokok di ujung kampung<br />Ia membanting tulang tanpa mengeluh<br />Agar dapur kami tetap berasap</p><p>Ketika nilaiku turun<br />Ibu tidak lekas naik darah<br />Ia berbicara dengan kepala dingin<br />Sambil membetulkan letak kerah bajuku</p><p>Bila aku pulang membawa juara<br />Ibu hanya tersenyum tipis<br />“Jangan besar kepala,” katanya<br />“Masih panjang jalan di depanmu”</p><p>Aku menyimpan kata-kata itu<br />Seperti menyimpan buah tangan<br />Dari perjalanan yang belum selesai</p>', 2),
  ('psg-bisd-relevansi-puskesmas', 'sub-bahasa-indonesia-sd', 'Teks untuk soal nomor 1, 2, dan 10', '<p><strong>Bangku Panjang di Puskesmas</strong></p><p>Sabtu pagi Nia menemani ibunya ke puskesmas. Mereka berangkat naik angkutan umum. Mereka mengambil nomor antrean di meja depan. Nomor mereka dua puluh tiga.</p><p>Bangku panjang di ruang tunggu sudah penuh. Nia dan ibunya berdiri di dekat pintu. Beberapa orang tampak mengipasi wajahnya.</p><p>Tak lama kemudian seorang kakek datang. Ia berjalan pelan sambil memegang tongkat. Kakek itu berdiri di belakang antrean.</p><p>Nia menyenggol lengan ibunya. “Bu, kakek itu berdiri sejak tadi,” bisiknya.</p><p>Ibu Nia lalu menghampiri petugas. Petugas mengumumkan agar tempat duduk didahulukan untuk lansia. Seorang pemuda segera berdiri dari bangku. Kakek itu duduk sambil mengucapkan terima kasih.</p><p>Ketika nomor dua puluh tiga dipanggil, Nia mengantar ibunya masuk. Dokter memeriksa ibunya dengan sabar. Obat diambil di loket sebelah kanan.</p><p>Pulang dari puskesmas, ibu berkata pelan kepada Nia. “Menunggu memang tidak mudah. Namun, giliran orang lain tetap harus kita hormati.”</p>', 0),
  ('psg-bisd-relevansi-air', 'sub-bahasa-indonesia-sd', 'Teks untuk soal nomor 3, 4, 5, dan 8', '<p><strong>Menghemat Air pada Musim Kemarau</strong></p><p>Musim kemarau membuat sumur warga cepat surut. Di beberapa daerah, air bersih diambil dari tempat yang jauh. Karena itu, air perlu dipakai dengan hemat.</p><p>Cara pertama adalah menutup keran rapat-rapat. Keran yang menetes membuang air belasan liter setiap hari. Tetesan itu sering tidak disadari penghuni rumah.</p><p>Cara kedua adalah menampung air bekas cucian beras. Air itu masih dapat dipakai untuk menyiram tanaman.</p><p>Cara ketiga adalah mandi memakai gayung. Mandi dengan gayung memakai air lebih sedikit daripada berendam.</p><p>Cara keempat adalah memeriksa pipa yang bocor. Pipa bocor membuat air terbuang tanpa terlihat.</p><p>Sekolah juga dapat ikut membantu. Bak cuci tangan sebaiknya memakai keran kecil. Petugas kebersihan menyiram tanaman pada sore hari. Pada waktu itu air tidak cepat menguap.</p><p>Kebiasaan kecil ternyata berpengaruh besar. Bila semua warga ikut berhemat, sumur tidak cepat kering. Air yang dihemat hari ini berguna pada hari kering berikutnya.</p>', 1),
  ('psg-bisd-relevansi-listrik', 'sub-bahasa-indonesia-sd', 'Teks untuk soal nomor 6, 7, dan 9', '<p><strong>Ketika Listrik Padam</strong></p><p>Hujan deras mengguyur kampung sejak sore. Menjelang malam listrik tiba-tiba padam. Rumah-rumah pun menjadi gelap.</p><p>Pak RT berkeliling membawa senter. Ia mengetuk pintu satu per satu. Warga diminta berkumpul di pos ronda.</p><p>Ternyata ada dahan besar menimpa kabel. Dahan itu patah tertiup angin kencang. Beberapa bapak membawa gergaji dan tali. Mereka bekerja bergantian agar tidak kelelahan. Senter warga diarahkan ke dahan yang patah.</p><p>Ibu-ibu menyiapkan teh hangat di pos ronda. Anak-anak diminta menunggu di dalam rumah. Adi dan adiknya menyalakan lilin di teras.</p><p>Dahan berhasil disingkirkan sebelum tengah malam. Potongannya dipinggirkan ke tepi jalan. Petugas listrik datang lalu memperbaiki kabelnya. Lampu kampung akhirnya menyala kembali. Warga bertepuk tangan di pos ronda.</p><p>Sebelum pulang, Pak RT mengucapkan terima kasih. “Pekerjaan berat menjadi ringan bila dikerjakan bersama,” katanya.</p><p>Adi mengingat kalimat itu sampai keesokan harinya. Di sekolah, ia mengajak teman-temannya membersihkan selokan kelas.</p>', 2),
  ('psg-bisd-kesesuaian-poster', 'sub-bahasa-indonesia-sd', 'Teks untuk soal nomor 1, 2, 3, dan 8', '<p><strong>Poster di Depan Kelas</strong></p><p>Sebuah poster baru ditempel di depan kelas enam. Judulnya ditulis besar: “Cuci Tangan Sebelum Makan”. Kata “Cuci Tangan” dicetak dengan warna merah. Kata lainnya berwarna hitam.</p><p>Di bawah judul terdapat enam gambar berurutan. Gambar pertama menunjukkan tangan dibasahi air. Gambar kedua menunjukkan sabun dituang ke telapak. Gambar berikutnya menunjukkan jari-jari digosok bergantian. Gambar terakhir menunjukkan tangan dikeringkan dengan lap bersih.</p><p>Setiap gambar diberi nomor urut. Di bawah nomor ada tulisan pendek. Tulisan itu menjelaskan gerakan pada gambarnya.</p><p>Di sudut kanan bawah ada gambar kuman berwarna hijau. Kuman itu digambar sedang menjauh. Di sebelahnya tertulis “Kuman pergi, tubuh sehat”.</p><p>Bu Guru menjelaskan poster itu pada jam pertama. Anak-anak diminta mencobanya di keran depan kelas. Mereka mempraktikkan langkahnya satu per satu. Bu Guru mengingatkan agar sabun tidak dipakai berlebihan.</p><p>Sejak poster ditempel, antrean di keran menjadi lebih tertib.</p>', 0),
  ('psg-bisd-kesesuaian-perpustakaan', 'sub-bahasa-indonesia-sd', 'Teks untuk soal nomor 4, 5, 9, dan 10', '<p><strong>Catatan Kunjungan Perpustakaan</strong></p><p>Perpustakaan SD Melati mencatat jumlah pengunjung setiap hari. Catatan itu ditulis pada papan di dekat pintu. Setiap anak menuliskan namanya sebelum masuk. Petugas menghitung jumlahnya menjelang pulang sekolah.</p><p>Pada hari Senin pengunjungnya 25 anak. Hari Selasa naik menjadi 30 anak. Hari Rabu turun menjadi 18 anak. Hari Kamis kembali naik menjadi 32 anak. Hari Jumat tercatat paling banyak, yaitu 40 anak.</p><p>Hari Rabu menjadi hari dengan pengunjung paling sedikit. Pada hari itu ada latihan pramuka setelah pulang sekolah.</p><p>Hari Jumat perpustakaan mengadakan kegiatan membaca bersama. Kegiatan itu diikuti dua kelas sekaligus.</p><p>Buku cerita paling sering dipinjam. Buku pengetahuan berada di urutan kedua. Buku kamus jarang dipinjam karena hanya boleh dibaca di tempat.</p><p>Petugas perpustakaan menambah rak baru pada akhir bulan. Rak itu diisi buku cerita bergambar. Rak baru diletakkan di dekat jendela. Ruangan pun terasa lebih terang dan nyaman.</p>', 1),
  ('psg-bisd-kesesuaian-melati', 'sub-bahasa-indonesia-sd', 'Teks untuk soal nomor 6 dan 7', '<p><strong>Melati di Halaman Sekolah</strong></p><p>Halaman SD Melati ditanami bunga melati. Bunga itu ditanam di sepanjang pagar depan. Warnanya putih dan baunya harum.</p><p>Melati termasuk tanaman yang mudah dirawat. Tanaman ini cukup disiram sekali sehari. Pupuk kandang diberikan sebulan sekali. Ranting yang kering dipangkas agar tunas baru tumbuh. Rumput di sekitarnya juga dicabuti agar tidak berebut air.</p><p>Melati berbunga paling banyak pada musim hujan. Kuncupnya mekar menjelang pagi. Bau harumnya tercium sampai ke ruang guru. Bunga melati juga dipetik untuk mengisi vas di ruang kepala sekolah. Lapangan sekolah akan diperbaiki pada liburan mendatang.</p><p>Anak-anak kelas empat mendapat tugas merawat melati. Mereka menyiram bergiliran setiap pagi. Regu piket mencatat jadwal penyiraman pada buku kecil. Bu Guru memeriksa catatan itu setiap akhir pekan. Regu yang paling rajin mendapat pujian di depan kelas.</p><p>Halaman sekolah pun menjadi lebih asri. Tamu yang datang sering memuji keharumannya.</p>', 2),
  ('psg-bisd-emosi-sepeda', 'sub-bahasa-indonesia-sd', 'Teks untuk soal nomor 1, 2, dan 8', '<p><strong>Sepeda Tua di Gudang</strong></p><p>Sejak kecil aku sering diantar Kakek ke sekolah. Kakek memakai sepeda tuanya yang berwarna hijau. Boncengannya beralas karung goni yang tebal.</p><p>Setiap pagi Kakek bersiul sepanjang jalan. Ia berhenti di warung untuk membeli dua kue lapis. Satu untukku, satu untuk bekalnya sendiri.</p><p>Tahun lalu Kakek jatuh sakit. Sepeda hijau itu disimpan di gudang. Debu perlahan menutup sadelnya.</p><p>Bulan lalu Kakek pergi untuk selamanya. Rumah terasa sepi setiap pagi. Aku berangkat sekolah dengan langkah pelan.</p><p>Suatu sore aku membuka pintu gudang. Sepeda hijau itu masih berdiri di sudut. Aku mengelap sadelnya dengan kain basah. Debu di rangkanya luruh sedikit demi sedikit. Warna hijaunya kembali terlihat seperti dahulu.</p><p>Ayah datang lalu memasang rantai baru. “Sepeda ini masih kuat,” katanya pelan.</p><p>Keesokan paginya aku mengayuh sepeda itu ke sekolah. Angin pagi menerpa wajahku. Aku seperti mendengar siulan Kakek di belakangku.</p>', 0),
  ('psg-bisd-emosi-tenda', 'sub-bahasa-indonesia-sd', 'Teks untuk soal nomor 3, 4, 9, dan 10', '<p><strong>Suara di Balik Tenda</strong></p><p>Malam pertama perkemahan terasa panjang. Aku setenda dengan Fajar dan Bima. Lampu badai kami gantung di tiang tengah. Di luar, api unggun sudah lama padam. Hanya suara jangkrik yang terdengar dari kebun.</p><p>Menjelang tengah malam, terdengar suara gemerisik. Suara itu datang dari balik tenda. Bima menarik selimut sampai dagu.</p><p>“Mungkin hanya angin,” bisik Fajar. Namun, suara itu terdengar lagi dan makin dekat.</p><p>Jantungku berdegup kencang. Aku memegang senter dengan tangan gemetar. Fajar membuka resleting tenda perlahan-lahan.</p><p>Cahaya senter menyapu rumput di luar. Sepasang mata kecil memantulkan cahaya. Kami bertiga menahan napas sejenak. Ternyata seekor kucing kampung sedang mengais bungkus roti. Bulunya basah terkena embun malam.</p><p>Kami bertiga tertawa lega. Bima memberikan sisa rotinya kepada kucing itu. Kucing itu duduk di depan tenda sampai pagi.</p><p>Pagi harinya kami menceritakannya kepada Kak Pembina. “Perkemahan memang penuh kejutan,” katanya sambil tersenyum.</p>', 1),
  ('psg-bisd-emosi-puisi', 'sub-bahasa-indonesia-sd', 'Puisi untuk soal nomor 5, 6, dan 7', '<p><strong>Rumah Nenek</strong></p><p>Di ujung jalan berbatu itu<br />Ada rumah kayu berpintu biru<br />Setiap liburan aku ke sana<br />Menghitung ayam di halaman</p><p>Nenek menyambut di depan pintu<br />Tangannya wangi kayu manis<br />Dapurnya selalu hangat<br />Oleh air rebusan jahe</p><p>Kini liburan datang lagi<br />Tetapi aku tinggal jauh di kota<br />Rumah kayu itu masih ada<br />Dalam ingatan yang tak berdebu</p><p>Bila mataku terpejam<br />Aku mendengar deritan pintu biru<br />Dan suara nenek memanggil namaku<br />Dari dapur yang selalu hangat</p>', 2)
insert into public.misconceptions (id, label, description, insight) values
  ('mis-bisd-kosakata-001', 'Menebak makna kata dari bunyi yang mirip', 'Siswa mengira makna sebuah kata sama dengan kata lain yang bunyinya mirip, tanpa memeriksa kalimat tempat kata itu dipakai.', 'Bunyi yang mirip bukan bukti makna yang sama. Bacalah kalimat sebelum dan sesudahnya untuk melihat kata itu dipakai untuk apa.'),
  ('mis-bisd-kosakata-002', 'Menukar makna antarkata khusus dalam satu teks', 'Siswa memilih arti yang sebenarnya milik kata khusus lain yang muncul pada teks yang sama, misalnya arti pelek diberikan pada pentil.', 'Bila beberapa kata khusus muncul bersama, tandai masing-masing pada kalimatnya. Cocokkan arti dengan kata yang ditanyakan, bukan dengan kata di dekatnya.'),
  ('mis-bisd-kosakata-003', 'Menyamakan hasil dengan bahan atau alatnya', 'Siswa menyamakan kata khusus dengan bahan pembuatnya atau alat yang dipakai, misalnya kompos dianggap sama dengan sampah.', 'Bahan, alat, dan hasil adalah tiga hal berbeda. Perhatikan kata kerja pada kalimatnya: dibuat dari, dipakai untuk, atau menghasilkan.'),
  ('mis-bisd-kosakata-004', 'Menganggap semua kata dalam teks sebagai kata khusus', 'Karena teksnya membahas satu bidang, siswa menganggap seluruh katanya kata khusus, termasuk kata sehari-hari seperti kotak, jadwal, atau membayar.', 'Kata khusus hanya dipakai pada bidang tertentu. Kata yang biasa dipakai di mana saja tetap kata umum walaupun muncul di teks bidang tertentu.'),
  ('mis-bisd-kosakata-005', 'Memakai arti kamus tanpa melihat konteks', 'Siswa memilih arti yang paling sering ia dengar, padahal pada teks itu kata tersebut dipakai untuk hal yang berbeda.', 'Satu kata bisa berbeda arti pada bidang berbeda. Pastikan arti yang dipilih cocok dengan kalimat pada teks.'),
  ('mis-bisd-objek-001', 'Menebak benda hanya dari satu kata', 'Siswa langsung menyimpulkan nama benda begitu menemukan satu kata yang cocok, misalnya kata menumbuk, tanpa memeriksa ciri bentuk dan bahannya.', 'Kumpulkan dulu seluruh cirinya: bahan, bentuk, bagian, dan kegunaan. Nama benda yang tepat harus cocok dengan semua ciri itu, bukan hanya satu.'),
  ('mis-bisd-objek-002', 'Tertukar dengan benda lain pada teks yang sama', 'Siswa memilih nama benda lain yang juga digambarkan pada teks itu, misalnya menyebut dandang untuk gambaran tampah.', 'Bila satu teks menggambarkan beberapa benda, tandai tiap gambaran pada paragrafnya. Cocokkan pertanyaan dengan paragraf yang tepat.'),
  ('mis-bisd-objek-003', 'Menebak dari kebiasaan sendiri, bukan dari teks', 'Siswa menjawab dengan benda yang biasa ia pakai di rumah, padahal ciri pada teks menunjuk benda lain.', 'Pengalaman sendiri boleh membantu, tetapi jawabannya harus punya bukti kata di dalam teks.'),
  ('mis-bisd-objek-004', 'Mengira kata tentang keadaan sekitar sebagai ciri benda', 'Siswa memilih kata yang menggambarkan cuaca atau suasana, misalnya langit kelabu dan titik air, sebagai ciri benda yang ditanyakan.', 'Pisahkan kata yang menggambarkan bendanya sendiri dari kata yang menggambarkan keadaan di sekitarnya.'),
  ('mis-bisd-objek-005', 'Mengandalkan judul dan kesan umum teks', 'Siswa menjawab berdasarkan judul atau kesan keseluruhan teks, misalnya menjawab hujan karena judulnya menyebut musim hujan.', 'Judul memberi arah, tetapi jawabannya ditentukan larik atau kalimat yang menyebutkan ciri bendanya.'),
  ('mis-bisd-bagan-001', 'Menukar isi antarcabang bagan', 'Siswa meletakkan contoh milik satu kelompok ke cabang kelompok lain, misalnya botol plastik dimasukkan ke cabang sampah organik.', 'Sebelum mengisi bagan, tandai kalimat sumbernya. Setiap contoh harus berada di cabang yang kalimatnya menyebutkan contoh itu.'),
  ('mis-bisd-bagan-002', 'Menukar kelompok dengan contohnya', 'Siswa menaruh nama kelompok pada kotak contoh, atau sebaliknya, sehingga hubungan atas-bawah pada bagan menjadi terbalik.', 'Kotak di atas selalu berisi nama kelompok, kotak di bawahnya berisi anggota atau contohnya.'),
  ('mis-bisd-bagan-003', 'Menyusun langkah tidak sesuai urutan teks', 'Siswa menyusun bagan langkah menurut kebiasaannya sendiri, bukan menurut urutan yang ditulis pada teks.', 'Cari kata penanda urutan seperti langkah pertama, kedua, lalu, dan setelah itu. Urutan bagan mengikuti penanda tersebut.'),
  ('mis-bisd-bagan-004', 'Mencampur alat dengan bahan', 'Siswa memasukkan alat ke dalam daftar bahan atau sebaliknya, karena keduanya disebut berdekatan pada teks.', 'Bahan adalah yang habis atau berubah menjadi hasil; alat adalah yang dipakai berulang kali dan tetap utuh.'),
  ('mis-bisd-bagan-005', 'Memasukkan pendapat penulis ke dalam bagan fakta', 'Siswa memasukkan kalimat pendapat atau ajakan penulis ke dalam bagan yang seharusnya berisi kelompok, contoh, atau langkah.', 'Bagan menampung informasi yang dapat dikelompokkan. Kalimat pendapat, ajakan, dan simpulan penulis tidak punya tempat di dalamnya.'),
  ('mis-bisd-tersurat-001', 'Menjawab dari pengetahuan sendiri, bukan dari teks', 'Siswa memilih jawaban yang masuk akal menurut pengalamannya, padahal teks tidak menyebutkan hal itu.', 'Untuk soal informasi tersurat, jawabannya harus dapat ditunjuk kalimatnya. Bila kalimatnya tidak ada, jawaban itu salah walaupun terdengar masuk akal.'),
  ('mis-bisd-tersurat-002', 'Tertukar antartokoh atau antarpelaku', 'Siswa menukar siapa melakukan apa, misalnya perbuatan Pipi dianggap perbuatan Simut.', 'Bacalah kalimatnya secara utuh dan cari pelakunya di depan kata kerja. Nama yang disebut paling dekat belum tentu pelakunya.'),
  ('mis-bisd-tersurat-003', 'Tertukar antarangka dan antarwaktu', 'Siswa mengambil angka atau waktu lain yang juga muncul pada teks, misalnya waktu selesai dipakai sebagai waktu mulai.', 'Bila teks memuat beberapa angka, tandai masing-masing dengan keterangannya: mulai, selesai, panjang, atau jumlah.'),
  ('mis-bisd-tersurat-004', 'Mengubah sedikit isi teks lalu menganggapnya sama', 'Siswa menerima pernyataan yang menambahkan kata hanya, semua, atau selalu, padahal teks tidak membatasi sekeras itu.', 'Perhatikan kata hanya, semua, dan selalu. Satu kata seperti itu bisa membuat pernyataan menjadi tidak sesuai teks.'),
  ('mis-bisd-tersurat-005', 'Menganggap simpulan sendiri sebagai informasi tertulis', 'Siswa menganggap hal yang ia simpulkan dari teks sebagai kalimat yang tertulis di dalam teks.', 'Bedakan yang tertulis dari yang disimpulkan. Soal informasi tersurat hanya menanyakan yang benar-benar tertulis.'),
  ('mis-bisd-idepokok-001', 'Mengira kalimat pertama selalu ide pokok', 'Siswa langsung memilih kalimat pertama paragraf sebagai ide pokok tanpa memeriksa kalimat lain yang dijelaskannya.', 'Ide pokok adalah kalimat yang dijelaskan kalimat-kalimat lain. Letaknya bisa di awal, di tengah, atau di akhir paragraf.'),
  ('mis-bisd-idepokok-002', 'Memilih contoh atau rincian sebagai ide pokok', 'Siswa memilih kalimat berisi contoh, angka, atau nama sebagai ide pokok karena kalimat itu terasa paling jelas.', 'Contoh dan rincian justru mendukung ide pokok. Tanyakan: kalimat mana yang dijelaskan oleh contoh-contoh ini?'),
  ('mis-bisd-idepokok-003', 'Menyamakan amanat dengan peristiwa yang paling menarik', 'Siswa menyebut kejadian paling seru dalam cerita sebagai amanat, padahal amanat berupa pesan untuk pembaca.', 'Amanat berbentuk pesan atau ajakan bagi pembaca, bukan ringkasan kejadian. Tanyakan: apa yang penulis ingin kita lakukan?'),
  ('mis-bisd-idepokok-004', 'Menyimpulkan sifat tokoh dari perbuatan yang tidak berkaitan', 'Siswa menilai sifat tokoh dari perbuatan kecil yang tidak berhubungan dengan masalah cerita, misalnya menyebut hemat karena batal jajan.', 'Pilih perbuatan yang menjadi inti cerita. Sifat tokoh disimpulkan dari keputusannya saat menghadapi masalah.'),
  ('mis-bisd-idepokok-005', 'Menganggap ide pokok satu paragraf mewakili seluruh teks', 'Siswa menjadikan ide pokok salah satu paragraf sebagai ide pokok seluruh teks sehingga cakupannya terlalu sempit.', 'Ide pokok seluruh teks harus mencakup semua paragraf. Periksa apakah setiap paragraf dapat dimasukkan ke dalam kalimat pilihanmu.'),
  ('mis-bisd-perubahan-001', 'Menukar keadaan awal dengan keadaan akhir', 'Siswa membalik arah perubahan, misalnya menyebut jalan berubah dari aspal menjadi tanah berbatu.', 'Tandai dua keadaan itu dengan kata dahulu dan sekarang. Arah perubahan selalu dari keadaan lama menuju keadaan baru.'),
  ('mis-bisd-perubahan-002', 'Mengira kejadian terakhir sebagai penyebab perubahan', 'Siswa memilih kejadian yang muncul paling akhir sebagai penyebab, padahal kejadian itu justru akibat dari perubahannya.', 'Penyebab selalu terjadi lebih dahulu. Periksa urutan kejadiannya sebelum menentukan mana sebab dan mana akibat.'),
  ('mis-bisd-perubahan-003', 'Menyebut perubahan yang tidak ada dalam teks', 'Siswa menambahkan perubahan yang biasa terjadi menurut pengalamannya, padahal teks tidak menyebutkannya.', 'Setiap perubahan yang dipilih harus punya dua bukti dalam teks: keadaan sebelumnya dan keadaan sesudahnya.'),
  ('mis-bisd-perubahan-004', 'Mengira tokoh berubah hanya karena dinasihati', 'Siswa menyimpulkan tokoh berubah karena nasihat orang lain, padahal cerita menunjukkan tokoh berubah setelah mengalami akibat perbuatannya.', 'Cari peristiwa yang membuat tokoh merasakan akibatnya sendiri. Peristiwa itulah titik balik perubahannya.'),
  ('mis-bisd-perubahan-005', 'Mencampur perubahan benda dengan perubahan tempat', 'Siswa mencampur apa yang berubah pada benda dengan apa yang berubah pada tempat atau suasana di sekitarnya.', 'Tanyakan lebih dahulu: yang berubah bendanya, tokohnya, atau tempatnya? Baru cari buktinya di dalam teks.'),
  ('mis-bisd-ungkapan-001', 'Mengartikan ungkapan kata demi kata', 'Siswa mengartikan ungkapan menurut arti tiap katanya, misalnya besar kepala diartikan berkepala besar atau dapur berasap diartikan dapur penuh asap.', 'Ungkapan mempunyai makna baru yang tidak sama dengan arti kata-katanya. Ujilah pilihanmu dengan memasukkannya ke dalam kalimat aslinya.'),
  ('mis-bisd-ungkapan-002', 'Menukar makna ungkapan yang memakai kata sama', 'Siswa tertukar antara ungkapan yang memuat kata yang sama, misalnya besar kepala, keras kepala, dan kepala dingin.', 'Satu kata yang sama bisa membentuk ungkapan yang maknanya jauh berbeda. Ingat ungkapannya secara utuh, bukan sepotong.'),
  ('mis-bisd-ungkapan-003', 'Menebak makna dari suasana cerita', 'Siswa menebak makna ungkapan dari suasana atau perasaan tokoh di sekitarnya, bukan dari kalimat yang memuat ungkapan itu.', 'Bacalah kalimat sebelum dan sesudah ungkapan. Kalimat itulah yang menunjukkan maknanya, bukan suasana ceritanya secara umum.'),
  ('mis-bisd-ungkapan-004', 'Menyempitkan makna ungkapan pada satu kejadian', 'Siswa menyamakan makna ungkapan dengan satu kejadian tertentu dalam teks, sehingga maknanya menjadi terlalu sempit.', 'Makna ungkapan berlaku umum. Kejadian dalam teks hanya contoh pemakaiannya, bukan artinya.'),
  ('mis-bisd-ungkapan-005', 'Menganggap semua ungkapan bermakna baik', 'Siswa menganggap setiap ungkapan memuji, padahal sebagian ungkapan justru menyatakan sifat atau keadaan yang kurang baik.', 'Perhatikan bagaimana tokoh lain menanggapinya. Teguran atau bisikan pelan sering menandai ungkapan yang bermakna kurang baik.'),
  ('mis-bisd-relevansi-001', 'Memilih contoh yang hanya mirip tempatnya', 'Siswa memilih kejadian sehari-hari karena tempatnya sama dengan teks, misalnya sama-sama di sekolah, walaupun perbuatannya berbeda.', 'Yang dibandingkan adalah perbuatan dan nilainya, bukan tempatnya. Tanyakan: apakah perbuatannya sejalan dengan pesan teks?'),
  ('mis-bisd-relevansi-002', 'Memilih contoh yang berlawanan dengan pesan teks', 'Siswa memilih kejadian yang justru kebalikan dari pesan teks karena topiknya terasa berhubungan.', 'Periksa arah perbuatannya. Menyerobot antrean berhubungan dengan antre, tetapi arahnya berlawanan dengan pesan teks.'),
  ('mis-bisd-relevansi-003', 'Menilai perbuatan tanpa memakai isi teks', 'Siswa menilai baik atau buruk berdasarkan pendapat sendiri tanpa mencari bukti di dalam teks.', 'Penilaian boleh memakai pengalaman pribadi, tetapi tetap harus dapat dihubungkan dengan kejadian yang ada di dalam teks.'),
  ('mis-bisd-relevansi-004', 'Menganggap semua pernyataan benar sebagai alasan yang mendukung', 'Siswa menerima pernyataan yang memang benar, padahal pernyataan itu tidak menjelaskan pendapat yang sedang dibahas.', 'Alasan yang mendukung harus menjawab pertanyaan mengapa. Pernyataan benar yang tidak menjawabnya bukan alasan pendukung.'),
  ('mis-bisd-relevansi-005', 'Mengandalkan kebiasaan sendiri walaupun bertentangan dengan teks', 'Siswa memilih kebiasaan yang biasa ia lakukan di rumah walaupun teks menganjurkan hal yang berbeda.', 'Kebiasaan yang sudah biasa dilakukan belum tentu sesuai anjuran teks. Bandingkan kebiasaan itu dengan cara yang disarankan penulis.'),
  ('mis-bisd-kesesuaian-001', 'Menilai gambar dan warna hanya sebagai hiasan', 'Siswa menganggap gambar, nomor, atau warna pada poster hanya membuat tampilan menarik, tanpa melihat isi yang ingin ditegaskan.', 'Tanyakan apa yang menjadi jelas berkat unsur itu. Warna dan gambar pada teks informasi biasanya dipakai untuk menegaskan isi, bukan sekadar menghias.'),
  ('mis-bisd-kesesuaian-002', 'Menerima simpulan yang melebihi datanya', 'Siswa menerima simpulan bernada selalu, semua, atau setiap hari, padahal data pada teks tidak menunjukkan pola sekuat itu.', 'Cocokkan simpulan dengan seluruh angka, bukan hanya angka yang paling menonjol. Satu angka yang menyimpang sudah cukup untuk menolak simpulan.'),
  ('mis-bisd-kesesuaian-003', 'Menghubungkan dua informasi yang kebetulan berdekatan', 'Siswa menganggap dua kalimat saling menjelaskan hanya karena letaknya bersebelahan pada teks.', 'Dua informasi saling mendukung bila yang satu menjelaskan sebab atau bukti bagi yang lain, bukan sekadar berdekatan letaknya.'),
  ('mis-bisd-kesesuaian-004', 'Mengira kalimat yang benar pasti padu', 'Siswa mempertahankan sebuah kalimat karena isinya benar, padahal kalimat itu membahas hal lain di luar pokok paragrafnya.', 'Kalimat yang benar tetap tidak padu bila tidak membahas pokok yang sedang dibicarakan paragraf tersebut.'),
  ('mis-bisd-kesesuaian-005', 'Memilih judul berdasarkan satu kalimat saja', 'Siswa memilih judul dari satu kalimat yang menarik perhatian, sehingga judulnya tidak mewakili seluruh isi teks.', 'Judul yang sesuai harus mewakili sebagian besar paragraf. Uji dengan bertanya: apakah setiap paragraf masih cocok dengan judul itu?'),
  ('mis-bisd-emosi-001', 'Menebak perasaan dari satu kata saja', 'Siswa menebak perasaan tokoh atau pembaca dari satu kata yang menonjol, misalnya kata gelap atau malam, tanpa melihat kejadiannya.', 'Perasaan disimpulkan dari kejadian dan sikap tokoh, bukan dari satu kata. Bacalah kalimat sebelum dan sesudahnya.'),
  ('mis-bisd-emosi-002', 'Memakai kesan seluruh cerita untuk satu bagian', 'Siswa memakai perasaan terhadap keseluruhan cerita untuk menjawab pertanyaan tentang satu bagian tertentu.', 'Perhatikan bagian yang ditanyakan. Satu cerita bisa menegangkan di tengah, tetapi melegakan di akhir.'),
  ('mis-bisd-emosi-003', 'Memilih reaksi yang tidak didukung akhir cerita', 'Siswa memilih reaksi yang tidak sesuai dengan kejadian pada akhir cerita, misalnya sedih padahal ceritanya berakhir menyenangkan.', 'Setiap reaksi harus punya kalimat pendukung. Bila kejadiannya tidak ada di dalam teks, reaksi itu tidak tepat.'),
  ('mis-bisd-emosi-004', 'Mengartikan larik puisi secara harfiah', 'Siswa mengartikan larik puisi kata demi kata sehingga kesan yang ingin dibangun penyair menjadi hilang.', 'Tanyakan kesan apa yang muncul dari larik itu. Puisi memakai gambaran untuk menyampaikan perasaan.'),
  ('mis-bisd-emosi-005', 'Mengira cerita menegangkan pasti berakhir sedih', 'Siswa menduga akhir cerita dari suasana di tengah cerita, bukan dari kejadian yang benar-benar ditulis pada akhir teks.', 'Bacalah sampai kalimat terakhir. Ketegangan sering berakhir dengan kelegaan, bahkan dengan tawa.')
insert into public.questions (id, subject_id, topic_id, subtopic_id, concept_id, type, competency, difficulty, reasoning_type, content_format, passage_id, stimulus, question_text, instruction, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key, requires_visual, visual_prompt, visual_type) values
  ('bisd-kosakata-001', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-kosakata-umum-khusus', 'con-bi-sd-kosakata-umum-khusus', 'single', 'Mengidentifikasi makna kata khusus bidang pertanian dari konteks', 'dasar', 'pemahaman', 'html', 'psg-bisd-kosakata-kebun', null, '<p>Makna kata <strong>menyemai</strong> pada teks tersebut adalah ….</p>', 'Pilih satu jawaban.', '<p>Pada paragraf kedua tertulis: “Kegiatan pertama adalah menyemai benih bayam. Benih ditabur di kotak berisi tanah halus.” Setelah tujuh hari, benih itu menjadi bibit.</p><p>Jadi menyemai berarti menabur benih sampai tumbuh menjadi bibit.</p><p>Pilihan B adalah langkah berikutnya, yaitu memindahkan bibit ke bedeng. Pilihan D adalah panen. Keduanya kegiatan lain pada teks yang sama.</p>', '[{"key":"A","text":"<p>menabur benih agar tumbuh menjadi bibit</p>"},{"key":"B","text":"<p>memindahkan bibit ke petak tanah yang lebih luas</p>","misconceptionId":"mis-bisd-kosakata-002"},{"key":"C","text":"<p>menyiram tanaman muda setiap pagi</p>","misconceptionId":"mis-bisd-kosakata-001"},{"key":"D","text":"<p>memetik daun bayam yang masih segar</p>","misconceptionId":"mis-bisd-kosakata-002"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('bisd-kosakata-002', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-kosakata-umum-khusus', 'con-bi-sd-kosakata-umum-khusus', 'single', 'Mengidentifikasi makna kata khusus bidang pertanian dari konteks', 'dasar', 'pemahaman', 'html', 'psg-bisd-kosakata-kebun', null, '<p>Kata <strong>bedeng</strong> pada teks tersebut menunjuk pada ….</p>', 'Pilih satu jawaban.', '<p>Paragraf ketiga menyebutkan: “Bibit lalu dipindahkan ke bedeng. Bedeng dibuat memanjang dan sedikit meninggi.”</p><p>Jadi bedeng adalah petak tanah memanjang yang dibuat agak tinggi agar air tidak menggenang.</p><p>Pilihan A adalah tempat menyemai, dan pilihan C adalah tumpukan bahan kompos.</p>', '[{"key":"A","text":"<p>kotak berisi tanah halus untuk menabur benih</p>","misconceptionId":"mis-bisd-kosakata-002"},{"key":"B","text":"<p>petak tanah memanjang yang dibuat agak tinggi</p>"},{"key":"C","text":"<p>tumpukan daun kering yang dibiarkan tiga pekan</p>","misconceptionId":"mis-bisd-kosakata-003"},{"key":"D","text":"<p>tempat teduh untuk menyimpan bibit bayam</p>","misconceptionId":"mis-bisd-kosakata-001"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('bisd-kosakata-003', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-kosakata-umum-khusus', 'con-bi-sd-kosakata-umum-khusus', 'single', 'Memilih kata umum yang mewakili kata khusus dalam teks', 'menengah', 'penerapan', 'html', 'psg-bisd-kosakata-kebun', null, '<p>Kata <strong>kompos</strong> pada teks tersebut termasuk kata khusus. Kata umum yang tepat untuk menggantikannya adalah ….</p>', 'Pilih satu jawaban.', '<p>Teks menyebut “Kompos menyuburkan tanah tanpa membeli pupuk pabrik”. Artinya kompos adalah salah satu jenis pupuk.</p><p>Pupuk adalah kata umum, sedangkan kompos adalah kata khusus untuk pupuk dari bahan yang membusuk.</p><p>Pilihan D keliru karena daun kering dan sisa sayur baru bahan pembuatnya, bukan komposnya sendiri.</p>', '[{"key":"A","text":"<p>tanah</p>","misconceptionId":"mis-bisd-kosakata-005"},{"key":"B","text":"<p>benih</p>","misconceptionId":"mis-bisd-kosakata-002"},{"key":"C","text":"<p>pupuk</p>"},{"key":"D","text":"<p>sampah</p>","misconceptionId":"mis-bisd-kosakata-003"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('bisd-kosakata-004', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-kosakata-umum-khusus', 'con-bi-sd-kosakata-umum-khusus', 'single', 'Mengidentifikasi makna kata khusus bidang kesehatan', 'menengah', 'penerapan', 'html', 'psg-bisd-kosakata-posyandu', null, '<p>Makna kata <strong>imunisasi</strong> pada teks tersebut adalah ….</p>', 'Pilih satu jawaban.', '<p>Imunisasi diberikan bidan di meja kelima. Imunisasi adalah pemberian vaksin supaya tubuh anak tahan terhadap penyakit tertentu.</p><p>Pilihan A terjadi di meja kedua dan pilihan B di meja ketiga. Pilihan C memang disebut teks, tetapi vitamin A bukan imunisasi.</p>', '[{"key":"A","text":"<p>penimbangan berat badan balita setiap bulan</p>","misconceptionId":"mis-bisd-kosakata-002"},{"key":"B","text":"<p>pencatatan pertumbuhan anak pada sebuah kartu</p>","misconceptionId":"mis-bisd-kosakata-002"},{"key":"C","text":"<p>pemberian vitamin A kepada bayi setiap bulan</p>","misconceptionId":"mis-bisd-kosakata-005"},{"key":"D","text":"<p>pemberian vaksin agar tubuh tahan terhadap penyakit</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('bisd-kosakata-005', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-kosakata-umum-khusus', 'con-bi-sd-kosakata-umum-khusus', 'single', 'Mengidentifikasi makna kata dari kegiatan yang digambarkan teks', 'menengah', 'penerapan', 'html', 'psg-bisd-kosakata-posyandu', null, '<p>Makna kata <strong>penyuluhan</strong> pada teks tersebut adalah ….</p>', 'Pilih satu jawaban.', '<p>Setelah kata penyuluhan, teks menulis: “Petugas menjelaskan menu sehat untuk balita.” Kegiatannya adalah menjelaskan, bukan membagikan atau memeriksa.</p><p>Jadi penyuluhan berarti pemberian penjelasan agar warga memahami sesuatu.</p><p>Pilihan B keliru karena teks hanya menyebut menunya dijelaskan, bukan dibagikan.</p>', '[{"key":"A","text":"<p>pemberian penjelasan agar warga memahami sesuatu</p>"},{"key":"B","text":"<p>pembagian makanan bergizi untuk anak balita</p>","misconceptionId":"mis-bisd-kosakata-003"},{"key":"C","text":"<p>pemeriksaan kesehatan balita oleh bidan desa</p>","misconceptionId":"mis-bisd-kosakata-002"},{"key":"D","text":"<p>pendaftaran nama anak pada buku besar</p>","misconceptionId":"mis-bisd-kosakata-001"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('bisd-kosakata-006', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-kosakata-umum-khusus', 'con-bi-sd-kosakata-umum-khusus', 'single', 'Mengidentifikasi makna kata khusus bidang perbengkelan dalam teks fiksi', 'menengah', 'penerapan', 'html', 'psg-bisd-kosakata-bengkel', null, '<p>Makna kata <strong>pelek</strong> pada cerita tersebut adalah ….</p>', 'Pilih satu jawaban.', '<p>Cerita menyebut “pelek roda yang berkilau”, lalu jari-jari roda disebut terpisah pada kalimat berikutnya.</p><p>Pelek adalah lingkaran logam pada roda, tempat ban dipasang.</p><p>Pilihan A adalah jari-jari, pilihan C adalah kunci pas, dan pilihan D adalah pentil. Ketiganya kata khusus lain yang muncul di cerita yang sama.</p>', '[{"key":"A","text":"<p>batang tipis yang menghubungkan poros dengan lingkar roda</p>","misconceptionId":"mis-bisd-kosakata-002"},{"key":"B","text":"<p>lingkaran logam pada roda, tempat ban dipasang</p>"},{"key":"C","text":"<p>alat besi untuk melonggarkan dan mengencangkan baut</p>","misconceptionId":"mis-bisd-kosakata-002"},{"key":"D","text":"<p>lubang kecil pada ban untuk memasukkan angin</p>","misconceptionId":"mis-bisd-kosakata-002"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('bisd-kosakata-007', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-kosakata-umum-khusus', 'con-bi-sd-kosakata-umum-khusus', 'single', 'Menalar makna satu kata yang dipakai untuk dua benda berbeda', 'lanjut', 'penalaran', 'html', 'psg-bisd-kosakata-bengkel', null, '<p>Kata <strong>kendur</strong> dipakai Pak Rusdi untuk rantai dan juga untuk jari-jari roda. Apa maksud kata itu pada kedua bagian tersebut?</p>', 'Pilih satu jawaban.', '<p>Setelah rantai disebut kendur, Pak Rusdi menarik roda ke belakang sampai “rantai pun kembali tegang”. Berarti kendur adalah lawan dari tegang, yaitu longgar.</p><p>Pada jari-jari, kendur diketahui dari bunyi ketukan yang berbeda. Jari-jari yang kendur berarti kurang tegang.</p><p>Pilihan B keliru karena rantai hanya lepas, bukan putus, dan tidak ada jari-jari yang patah.</p>', '[{"key":"A","text":"<p>Rantai yang kotor dan jari-jari yang berkarat.</p>","misconceptionId":"mis-bisd-kosakata-001"},{"key":"B","text":"<p>Rantai yang putus dan jari-jari yang patah.</p>","misconceptionId":"mis-bisd-kosakata-005"},{"key":"C","text":"<p>Rantai yang longgar dan jari-jari yang kurang tegang.</p>"},{"key":"D","text":"<p>Rantai yang terlalu panjang dan jari-jari yang terlalu pendek.</p>","misconceptionId":"mis-bisd-kosakata-005"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('bisd-kosakata-008', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-kosakata-umum-khusus', 'con-bi-sd-kosakata-umum-khusus', 'mcma', 'Memilah kata khusus bidang kesehatan dari kata umum', 'menengah', 'penerapan', 'html', 'psg-bisd-kosakata-posyandu', null, '<p>Kata mana saja pada teks tersebut yang merupakan kata khusus bidang kesehatan?</p>', 'Klik pada setiap pilihan jawaban benar! Jawaban benar lebih dari satu.', '<p>Imunisasi dan bidan hanya dipakai pada bidang kesehatan, jadi keduanya kata khusus.</p><p>Buku besar dipakai di banyak tempat, misalnya di koperasi atau di toko, sehingga tetap kata umum walaupun muncul pada teks kesehatan.</p>', '[{"key":"A","text":"<p>imunisasi</p>"},{"key":"B","text":"<p>bidan</p>"},{"key":"C","text":"<p>buku besar</p>","misconceptionId":"mis-bisd-kosakata-004"}]'::jsonb, null, array['A', 'B'], null, null, 'A, B', false, null, null),
  ('bisd-kosakata-009', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-kosakata-umum-khusus', 'con-bi-sd-kosakata-umum-khusus', 'mcma', 'Menalar kalimat yang memuat kosakata khusus satu bidang', 'lanjut', 'penalaran', 'html', 'psg-bisd-kosakata-bengkel', null, '<p>Kalimat mana saja pada cerita tersebut yang memakai kata khusus bidang perbengkelan?</p>', 'Klik pada setiap pilihan jawaban benar! Jawaban benar lebih dari satu.', '<p>Kunci pas dan pentil adalah nama alat dan bagian sepeda yang hanya dipakai di bengkel, jadi keduanya kata khusus.</p><p>Kalimat A hanya memakai kata sehari-hari: membayar, ongkos, dan perbaikan. Kata-kata itu dipakai di banyak bidang lain.</p>', '[{"key":"A","text":"<p>Ayah membayar ongkos perbaikan.</p>","misconceptionId":"mis-bisd-kosakata-004"},{"key":"B","text":"<p>Pak Rusdi mengambil kunci pas dari kotak kayu.</p>"},{"key":"C","text":"<p>Pentilnya diperiksa dengan air sabun.</p>"}]'::jsonb, null, array['B', 'C'], null, null, 'B, C', false, null, null),
  ('bisd-kosakata-010', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-kosakata-umum-khusus', 'con-bi-sd-kosakata-umum-khusus', 'category', 'Mengelompokkan kata menjadi kosakata umum dan kosakata khusus', 'lanjut', 'penalaran', 'html', null, '<p>Berikut beberapa kalimat yang diambil dari ketiga teks di atas. Kata yang dicetak tebal akan dikelompokkan menjadi kosakata umum atau kosakata khusus.</p>', '<p>Tentukan kosakata umum atau kosakata khusus untuk setiap kata yang dicetak tebal berikut!</p>', 'Klik pada pilihan Kosakata Umum atau Kosakata Khusus untuk setiap kalimat.', '<p>Kader dan pelek hanya dipakai pada bidang tertentu. Kader dipakai di bidang kesehatan masyarakat, pelek di bidang perbengkelan. Keduanya kosakata khusus.</p><p>Jadwal dan dibagikan dipakai di mana saja: di sekolah, di rumah, maupun di kantor. Keduanya tetap kosakata umum walaupun muncul pada teks bidang tertentu.</p>', null, null, null, '[{"key":"U","label":"Kosakata Umum"},{"key":"K","label":"Kosakata Khusus"}]'::jsonb, '[{"id":"p1","text":"<p>Di meja ketiga, <strong>kader</strong> mengisi grafik pada kartu itu.</p>","correctCategoryKey":"K"},{"id":"p2","text":"<p>Aku memperhatikan <strong>pelek</strong> roda yang berkilau.</p>","correctCategoryKey":"K"},{"id":"p3","text":"<p>Kami pun membuat <strong>jadwal</strong> menyiram bergiliran.</p>","correctCategoryKey":"U","misconceptionId":"mis-bisd-kosakata-004"},{"id":"p4","text":"<p>Hasilnya <strong>dibagikan</strong> kepada guru dan penjaga sekolah.</p>","correctCategoryKey":"U","misconceptionId":"mis-bisd-kosakata-004"}]'::jsonb, 'p1: K; p2: K; p3: U; p4: U', false, null, null),
  ('bisd-objek-001', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-objek-kosakata', 'con-bi-sd-objek-kosakata', 'single', 'Mengidentifikasi objek dari gambaran bentuk dan kegunaannya', 'dasar', 'pemahaman', 'html', 'psg-bisd-objek-gudang', null, '<p>Benda kayu memanjang berlubang beserta batang kayu di sampingnya pada cerita tersebut adalah ….</p>', 'Pilih satu jawaban.', '<p>Cirinya: terbuat dari kayu, memanjang, bagian tengahnya berlubang seperti perahu kecil, dan dipakai menumbuk padi. Benda itu bernama lesung, sedangkan batang kayu penumbuknya bernama alu.</p><p>Cobek dan ulekan terbuat dari batu dan berbentuk bundar, jadi tidak cocok dengan ciri kayu memanjang.</p>', '[{"key":"A","text":"<p>cobek dan ulekan</p>","misconceptionId":"mis-bisd-objek-001"},{"key":"B","text":"<p>lesung dan alu</p>"},{"key":"C","text":"<p>dandang dan tutupnya</p>","misconceptionId":"mis-bisd-objek-002"},{"key":"D","text":"<p>kentongan dan pemukulnya</p>","misconceptionId":"mis-bisd-objek-002"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('bisd-objek-002', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-objek-kosakata', 'con-bi-sd-objek-kosakata', 'single', 'Mengidentifikasi objek dari bahan, bentuk, dan bunyinya', 'menengah', 'penerapan', 'html', 'psg-bisd-objek-gudang', null, '<p>Bambu berlubang yang tergantung di dinding gudang itu adalah ….</p>', 'Pilih satu jawaban.', '<p>Bambu itu berlubang memanjang di satu sisi, dipukul dengan kayu, dan bunyinya dipakai memanggil warga berkumpul. Benda dengan ciri seperti itu bernama kentongan.</p><p>Seruling ditiup, angklung digoyang, dan bedug terbuat dari kayu besar berlapis kulit. Ketiganya tidak cocok dengan ciri pada teks.</p>', '[{"key":"A","text":"<p>seruling</p>","misconceptionId":"mis-bisd-objek-001"},{"key":"B","text":"<p>angklung</p>","misconceptionId":"mis-bisd-objek-003"},{"key":"C","text":"<p>kentongan</p>"},{"key":"D","text":"<p>bedug</p>","misconceptionId":"mis-bisd-objek-001"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('bisd-objek-003', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-objek-kosakata', 'con-bi-sd-objek-kosakata', 'single', 'Mengidentifikasi objek dari bahan dan kegunaannya', 'menengah', 'penerapan', 'html', 'psg-bisd-objek-gudang', null, '<p>Wadah tembaga berbentuk kerucut terbalik pada cerita tersebut adalah ….</p>', 'Pilih satu jawaban.', '<p>Wadah itu terbuat dari tembaga, berbentuk kerucut terbalik, dan dipakai mengukus nasi sehingga uap panas keluar dari mulutnya. Benda itu bernama dandang.</p><p>Kuali dipakai menggoreng, tempayan menyimpan air, dan cerek merebus air. Ketiganya bukan alat mengukus.</p>', '[{"key":"A","text":"<p>kuali</p>","misconceptionId":"mis-bisd-objek-003"},{"key":"B","text":"<p>tempayan</p>","misconceptionId":"mis-bisd-objek-001"},{"key":"C","text":"<p>cerek</p>","misconceptionId":"mis-bisd-objek-003"},{"key":"D","text":"<p>dandang</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('bisd-objek-004', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-objek-kosakata', 'con-bi-sd-objek-kosakata', 'single', 'Mengidentifikasi objek dari cara kerjanya pada teks informasi', 'menengah', 'penerapan', 'html', 'psg-bisd-objek-pasar', null, '<p>Alat yang dipakai pedagang sayur pada teks tersebut adalah ….</p>', 'Pilih satu jawaban.', '<p>Alat pedagang sayur digambarkan berlengan dua: barang di lengan kiri, bandul besi di lengan kanan, dan lengan mendatar bila beratnya sama. Alat itu adalah neraca dengan anak timbangan.</p><p>Pilihan B dipakai pedagang buah, pilihan C dipakai pedagang beras, dan pilihan D dipakai pedagang ikan.</p>', '[{"key":"A","text":"<p>neraca dengan bandul besi sebagai anak timbangan</p>"},{"key":"B","text":"<p>timbangan gantung yang berpapan angka</p>","misconceptionId":"mis-bisd-objek-002"},{"key":"C","text":"<p>takaran kaleng seukuran satu liter</p>","misconceptionId":"mis-bisd-objek-002"},{"key":"D","text":"<p>wadah anyaman bambu yang lebar dan bundar</p>","misconceptionId":"mis-bisd-objek-002"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('bisd-objek-005', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-objek-kosakata', 'con-bi-sd-objek-kosakata', 'single', 'Menyebutkan nama objek yang digambarkan teks informasi', 'menengah', 'penerapan', 'html', 'psg-bisd-objek-pasar', null, '<p>Wadah yang dipakai pedagang ikan pada teks tersebut biasa disebut ….</p>', 'Pilih satu jawaban.', '<p>Teks menyebut wadah itu terbuat dari anyaman bambu, lebar, bundar, dan tidak dalam. Wadah dengan ciri seperti itu bernama tampah.</p><p>Pilihan A, C, dan D adalah wadah yang memang sering dipakai pedagang, tetapi cirinya tidak disebut di dalam teks.</p>', '[{"key":"A","text":"<p>keranjang tinggi bertutup rapat</p>","misconceptionId":"mis-bisd-objek-003"},{"key":"B","text":"<p>tampah lebar dari anyaman bambu</p>"},{"key":"C","text":"<p>karung besar dari kain plastik</p>","misconceptionId":"mis-bisd-objek-003"},{"key":"D","text":"<p>kotak kayu berisi pecahan es</p>","misconceptionId":"mis-bisd-objek-003"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('bisd-objek-006', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-objek-kosakata', 'con-bi-sd-objek-kosakata', 'single', 'Mengidentifikasi objek yang dibicarakan dalam puisi', 'menengah', 'penerapan', 'html', 'psg-bisd-objek-puisi', null, '<p>Benda apa yang dibicarakan pada puisi tersebut?</p>', 'Pilih satu jawaban.', '<p>Puisi menyebut benda itu terlipat di sudut lemari, berangka besi ramping, berkain lebar, bergagang, dan berdiri di atas kepala saat hujan. Ciri-ciri itu menunjuk pada payung.</p><p>Jas hujan dipakai di badan dan tidak bergagang. Hujan adalah keadaan yang menyebabkan benda itu dipakai, bukan bendanya.</p>', '[{"key":"A","text":"<p>Jas hujan.</p>","misconceptionId":"mis-bisd-objek-003"},{"key":"B","text":"<p>Hujan.</p>","misconceptionId":"mis-bisd-objek-005"},{"key":"C","text":"<p>Payung.</p>"},{"key":"D","text":"<p>Topi.</p>","misconceptionId":"mis-bisd-objek-001"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('bisd-objek-007', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-objek-kosakata', 'con-bi-sd-objek-kosakata', 'single', 'Menalar larik yang menjadi penciri utama objek', 'lanjut', 'penalaran', 'html', 'psg-bisd-objek-puisi', null, '<p>Pasangan larik mana yang paling membantu pembaca mengenali benda pada puisi tersebut?</p>', 'Pilih satu jawaban.', '<p>Kedua larik pada pilihan D menyebut bagian bendanya sendiri, yaitu kain yang terbentang dan gagang yang digenggam. Bagian itulah penciri payung.</p><p>Pilihan A dan B menggambarkan keadaan cuaca dan jalan, sedangkan pilihan C menggambarkan akibat memakainya. Ketiganya tidak menyebut bagian bendanya.</p>', '[{"key":"A","text":"<p>“Menunggu langit berubah kelabu” dan “Bila titik air mulai berjatuhan”.</p>","misconceptionId":"mis-bisd-objek-004"},{"key":"B","text":"<p>“Jalan berubah menjadi cermin panjang” dan “Sepatuku basah di tepiannya”.</p>","misconceptionId":"mis-bisd-objek-004"},{"key":"C","text":"<p>“Namun bahuku tetap kering” dan “Ketika hujan reda”.</p>","misconceptionId":"mis-bisd-objek-005"},{"key":"D","text":"<p>“Kainmu terbentang seperti sayap kelelawar” dan “Aku menggenggam gagangmu erat”.</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('bisd-objek-008', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-objek-kosakata', 'con-bi-sd-objek-kosakata', 'mcma', 'Mengelompokkan objek menurut kegunaannya dalam teks', 'menengah', 'penerapan', 'html', 'psg-bisd-objek-gudang', null, '<p>Benda mana saja di gudang Nenek yang dipakai untuk mengolah atau memasak makanan?</p>', 'Klik pada setiap pilihan jawaban benar! Jawaban benar lebih dari satu.', '<p>Lesung dipakai menumbuk padi menjadi beras dan dandang dipakai mengukus nasi. Keduanya berhubungan dengan mengolah makanan.</p><p>Bambu panjang di dinding adalah kentongan. Bunyinya dipakai memanggil warga, bukan untuk mengolah makanan.</p>', '[{"key":"A","text":"<p>Benda kayu memanjang tempat padi ditumbuk.</p>"},{"key":"B","text":"<p>Bambu panjang yang tergantung di dinding.</p>","misconceptionId":"mis-bisd-objek-001"},{"key":"C","text":"<p>Wadah tembaga berbentuk kerucut terbalik.</p>"}]'::jsonb, null, array['A', 'C'], null, null, 'A, C', false, null, null),
  ('bisd-objek-009', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-objek-kosakata', 'con-bi-sd-objek-kosakata', 'mcma', 'Menalar larik yang menunjukkan keadaan objek', 'lanjut', 'penalaran', 'html', 'psg-bisd-objek-puisi', null, '<p>Larik mana saja yang menunjukkan benda itu sedang tidak dipakai?</p>', 'Klik pada setiap pilihan jawaban benar! Jawaban benar lebih dari satu.', '<p>Kata terlipat dan menunggu menunjukkan benda itu tersimpan dan belum dipakai. Larik A menggambarkan keadaan sebelum hujan, larik C sesudah hujan reda.</p><p>Larik B justru menggambarkan saat benda itu sedang dipakai di atas kepala.</p>', '[{"key":"A","text":"<p>“Kau terlipat diam di sudut lemari”.</p>"},{"key":"B","text":"<p>“Lalu kau terlipat lagi, menunggu”.</p>"},{"key":"C","text":"<p>“Kau berdiri di atas kepalaku”.</p>","misconceptionId":"mis-bisd-objek-004"}]'::jsonb, null, array['A', 'B'], null, null, 'A, B', false, null, null),
  ('bisd-objek-010', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-objek-kosakata', 'con-bi-sd-objek-kosakata', 'category', 'Menilai kecocokan nama benda dengan gambarannya dalam teks', 'lanjut', 'penalaran', 'html', null, '<p>Beni menulis catatan tentang benda-benda pada teks “Sore di Gudang Nenek” dan “Alat-Alat di Pasar Pagi”. Ia memasangkan nama benda dengan gambarannya.</p>', '<p>Tentukan sesuai atau tidak sesuai untuk setiap pasangan nama benda dan gambarannya berikut!</p>', 'Klik pada pilihan Sesuai atau Tidak Sesuai untuk setiap pernyataan.', '<p>P1 sesuai: batang kayu sebesar lengan di samping lesung memang alu.</p><p>P2 tidak sesuai: wadah tembaga berbentuk kerucut terbalik adalah dandang. Kentongan terbuat dari bambu.</p><p>P3 tidak sesuai: pelita adalah lampu berbahan bakar minyak. Alat takar beras seukuran satu liter adalah takaran kaleng.</p><p>P4 sesuai: wadah pedagang ikan yang lebar dan tidak dalam adalah tampah.</p>', null, null, null, '[{"key":"S","label":"Sesuai"},{"key":"T","label":"Tidak Sesuai"}]'::jsonb, '[{"id":"p1","text":"<p>Alu — batang kayu sebesar lengan untuk menumbuk padi.</p>","correctCategoryKey":"S"},{"id":"p2","text":"<p>Kentongan — wadah tembaga berbentuk kerucut terbalik.</p>","correctCategoryKey":"T","misconceptionId":"mis-bisd-objek-002"},{"id":"p3","text":"<p>Pelita — alat takar beras seukuran satu liter.</p>","correctCategoryKey":"T","misconceptionId":"mis-bisd-objek-002"},{"id":"p4","text":"<p>Tampah — wadah anyaman bambu yang lebar, bundar, dan tidak dalam.</p>","correctCategoryKey":"S"}]'::jsonb, 'p1: S; p2: T; p3: T; p4: S', false, null, null),
  ('bisd-bagan-001', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-ikhtisar-bagan', 'con-bi-sd-ikhtisar-bagan', 'single', 'Memilih bagan yang sesuai dengan pengelompokan pada teks', 'dasar', 'pemahaman', 'html', 'psg-bisd-bagan-sampah', null, '<p>Bagan mana yang sesuai untuk menggambarkan informasi pada teks tersebut?</p>', 'Pilih satu jawaban.', '<p>Teks membagi sampah menjadi dua kelompok, lalu menyebut contoh dan cara mengolah tiap kelompok. Bagan C memuat keduanya dengan tepat.</p><p>Bagan A hanya memuat satu kelompok sehingga isinya belum lengkap. Bagan B menukar isi kedua kelompok, sedangkan bagan D memakai ciri sebagai nama kelompok dengan contoh yang tertukar.</p>', '[{"key":"A","text":"<p>Sampah</p><ul><li>Sampah organik: sisa sayur, kulit buah, daun kering; mudah membusuk; diolah menjadi kompos</li></ul>","misconceptionId":"mis-bisd-bagan-002"},{"key":"B","text":"<p>Sampah</p><ul><li>Sampah organik: botol plastik, kaleng, pecahan kaca; sulit membusuk; didaur ulang</li><li>Sampah anorganik: sisa sayur, kulit buah, daun kering; mudah membusuk; diolah menjadi kompos</li></ul>","misconceptionId":"mis-bisd-bagan-001"},{"key":"C","text":"<p>Sampah</p><ul><li>Sampah organik: sisa sayur, kulit buah, daun kering; mudah membusuk; diolah menjadi kompos</li><li>Sampah anorganik: botol plastik, kaleng, pecahan kaca; sulit membusuk; didaur ulang</li></ul>"},{"key":"D","text":"<p>Sampah</p><ul><li>Mudah membusuk: botol plastik, kaleng, pecahan kaca; dikumpulkan di bank sampah</li><li>Sulit membusuk: sisa sayur, kulit buah, daun kering; diolah menjadi kompos</li></ul>","misconceptionId":"mis-bisd-bagan-001"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('bisd-bagan-002', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-ikhtisar-bagan', 'con-bi-sd-ikhtisar-bagan', 'single', 'Melengkapi cabang bagan dengan informasi dari teks', 'menengah', 'penerapan', 'html', 'psg-bisd-bagan-sampah', null, '<p>Perhatikan bagan berikut.</p><p>Sampah anorganik</p><ul><li>Ciri: sulit membusuk</li><li>Contoh: botol plastik, kaleng, pecahan kaca</li><li>Penanganan di sekolah: ….</li></ul><p>Bagian yang rumpang pada bagan tersebut sebaiknya diisi dengan ….</p>', 'Pilih satu jawaban.', '<p>Paragraf kelima menyebut penanganan sampah anorganik di sekolah: “Sampah anorganik dikumpulkan di bank sampah. Hasil penjualannya menjadi kas kelas.”</p><p>Pilihan A adalah penanganan sampah organik. Pilihan C benar terjadi di sekolah, tetapi berlaku untuk semua sampah, bukan khusus cabang anorganik.</p>', '[{"key":"A","text":"<p>diolah menjadi kompos di lubang belakang</p>","misconceptionId":"mis-bisd-bagan-001"},{"key":"B","text":"<p>dibuang ke tempat sampah di dapur rumah</p>","misconceptionId":"mis-bisd-bagan-001"},{"key":"C","text":"<p>dipisahkan oleh petugas piket setiap hari</p>","misconceptionId":"mis-bisd-bagan-002"},{"key":"D","text":"<p>dikumpulkan di bank sampah lalu dijual</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('bisd-bagan-003', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-ikhtisar-bagan', 'con-bi-sd-ikhtisar-bagan', 'single', 'Menyusun bagan urutan langkah sesuai teks prosedur', 'menengah', 'penerapan', 'html', 'psg-bisd-bagan-telur', null, '<p>Bagan urutan yang tepat untuk pembuatan telur asin pada teks tersebut adalah ….</p>', 'Pilih satu jawaban.', '<p>Teks memakai penanda urutan: langkah pertama mencuci dan menggosok telur, langkah kedua membuat adonan garam dan abu gosok, langkah ketiga membalut telur, langkah keempat menyimpannya selama dua pekan.</p><p>Pilihan lain memindahkan langkah ke tempat yang salah, misalnya membalut telur sebelum adonannya dibuat.</p>', '[{"key":"A","text":"<p>mencuci dan menggosok telur &rarr; membuat adonan garam &rarr; membalut telur &rarr; menyimpan dua pekan</p>"},{"key":"B","text":"<p>membuat adonan garam &rarr; mencuci dan menggosok telur &rarr; menyimpan dua pekan &rarr; membalut telur</p>","misconceptionId":"mis-bisd-bagan-003"},{"key":"C","text":"<p>mencuci dan menggosok telur &rarr; membalut telur &rarr; membuat adonan garam &rarr; merebus telur</p>","misconceptionId":"mis-bisd-bagan-003"},{"key":"D","text":"<p>membuat adonan garam &rarr; membalut telur &rarr; menggosok telur dengan amplas &rarr; menyimpan dua pekan</p>","misconceptionId":"mis-bisd-bagan-003"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('bisd-bagan-004', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-ikhtisar-bagan', 'con-bi-sd-ikhtisar-bagan', 'single', 'Memisahkan bahan dan alat saat menyusun bagan', 'menengah', 'penerapan', 'html', 'psg-bisd-bagan-telur', null, '<p>Kotak <strong>Bahan</strong> pada bagan pembuatan telur asin sebaiknya berisi ….</p>', 'Pilih satu jawaban.', '<p>Teks memisahkan keduanya: bahan berupa telur bebek, garam, abu gosok, dan air; alat berupa baskom, amplas halus, dan wadah tertutup.</p><p>Pilihan A seluruhnya alat. Pilihan C dan D mencampur bahan dengan alat.</p>', '[{"key":"A","text":"<p>baskom, amplas halus, dan wadah tertutup</p>","misconceptionId":"mis-bisd-bagan-004"},{"key":"B","text":"<p>telur bebek, garam, abu gosok, dan air</p>"},{"key":"C","text":"<p>telur bebek, amplas halus, dan baskom</p>","misconceptionId":"mis-bisd-bagan-004"},{"key":"D","text":"<p>garam, air, dan wadah tertutup</p>","misconceptionId":"mis-bisd-bagan-004"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('bisd-bagan-005', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-ikhtisar-bagan', 'con-bi-sd-ikhtisar-bagan', 'single', 'Menyusun ikhtisar yang mewakili seluruh isi teks', 'menengah', 'penerapan', 'html', 'psg-bisd-bagan-kelapa', null, '<p>Ikhtisar yang tepat untuk teks tersebut adalah ….</p>', 'Pilih satu jawaban.', '<p>Teks membahas kegunaan daun, batang, buah, dan akar. Ikhtisar harus mewakili keempatnya sekaligus.</p><p>Pilihan A dan B hanya mewakili satu bagian saja, sedangkan pilihan D mengangkat kalimat penutup yang bukan isi utama teks.</p>', '[{"key":"A","text":"<p>Pohon kelapa tumbuh subur di tepi pantai dan akarnya menahan pasir pantai.</p>","misconceptionId":"mis-bisd-bagan-002"},{"key":"B","text":"<p>Daun kelapa muda dan daun tua dipakai membuat ketupat, atap gubuk, dan sapu.</p>","misconceptionId":"mis-bisd-bagan-002"},{"key":"C","text":"<p>Hampir seluruh bagian pohon kelapa, dari daun hingga akar, dapat dimanfaatkan warga.</p>"},{"key":"D","text":"<p>Warga pantai merawat pohon kelapa dengan telaten agar tetap tumbuh dan berbuah.</p>","misconceptionId":"mis-bisd-bagan-005"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('bisd-bagan-006', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-ikhtisar-bagan', 'con-bi-sd-ikhtisar-bagan', 'single', 'Menemukan bagian bagan yang tidak sesuai isi teks', 'lanjut', 'penalaran', 'html', 'psg-bisd-bagan-kelapa', null, '<p>Rani membuat bagan berikut untuk cabang <strong>Buah kelapa</strong>.</p><ul><li>air kelapa &rarr; minuman segar</li><li>daging buah &rarr; santan</li><li>tempurung &rarr; gayung</li><li>sabut &rarr; arang</li></ul><p>Pasangan yang keliru pada bagan tersebut adalah ….</p>', 'Pilih satu jawaban.', '<p>Teks menyebut “Tempurungnya dibuat menjadi gayung dan arang. Sabutnya dijadikan keset dan tali.”</p><p>Jadi arang berasal dari tempurung, bukan dari sabut. Pasangan sabut &rarr; arang keliru, sedangkan tiga pasangan lainnya sudah tepat.</p>', '[{"key":"A","text":"<p>air kelapa &rarr; minuman segar</p>","misconceptionId":"mis-bisd-bagan-001"},{"key":"B","text":"<p>daging buah &rarr; santan</p>","misconceptionId":"mis-bisd-bagan-001"},{"key":"C","text":"<p>tempurung &rarr; gayung</p>","misconceptionId":"mis-bisd-bagan-001"},{"key":"D","text":"<p>sabut &rarr; arang</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('bisd-bagan-007', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-ikhtisar-bagan', 'con-bi-sd-ikhtisar-bagan', 'single', 'Menalar informasi yang tidak dapat dimasukkan ke dalam bagan', 'lanjut', 'penalaran', 'html', 'psg-bisd-bagan-sampah', null, '<p>Bagian teks yang <strong>tidak dapat</strong> dimasukkan ke dalam bagan pengelompokan sampah adalah ….</p>', 'Pilih satu jawaban.', '<p>Bagan pengelompokan menampung ciri, contoh, dan cara pengolahan tiap kelompok. Pilihan B, C, dan D termasuk ketiganya.</p><p>Kalimat “Memisahkan sampah tampak sepele” adalah pendapat penulis. Kalimat itu tidak menjelaskan kelompok mana pun sehingga tidak punya tempat dalam bagan.</p>', '[{"key":"A","text":"<p>Memisahkan sampah tampak sepele.</p>"},{"key":"B","text":"<p>Sampah organik dapat diolah menjadi kompos.</p>","misconceptionId":"mis-bisd-bagan-005"},{"key":"C","text":"<p>Contoh sampah anorganik adalah botol plastik.</p>","misconceptionId":"mis-bisd-bagan-005"},{"key":"D","text":"<p>Sampah anorganik masih dapat didaur ulang.</p>","misconceptionId":"mis-bisd-bagan-005"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('bisd-bagan-008', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-ikhtisar-bagan', 'con-bi-sd-ikhtisar-bagan', 'mcma', 'Memilih isi kotak alat pada bagan teks prosedur', 'menengah', 'penerapan', 'html', 'psg-bisd-bagan-telur', null, '<p>Apa saja yang tepat diletakkan pada kotak <strong>Alat</strong> dalam bagan pembuatan telur asin?</p>', 'Klik pada setiap pilihan jawaban benar! Jawaban benar lebih dari satu.', '<p>Teks menyebut alatnya berupa baskom, amplas halus, dan wadah tertutup. Ketiganya dipakai berulang kali dan tetap utuh setelah dipakai.</p><p>Abu gosok dicampur garam menjadi adonan pembalut telur, jadi abu gosok termasuk bahan.</p>', '[{"key":"A","text":"<p>Abu gosok.</p>","misconceptionId":"mis-bisd-bagan-004"},{"key":"B","text":"<p>Amplas halus.</p>"},{"key":"C","text":"<p>Wadah tertutup.</p>"}]'::jsonb, null, array['B', 'C'], null, null, 'B, C', false, null, null),
  ('bisd-bagan-009', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-ikhtisar-bagan', 'con-bi-sd-ikhtisar-bagan', 'mcma', 'Mengisi cabang bagan dengan hasil yang tepat', 'menengah', 'penerapan', 'html', 'psg-bisd-bagan-kelapa', null, '<p>Apa saja yang tepat diisikan pada cabang <strong>Daun</strong> dalam bagan pohon kelapa?</p>', 'Klik pada setiap pilihan jawaban benar! Jawaban benar lebih dari satu.', '<p>Janur adalah daun kelapa yang muda, dan lidi adalah tulang daunnya. Keduanya berada di cabang Daun.</p><p>Tiang rumah dan bangku dibuat dari batang kelapa, jadi tempatnya di cabang Batang.</p>', '[{"key":"A","text":"<p>Hiasan dan ketupat dari janur.</p>"},{"key":"B","text":"<p>Tiang rumah dan bangku.</p>","misconceptionId":"mis-bisd-bagan-001"},{"key":"C","text":"<p>Sapu dari lidi.</p>"}]'::jsonb, null, array['A', 'C'], null, null, 'A, C', false, null, null),
  ('bisd-bagan-010', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-ikhtisar-bagan', 'con-bi-sd-ikhtisar-bagan', 'category', 'Menilai ketepatan penempatan informasi dalam bagan', 'lanjut', 'penalaran', 'html', 'psg-bisd-bagan-kelapa', null, '<p>Doni menyusun bagan pohon kelapa dengan empat cabang: Daun, Batang, Buah, dan Akar. Tentukan tepat atau tidak tepat penempatan berikut!</p>', 'Klik pada pilihan Tepat atau Tidak Tepat untuk setiap pernyataan.', '<p>P1 tidak tepat: lidi adalah tulang daun, jadi sapu lidi masuk cabang Daun.</p><p>P2 tepat: santan berasal dari daging buah kelapa.</p><p>P3 tepat: teks menyebut batang dipakai membuat jembatan kecil.</p><p>P4 tidak tepat: keset dibuat dari sabut, yaitu bagian buah. Akar hanya disebut sebagai penahan pasir.</p>', null, null, null, '[{"key":"T","label":"Tepat"},{"key":"X","label":"Tidak Tepat"}]'::jsonb, '[{"id":"p1","text":"<p>Sapu lidi diletakkan pada cabang Batang.</p>","correctCategoryKey":"X","misconceptionId":"mis-bisd-bagan-001"},{"id":"p2","text":"<p>Santan diletakkan pada cabang Buah.</p>","correctCategoryKey":"T"},{"id":"p3","text":"<p>Jembatan kecil diletakkan pada cabang Batang.</p>","correctCategoryKey":"T"},{"id":"p4","text":"<p>Keset diletakkan pada cabang Akar.</p>","correctCategoryKey":"X","misconceptionId":"mis-bisd-bagan-001"}]'::jsonb, 'p1: X; p2: T; p3: T; p4: X', false, null, null),
  ('bisd-tersurat-001', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-informasi-tersurat', 'con-bi-sd-informasi-tersurat', 'single', 'Mengidentifikasi pelaku suatu perbuatan dalam teks fiksi', 'dasar', 'pemahaman', 'html', 'psg-bisd-tersurat-semut', null, '<p>Siapa yang menjatuhkan daun lebar ke dekat Simut?</p>', 'Pilih satu jawaban.', '<p>Paragraf ketiga menulis: “Ia segera memetik daun yang lebar. Daun itu dijatuhkan tepat di dekat Simut.” Kata <em>ia</em> menunjuk burung pipit yang bernama Pipi.</p><p>Angin memang disebut pada paragraf kedua, tetapi angin hanya menggoyang batang kayu.</p>', '[{"key":"A","text":"<p>Simut.</p>","misconceptionId":"mis-bisd-tersurat-002"},{"key":"B","text":"<p>Pemburu.</p>","misconceptionId":"mis-bisd-tersurat-002"},{"key":"C","text":"<p>Angin kencang.</p>","misconceptionId":"mis-bisd-tersurat-001"},{"key":"D","text":"<p>Pipi.</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('bisd-tersurat-002', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-informasi-tersurat', 'con-bi-sd-informasi-tersurat', 'single', 'Mengidentifikasi perbuatan tokoh yang tertulis dalam teks', 'dasar', 'pemahaman', 'html', 'psg-bisd-tersurat-semut', null, '<p>Apa yang dilakukan Simut untuk menolong Pipi?</p>', 'Pilih satu jawaban.', '<p>Paragraf keempat menulis: “Ia berlari cepat lalu menggigit kaki pemburu.”</p><p>Yang berteriak justru pemburu, dan yang menjatuhkan daun adalah Pipi. Merusak jaring tidak pernah disebut di dalam cerita.</p>', '[{"key":"A","text":"<p>Menggigit kaki pemburu.</p>"},{"key":"B","text":"<p>Berteriak memanggil burung lain.</p>","misconceptionId":"mis-bisd-tersurat-002"},{"key":"C","text":"<p>Menjatuhkan daun yang lebar.</p>","misconceptionId":"mis-bisd-tersurat-002"},{"key":"D","text":"<p>Merusak jaring milik pemburu.</p>","misconceptionId":"mis-bisd-tersurat-001"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('bisd-tersurat-003', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-informasi-tersurat', 'con-bi-sd-informasi-tersurat', 'single', 'Menemukan keterangan tempat yang tertulis dalam teks informasi', 'menengah', 'penerapan', 'html', 'psg-bisd-tersurat-kereta', null, '<p>Di mana pencangkulan pertama pembangunan jalur kereta dilakukan?</p>', 'Pilih satu jawaban.', '<p>Paragraf kedua menulis: “Pencangkulan pertama dilakukan di Desa Kemijen, Semarang.”</p><p>Tanggung adalah ujung jalur pertama, sedangkan Jawa Timur baru dibangun setelah jalur pertama selesai.</p>', '[{"key":"A","text":"<p>Di Tanggung.</p>","misconceptionId":"mis-bisd-tersurat-002"},{"key":"B","text":"<p>Di Desa Kemijen, Semarang.</p>"},{"key":"C","text":"<p>Di pelabuhan Semarang.</p>","misconceptionId":"mis-bisd-tersurat-001"},{"key":"D","text":"<p>Di Jawa Timur.</p>","misconceptionId":"mis-bisd-tersurat-002"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('bisd-tersurat-004', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-informasi-tersurat', 'con-bi-sd-informasi-tersurat', 'single', 'Menemukan keterangan waktu yang tertulis dalam teks informasi', 'menengah', 'penerapan', 'html', 'psg-bisd-tersurat-kereta', null, '<p>Kapan jalur Semarang–Tanggung mulai dipakai?</p>', 'Pilih satu jawaban.', '<p>Paragraf ketiga menulis: “Jalur itu mulai dipakai pada 10 Agustus 1867.” Pembangunannya sendiri dimulai pada tahun 1864.</p><p>Pilihan A menukar waktu mulai dibangun dengan waktu mulai dipakai. Pilihan B dan D memuat tahun yang tidak disebut teks.</p>', '[{"key":"A","text":"<p>Pada tahun 1864, saat pembangunannya dimulai.</p>","misconceptionId":"mis-bisd-tersurat-003"},{"key":"B","text":"<p>Pada tahun 1865, setelah rel dipasang seluruhnya.</p>","misconceptionId":"mis-bisd-tersurat-001"},{"key":"C","text":"<p>Pada 10 Agustus 1867, tiga tahun setelah dibangun.</p>"},{"key":"D","text":"<p>Pada tahun 1870, setelah jalur Sumatra selesai.</p>","misconceptionId":"mis-bisd-tersurat-003"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('bisd-tersurat-005', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-informasi-tersurat', 'con-bi-sd-informasi-tersurat', 'single', 'Menemukan rincian barang yang disebut teks informasi', 'menengah', 'penerapan', 'html', 'psg-bisd-tersurat-kereta', null, '<p>Hasil bumi apa yang diangkut kereta pertama ke pelabuhan?</p>', 'Pilih satu jawaban.', '<p>Paragraf keempat menulis: “Hasil bumi berupa gula dan kopi diangkut ke pelabuhan.”</p><p>Tiga pilihan lain memang hasil bumi Indonesia, tetapi tidak disebutkan pada teks ini.</p>', '[{"key":"A","text":"<p>Beras dan jagung.</p>","misconceptionId":"mis-bisd-tersurat-001"},{"key":"B","text":"<p>Teh dan tembakau.</p>","misconceptionId":"mis-bisd-tersurat-001"},{"key":"C","text":"<p>Karet dan kelapa.</p>","misconceptionId":"mis-bisd-tersurat-001"},{"key":"D","text":"<p>Gula dan kopi.</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('bisd-tersurat-006', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-informasi-tersurat', 'con-bi-sd-informasi-tersurat', 'single', 'Menemukan waktu kegiatan pada teks cerita', 'menengah', 'penerapan', 'html', 'psg-bisd-tersurat-layangan', null, '<p>Pukul berapa lomba layang-layang dimulai?</p>', 'Pilih satu jawaban.', '<p>Teks menulis: “Pukul delapan pagi lomba dimulai.”</p><p>Pukul sepuluh adalah waktu acara selesai, sedangkan pukul tujuh dan pukul sembilan tidak disebut sama sekali.</p>', '[{"key":"A","text":"<p>Pukul delapan pagi.</p>"},{"key":"B","text":"<p>Pukul sembilan pagi.</p>","misconceptionId":"mis-bisd-tersurat-003"},{"key":"C","text":"<p>Pukul sepuluh pagi.</p>","misconceptionId":"mis-bisd-tersurat-003"},{"key":"D","text":"<p>Pukul tujuh pagi.</p>","misconceptionId":"mis-bisd-tersurat-003"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('bisd-tersurat-007', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-informasi-tersurat', 'con-bi-sd-informasi-tersurat', 'single', 'Menemukan peristiwa yang dialami tokoh dalam teks', 'menengah', 'penerapan', 'html', 'psg-bisd-tersurat-layangan', null, '<p>Apa yang terjadi pada layang-layang Rangga saat lomba berlangsung?</p>', 'Pilih satu jawaban.', '<p>Teks menulis: “Namun, benangnya tersangkut dahan pohon. Rangga menarik benang itu perlahan agar tidak putus.”</p><p>Jadi benangnya tersangkut, tetapi tidak putus. Pilihan A mengubah isi teks hanya pada satu kata.</p>', '[{"key":"A","text":"<p>Benangnya putus tertiup angin timur.</p>","misconceptionId":"mis-bisd-tersurat-004"},{"key":"B","text":"<p>Benangnya tersangkut dahan pohon.</p>"},{"key":"C","text":"<p>Kertasnya robek terkena ranting.</p>","misconceptionId":"mis-bisd-tersurat-001"},{"key":"D","text":"<p>Layang-layangnya jatuh ke tengah lapangan.</p>","misconceptionId":"mis-bisd-tersurat-001"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('bisd-tersurat-008', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-informasi-tersurat', 'con-bi-sd-informasi-tersurat', 'mcma', 'Menemukan beberapa peristiwa tersurat yang dialami tokoh', 'menengah', 'penerapan', 'html', 'psg-bisd-tersurat-semut', null, '<p>Peristiwa apa saja yang dialami Simut menurut cerita tersebut?</p>', 'Klik pada setiap pilihan jawaban benar! Jawaban benar lebih dari satu.', '<p>Kedua peristiwa itu tertulis pada paragraf kedua dan ketiga: Simut terjatuh ke sungai, lalu naik ke atas daun dan terbawa ke tepi.</p><p>Jaring memang dibawa pemburu, tetapi tidak ada tokoh yang terjerat jaring di dalam cerita.</p>', '[{"key":"A","text":"<p>Terjatuh ke dalam sungai.</p>"},{"key":"B","text":"<p>Naik ke atas daun lalu terbawa ke tepi.</p>"},{"key":"C","text":"<p>Terjerat jaring milik pemburu.</p>","misconceptionId":"mis-bisd-tersurat-001"}]'::jsonb, null, array['A', 'B'], null, null, 'A, B', false, null, null),
  ('bisd-tersurat-009', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-informasi-tersurat', 'con-bi-sd-informasi-tersurat', 'mcma', 'Memilah pernyataan yang benar-benar tertulis pada teks', 'lanjut', 'penalaran', 'html', 'psg-bisd-tersurat-layangan', null, '<p>Informasi apa saja tentang lomba tersebut yang tertulis pada teks?</p>', 'Klik pada setiap pilihan jawaban benar! Jawaban benar lebih dari satu.', '<p>Kalimat “Lomba tersebut diadakan setiap bulan Agustus” dan “Hadiahnya berupa buku tulis dan tas sekolah” tertulis apa adanya pada teks.</p><p>Peserta dibagi menjadi dua kelompok, bukan tiga. Pernyataan A hanya mengubah satu kata, tetapi isinya menjadi tidak sesuai.</p>', '[{"key":"A","text":"<p>Peserta dibagi menjadi tiga kelompok.</p>","misconceptionId":"mis-bisd-tersurat-004"},{"key":"B","text":"<p>Lomba diadakan setiap bulan Agustus.</p>"},{"key":"C","text":"<p>Hadiahnya berupa buku tulis dan tas sekolah.</p>"}]'::jsonb, null, array['B', 'C'], null, null, 'B, C', false, null, null),
  ('bisd-tersurat-010', 'sub-bahasa-indonesia-sd', 'top-bi-sd-tekstual', 'st-bi-sd-informasi-tersurat', 'con-bi-sd-informasi-tersurat', 'category', 'Menilai kesesuaian pernyataan dengan informasi tersurat', 'lanjut', 'penalaran', 'html', 'psg-bisd-tersurat-kereta', null, '<p>Rani mencatat beberapa hal setelah membaca teks tersebut. Tentukan sesuai atau tidak sesuai untuk setiap catatannya!</p>', 'Klik pada pilihan Sesuai atau Tidak Sesuai untuk setiap pernyataan.', '<p>P1 tidak sesuai: teks menyebut panjangnya kira-kira dua puluh enam kilometer.</p><p>P2 sesuai: tertulis pada paragraf ketiga.</p><p>P3 sesuai: tertulis pada paragraf pertama.</p><p>P4 tidak sesuai: kereta pertama menarik gerbong barang dan gerbong penumpang. Kata <em>hanya</em> membuat pernyataan itu menyempit dan keliru.</p>', null, null, null, '[{"key":"S","label":"Sesuai"},{"key":"T","label":"Tidak Sesuai"}]'::jsonb, '[{"id":"p1","text":"<p>Panjang jalur pertama kira-kira lima puluh kilometer.</p>","correctCategoryKey":"T","misconceptionId":"mis-bisd-tersurat-003"},{"id":"p2","text":"<p>Jalur kereta pertama menghubungkan Semarang dan Tanggung.</p>","correctCategoryKey":"S"},{"id":"p3","text":"<p>Pembangunan jalur pertama dimulai pada tahun 1864.</p>","correctCategoryKey":"S"},{"id":"p4","text":"<p>Kereta pertama hanya mengangkut penumpang.</p>","correctCategoryKey":"T","misconceptionId":"mis-bisd-tersurat-004"}]'::jsonb, 'p1: T; p2: S; p3: S; p4: T', false, null, null),
  ('bisd-idepokok-001', 'sub-bahasa-indonesia-sd', 'top-bi-sd-inferensial', 'st-bi-sd-ide-pokok', 'con-bi-sd-ide-pokok', 'single', 'Menyimpulkan amanat cerita', 'dasar', 'pemahaman', 'html', 'psg-bisd-idepokok-kotakpensil', null, '<p>Apa amanat cerita tersebut?</p>', 'Pilih satu jawaban.', '<p>Seluruh cerita bergerak dari satu keputusan Rani: mengembalikan kotak pensil yang ia temukan, walaupun sempat tergoda uang di dalamnya.</p><p>Pilihan B dan C hanya kejadian pendukung. Pilihan D salah alamat karena Rani batal jajan bukan untuk berhemat, melainkan karena uang itu bukan miliknya.</p>', '[{"key":"A","text":"<p>Kembalikanlah barang yang bukan milik kita.</p>"},{"key":"B","text":"<p>Simpanlah barang berharga di tempat yang aman.</p>","misconceptionId":"mis-bisd-idepokok-003"},{"key":"C","text":"<p>Bertanyalah kepada guru bila menghadapi masalah.</p>","misconceptionId":"mis-bisd-idepokok-003"},{"key":"D","text":"<p>Berhematlah agar uang jajan tidak cepat habis.</p>","misconceptionId":"mis-bisd-idepokok-004"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('bisd-idepokok-002', 'sub-bahasa-indonesia-sd', 'top-bi-sd-inferensial', 'st-bi-sd-ide-pokok', 'con-bi-sd-ide-pokok', 'single', 'Menyimpulkan sifat tokoh dari perbuatannya', 'menengah', 'penerapan', 'html', 'psg-bisd-idepokok-kotakpensil', null, '<p>Bagaimana sifat Rani berdasarkan cerita tersebut?</p>', 'Pilih satu jawaban.', '<p>Rani menemukan kotak berisi uang, sempat ragu, lalu menyerahkannya ke ruang guru. Perbuatan itu menunjukkan sifat jujur.</p><p>Teks tidak menyebut Rani membereskan meja setiap hari, dan yang bertanya di depan kelas adalah Bu Sinta, bukan Rani.</p>', '[{"key":"A","text":"<p>Rajin, karena ia membereskan meja setiap hari.</p>","misconceptionId":"mis-bisd-idepokok-004"},{"key":"B","text":"<p>Pemberani, karena ia berbicara di depan kelas.</p>","misconceptionId":"mis-bisd-idepokok-004"},{"key":"C","text":"<p>Jujur, karena ia mengembalikan barang temuannya.</p>"},{"key":"D","text":"<p>Hemat, karena ia tidak jadi membeli bakso.</p>","misconceptionId":"mis-bisd-idepokok-004"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('bisd-idepokok-003', 'sub-bahasa-indonesia-sd', 'top-bi-sd-inferensial', 'st-bi-sd-ide-pokok', 'con-bi-sd-ide-pokok', 'single', 'Menyimpulkan ide pokok sebuah paragraf', 'menengah', 'penerapan', 'html', 'psg-bisd-idepokok-lebah', null, '<p>Apa ide pokok paragraf kedua teks tersebut?</p>', 'Pilih satu jawaban.', '<p>Paragraf kedua menceritakan lebah mencari nektar, serbuk sari menempel di kakinya, lalu terbawa ke bunga lain. Seluruh kalimatnya menjelaskan cara lebah memindahkan serbuk sari.</p><p>Pilihan A adalah ide paragraf pertama dan pilihan C ide paragraf keempat. Pilihan D adalah akibat yang dibahas paragraf ketiga.</p>', '[{"key":"A","text":"<p>Lebah sering ditakuti manusia karena sengatnya.</p>","misconceptionId":"mis-bisd-idepokok-005"},{"key":"B","text":"<p>Cara lebah membawa serbuk sari antarbunga.</p>"},{"key":"C","text":"<p>Jumlah lebah di ladang semakin berkurang.</p>","misconceptionId":"mis-bisd-idepokok-005"},{"key":"D","text":"<p>Petani dapat memanen buah lebih banyak.</p>","misconceptionId":"mis-bisd-idepokok-002"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('bisd-idepokok-004', 'sub-bahasa-indonesia-sd', 'top-bi-sd-inferensial', 'st-bi-sd-ide-pokok', 'con-bi-sd-ide-pokok', 'single', 'Menentukan gagasan pendukung dalam paragraf', 'menengah', 'penerapan', 'html', 'psg-bisd-idepokok-lebah', null, '<p>Gagasan pendukung pada paragraf keempat teks tersebut adalah ….</p>', 'Pilih satu jawaban.', '<p>Ide pokok paragraf keempat adalah jumlah lebah semakin berkurang. Kalimat tentang racun hama menjelaskan penyebab berkurangnya lebah, jadi kalimat itulah gagasan pendukungnya.</p><p>Pilihan A, B, dan C berada di paragraf lain sehingga tidak mendukung ide pokok paragraf keempat.</p>', '[{"key":"A","text":"<p>Lebah mencari makan berupa nektar bunga.</p>","misconceptionId":"mis-bisd-idepokok-005"},{"key":"B","text":"<p>Penyerbukan membuat bunga berubah menjadi buah.</p>","misconceptionId":"mis-bisd-idepokok-005"},{"key":"C","text":"<p>Warga dapat menanam bunga di halaman rumah.</p>","misconceptionId":"mis-bisd-idepokok-005"},{"key":"D","text":"<p>Racun hama yang berlebihan ikut membunuh lebah.</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('bisd-idepokok-005', 'sub-bahasa-indonesia-sd', 'top-bi-sd-inferensial', 'st-bi-sd-ide-pokok', 'con-bi-sd-ide-pokok', 'single', 'Menyimpulkan ide pokok seluruh teks', 'lanjut', 'penalaran', 'html', 'psg-bisd-idepokok-lebah', null, '<p>Ide pokok seluruh teks tersebut adalah ….</p>', 'Pilih satu jawaban.', '<p>Teks membahas jasa lebah bagi tanaman, ancaman yang membuat lebah berkurang, lalu cara menjaganya. Kalimat pada pilihan A mencakup ketiganya.</p><p>Pilihan B hanya mewakili satu paragraf. Pilihan C terlalu sempit karena teks juga menyebut cara lain, sedangkan pilihan D tidak dibahas teks.</p>', '[{"key":"A","text":"<p>Lebah berjasa bagi tanaman sehingga perlu dijaga.</p>"},{"key":"B","text":"<p>Lebah mengumpulkan nektar dari bunga-bunga liar.</p>","misconceptionId":"mis-bisd-idepokok-005"},{"key":"C","text":"<p>Petani sebaiknya berhenti memakai racun hama.</p>","misconceptionId":"mis-bisd-idepokok-002"},{"key":"D","text":"<p>Bunga di halaman rumah membuat kebun terlihat asri.</p>","misconceptionId":"mis-bisd-idepokok-002"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('bisd-idepokok-006', 'sub-bahasa-indonesia-sd', 'top-bi-sd-inferensial', 'st-bi-sd-ide-pokok', 'con-bi-sd-ide-pokok', 'single', 'Menyimpulkan nilai yang terkandung dalam cerita', 'menengah', 'penerapan', 'html', 'psg-bisd-idepokok-bakulkue', null, '<p>Nilai apa yang tampak dari perbuatan Dimas dan teman-temannya?</p>', 'Pilih satu jawaban.', '<p>Dimas dan teman-temannya melihat kesulitan Bu Sari, lalu mengumpulkan uang jajan dan membeli kue yang masih kering. Perbuatan itu menunjukkan kepedulian terhadap orang lain.</p><p>Kejujuran, kedisiplinan, dan kesabaran tidak menjadi inti persoalan pada cerita ini.</p>', '[{"key":"A","text":"<p>Kejujuran.</p>","misconceptionId":"mis-bisd-idepokok-004"},{"key":"B","text":"<p>Kedisiplinan.</p>","misconceptionId":"mis-bisd-idepokok-004"},{"key":"C","text":"<p>Kepedulian.</p>"},{"key":"D","text":"<p>Kesabaran.</p>","misconceptionId":"mis-bisd-idepokok-004"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('bisd-idepokok-007', 'sub-bahasa-indonesia-sd', 'top-bi-sd-inferensial', 'st-bi-sd-ide-pokok', 'con-bi-sd-ide-pokok', 'single', 'Menentukan peristiwa yang menjadi awal masalah cerita', 'lanjut', 'penalaran', 'html', 'psg-bisd-idepokok-bakulkue', null, '<p>Peristiwa yang menjadi awal masalah pada cerita tersebut adalah ….</p>', 'Pilih satu jawaban.', '<p>Masalah cerita muncul ketika bakul kue terjatuh sehingga sebagian kue basah dan Bu Sari tidak memperoleh uang.</p><p>Pilihan A dan D adalah keadaan sebelum masalah muncul, sedangkan pilihan C adalah usaha menyelesaikan masalah.</p>', '[{"key":"A","text":"<p>Bu Sari datang ke sekolah membawa payung besar.</p>","misconceptionId":"mis-bisd-idepokok-003"},{"key":"B","text":"<p>Bakul kue Bu Sari terjatuh ke genangan air.</p>"},{"key":"C","text":"<p>Dimas mengajak teman-temannya berkumpul.</p>","misconceptionId":"mis-bisd-idepokok-003"},{"key":"D","text":"<p>Anak-anak membeli kue sebelum bel berbunyi.</p>","misconceptionId":"mis-bisd-idepokok-003"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('bisd-idepokok-008', 'sub-bahasa-indonesia-sd', 'top-bi-sd-inferensial', 'st-bi-sd-ide-pokok', 'con-bi-sd-ide-pokok', 'mcma', 'Menentukan peristiwa yang dialami tokoh tertentu', 'menengah', 'penerapan', 'html', 'psg-bisd-idepokok-kotakpensil', null, '<p>Peristiwa apa saja yang dialami Rani dalam cerita tersebut?</p>', 'Klik pada setiap pilihan jawaban benar! Jawaban benar lebih dari satu.', '<p>Rani menemukan kotak pensil, lalu membawanya ke ruang guru. Kedua peristiwa itu dialami Rani.</p><p>Yang kehilangan kotak berisi uang iuran seragam adalah Damar, bukan Rani.</p>', '[{"key":"A","text":"<p>Menemukan kotak pensil di bawah bangku.</p>"},{"key":"B","text":"<p>Kehilangan uang iuran seragam sejak pagi.</p>","misconceptionId":"mis-bisd-idepokok-004"},{"key":"C","text":"<p>Membawa kotak pensil itu ke ruang guru.</p>"}]'::jsonb, null, array['A', 'C'], null, null, 'A, C', false, null, null),
  ('bisd-idepokok-009', 'sub-bahasa-indonesia-sd', 'top-bi-sd-inferensial', 'st-bi-sd-ide-pokok', 'con-bi-sd-ide-pokok', 'mcma', 'Menalar amanat yang sesuai dengan isi cerita', 'lanjut', 'penalaran', 'html', 'psg-bisd-idepokok-bakulkue', null, '<p>Pernyataan mana saja yang sesuai dengan amanat cerita tersebut?</p>', 'Klik pada setiap pilihan jawaban benar! Jawaban benar lebih dari satu.', '<p>Anak-anak hanya mengumpulkan uang jajan seadanya, tetapi bantuan itu berarti bagi Bu Sari. Kalimat penutup cerita menegaskannya: menolong tidak harus menunggu menjadi orang kaya.</p><p>Pernyataan C justru kebalikan dari amanat cerita.</p>', '[{"key":"A","text":"<p>Menolong dapat dilakukan sesuai kemampuan kita.</p>"},{"key":"B","text":"<p>Kesulitan orang lain layak kita perhatikan.</p>"},{"key":"C","text":"<p>Menolong sebaiknya ditunda sampai kita kaya.</p>","misconceptionId":"mis-bisd-idepokok-003"}]'::jsonb, null, array['A', 'B'], null, null, 'A, B', false, null, null),
  ('bisd-idepokok-010', 'sub-bahasa-indonesia-sd', 'top-bi-sd-inferensial', 'st-bi-sd-ide-pokok', 'con-bi-sd-ide-pokok', 'category', 'Memilah ide pokok dan gagasan pendukung', 'lanjut', 'penalaran', 'html', 'psg-bisd-idepokok-lebah', null, '<p>Tentukan ide pokok atau gagasan pendukung untuk setiap kalimat berikut sesuai paragrafnya masing-masing!</p>', 'Klik pada pilihan Ide Pokok atau Gagasan Pendukung untuk setiap kalimat.', '<p>P1 dan P4 adalah kalimat yang dijelaskan kalimat-kalimat lain pada paragrafnya, jadi keduanya ide pokok.</p><p>P2 berisi contoh pohon yang bergantung pada lebah, dan P3 berisi salah satu cara menjaga lebah. Keduanya rincian, jadi termasuk gagasan pendukung.</p>', null, null, null, '[{"key":"I","label":"Ide Pokok"},{"key":"G","label":"Gagasan Pendukung"}]'::jsonb, '[{"id":"p1","text":"<p>Lebah memberi jasa besar bagi manusia.</p>","correctCategoryKey":"I"},{"id":"p2","text":"<p>Pohon mangga, jambu, dan kopi sangat bergantung pada lebah.</p>","correctCategoryKey":"G","misconceptionId":"mis-bisd-idepokok-002"},{"id":"p3","text":"<p>Sarang lebah liar sebaiknya tidak dibakar.</p>","correctCategoryKey":"G","misconceptionId":"mis-bisd-idepokok-002"},{"id":"p4","text":"<p>Ada beberapa cara untuk menjaga lebah.</p>","correctCategoryKey":"I"}]'::jsonb, 'p1: I; p2: G; p3: G; p4: I', false, null, null),
  ('bisd-perubahan-001', 'sub-bahasa-indonesia-sd', 'top-bi-sd-inferensial', 'st-bi-sd-perubahan-unsur', 'con-bi-sd-perubahan-unsur', 'single', 'Menyimpulkan perubahan bentuk benda pada teks proses', 'dasar', 'pemahaman', 'html', 'psg-bisd-perubahan-tempe', null, '<p>Perubahan apa yang terjadi pada kedelai setelah direbus?</p>', 'Pilih satu jawaban.', '<p>Paragraf kedua menulis: “Kedelai direbus lebih dahulu selama satu jam. Biji yang tadinya keras menjadi lunak.”</p><p>Warna putih dan bentuk balok baru muncul setelah jamur tempe tumbuh, sedangkan bau tajam terjadi pada tempe yang disimpan terlalu lama.</p>', '[{"key":"A","text":"<p>Warnanya berubah menjadi putih bersih.</p>","misconceptionId":"mis-bisd-perubahan-003"},{"key":"B","text":"<p>Bijinya berubah dari keras menjadi lunak.</p>"},{"key":"C","text":"<p>Butirannya menyatu menjadi satu balok.</p>","misconceptionId":"mis-bisd-perubahan-002"},{"key":"D","text":"<p>Baunya berubah menjadi tajam dan tidak sedap.</p>","misconceptionId":"mis-bisd-perubahan-002"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('bisd-perubahan-002', 'sub-bahasa-indonesia-sd', 'top-bi-sd-inferensial', 'st-bi-sd-perubahan-unsur', 'con-bi-sd-perubahan-unsur', 'single', 'Menemukan penyebab perubahan bentuk benda', 'menengah', 'penerapan', 'html', 'psg-bisd-perubahan-tempe', null, '<p>Apa yang membuat butiran kedelai menyatu menjadi satu balok padat?</p>', 'Pilih satu jawaban.', '<p>Paragraf kelima menyebut benang putih tumbuh di sela kedelai, lalu “Butiran kedelai pun menyatu menjadi satu balok padat.” Benang itu adalah jamur tempe.</p><p>Perebusan hanya melunakkan biji dan perendaman membuat air menjadi asam. Keduanya terjadi jauh sebelum kedelai menyatu.</p>', '[{"key":"A","text":"<p>Perebusan kedelai selama satu jam.</p>","misconceptionId":"mis-bisd-perubahan-002"},{"key":"B","text":"<p>Perendaman kedelai selama semalaman.</p>","misconceptionId":"mis-bisd-perubahan-002"},{"key":"C","text":"<p>Bungkus daun pisang yang rapat.</p>","misconceptionId":"mis-bisd-perubahan-003"},{"key":"D","text":"<p>Benang-benang jamur tempe yang tumbuh.</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('bisd-perubahan-003', 'sub-bahasa-indonesia-sd', 'top-bi-sd-inferensial', 'st-bi-sd-perubahan-unsur', 'con-bi-sd-perubahan-unsur', 'single', 'Menyimpulkan sebab perubahan keadaan benda', 'menengah', 'penerapan', 'html', 'psg-bisd-perubahan-tempe', null, '<p>Mengapa tempe yang berwarna kehitaman sebaiknya tidak dimakan?</p>', 'Pilih satu jawaban.', '<p>Teks menyebut tempe yang baru jadi berbau segar, lalu “Bila disimpan terlalu lama, tempe berubah menjadi kehitaman. Baunya pun menjadi tajam dan tidak sedap.”</p><p>Warna kehitaman itu tanda tempe sudah terlalu lama disimpan, bukan tanda pembuatannya gagal sejak awal.</p>', '[{"key":"A","text":"<p>Karena raginya belum tumbuh dengan sempurna.</p>","misconceptionId":"mis-bisd-perubahan-001"},{"key":"B","text":"<p>Karena kedelainya kurang lama direbus.</p>","misconceptionId":"mis-bisd-perubahan-002"},{"key":"C","text":"<p>Karena tempe sudah terlalu lama disimpan.</p>"},{"key":"D","text":"<p>Karena bungkusnya memakai plastik berlubang.</p>","misconceptionId":"mis-bisd-perubahan-003"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('bisd-perubahan-004', 'sub-bahasa-indonesia-sd', 'top-bi-sd-inferensial', 'st-bi-sd-perubahan-unsur', 'con-bi-sd-perubahan-unsur', 'single', 'Menyimpulkan perubahan sikap tokoh dalam cerita', 'menengah', 'penerapan', 'html', 'psg-bisd-perubahan-rio', null, '<p>Bagaimana perubahan sikap Rio setelah lomba baris-berbaris?</p>', 'Pilih satu jawaban.', '<p>Setelah lomba, Rio meminta jam weker, menyiapkan seragam sebelum tidur, dan berangkat lebih pagi. Semuanya menunjukkan sikap yang lebih disiplin.</p><p>Rio memang sempat duduk termenung, tetapi cerita tidak menyebut ia menjauhi teman-temannya. Ia justru dipanggil ketua regu.</p>', '[{"key":"A","text":"<p>Ia menjadi disiplin dan berangkat lebih pagi.</p>"},{"key":"B","text":"<p>Ia menjadi pendiam dan menjauhi teman-temannya.</p>","misconceptionId":"mis-bisd-perubahan-003"},{"key":"C","text":"<p>Ia berhenti mengikuti kegiatan di sekolah.</p>","misconceptionId":"mis-bisd-perubahan-003"},{"key":"D","text":"<p>Ia minta diantar ayahnya setiap pagi.</p>","misconceptionId":"mis-bisd-perubahan-003"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('bisd-perubahan-005', 'sub-bahasa-indonesia-sd', 'top-bi-sd-inferensial', 'st-bi-sd-perubahan-unsur', 'con-bi-sd-perubahan-unsur', 'single', 'Menemukan peristiwa yang menyebabkan tokoh berubah', 'lanjut', 'penalaran', 'html', 'psg-bisd-perubahan-rio', null, '<p>Peristiwa apa yang membuat Rio berubah?</p>', 'Pilih satu jawaban.', '<p>Rio sudah lama dibangunkan ibunya, tetapi sikapnya tidak berubah. Perubahan baru terjadi setelah regunya maju tanpa pemimpin dan nilainya berkurang. Rio merasakan sendiri akibat keterlambatannya.</p><p>Jam weker dan sebutan ketua regu justru muncul setelah Rio berubah, jadi keduanya akibat, bukan penyebab.</p>', '[{"key":"A","text":"<p>Ibunya membangunkan Rio berkali-kali setiap pagi.</p>","misconceptionId":"mis-bisd-perubahan-004"},{"key":"B","text":"<p>Regunya maju tanpa pemimpin karena Rio terlambat.</p>"},{"key":"C","text":"<p>Ayahnya memberikan sebuah jam weker kepadanya.</p>","misconceptionId":"mis-bisd-perubahan-002"},{"key":"D","text":"<p>Teman-temannya memanggil Rio dengan sebutan ketua regu.</p>","misconceptionId":"mis-bisd-perubahan-002"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('bisd-perubahan-006', 'sub-bahasa-indonesia-sd', 'top-bi-sd-inferensial', 'st-bi-sd-perubahan-unsur', 'con-bi-sd-perubahan-unsur', 'single', 'Menyimpulkan perubahan latar tempat dalam teks', 'menengah', 'penerapan', 'html', 'psg-bisd-perubahan-kampung', null, '<p>Perubahan latar apa yang terjadi di kampung tersebut?</p>', 'Pilih satu jawaban.', '<p>Teks menyebut dahulu di depan rumah terbentang sawah luas, lalu “Sawah di depan rumah berubah menjadi deretan toko.”</p><p>Pilihan A dan C membalik arah perubahannya. Lapangan dekat balai desa justru menjadi tempat bermain anak-anak sekarang.</p>', '[{"key":"A","text":"<p>Sungai kecil di utara berubah menjadi sawah luas.</p>","misconceptionId":"mis-bisd-perubahan-001"},{"key":"B","text":"<p>Lapangan dekat balai desa berubah menjadi toko.</p>","misconceptionId":"mis-bisd-perubahan-005"},{"key":"C","text":"<p>Jalan beraspal berubah menjadi tanah berbatu.</p>","misconceptionId":"mis-bisd-perubahan-001"},{"key":"D","text":"<p>Sawah di depan rumah berubah menjadi deretan toko.</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('bisd-perubahan-007', 'sub-bahasa-indonesia-sd', 'top-bi-sd-inferensial', 'st-bi-sd-perubahan-unsur', 'con-bi-sd-perubahan-unsur', 'single', 'Menalar hubungan perubahan latar dengan suasana kampung', 'lanjut', 'penalaran', 'html', 'psg-bisd-perubahan-kampung', null, '<p>Perubahan mana yang membuat suasana kampung menjadi lebih bising?</p>', 'Pilih satu jawaban.', '<p>Teks menulis “Suara katak berganti dengan suara kendaraan”. Kendaraan bertambah karena sawah di depan rumah berubah menjadi deretan toko.</p><p>Aspal, lapangan, dan bibit pohon disebut teks, tetapi tidak dihubungkan dengan bertambahnya suara kendaraan.</p>', '[{"key":"A","text":"<p>Jalan kampung yang kini dilapisi aspal halus.</p>","misconceptionId":"mis-bisd-perubahan-005"},{"key":"B","text":"<p>Anak-anak yang bermain di lapangan balai desa.</p>","misconceptionId":"mis-bisd-perubahan-005"},{"key":"C","text":"<p>Sawah yang berganti toko sehingga kendaraan bertambah.</p>"},{"key":"D","text":"<p>Bibit pohon di tepi jalan yang diberi pagar bambu.</p>","misconceptionId":"mis-bisd-perubahan-003"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('bisd-perubahan-008', 'sub-bahasa-indonesia-sd', 'top-bi-sd-inferensial', 'st-bi-sd-perubahan-unsur', 'con-bi-sd-perubahan-unsur', 'mcma', 'Menentukan perubahan benda yang disebut dalam teks', 'menengah', 'penerapan', 'html', 'psg-bisd-perubahan-tempe', null, '<p>Perubahan apa saja yang dialami kedelai sampai menjadi tempe?</p>', 'Klik pada setiap pilihan jawaban benar! Jawaban benar lebih dari satu.', '<p>Kedelai melunak setelah direbus dan menyatu menjadi balok setelah jamur tempe tumbuh. Keduanya perubahan yang dialami kedelai selama menjadi tempe.</p><p>Warna kehitaman terjadi pada tempe yang sudah jadi lalu disimpan terlalu lama, bukan bagian dari proses pembuatannya.</p>', '[{"key":"A","text":"<p>Dari kuning menjadi kehitaman.</p>","misconceptionId":"mis-bisd-perubahan-002"},{"key":"B","text":"<p>Dari keras menjadi lunak.</p>"},{"key":"C","text":"<p>Dari butiran terpisah menjadi balok padat.</p>"}]'::jsonb, null, array['B', 'C'], null, null, 'B, C', false, null, null),
  ('bisd-perubahan-009', 'sub-bahasa-indonesia-sd', 'top-bi-sd-inferensial', 'st-bi-sd-perubahan-unsur', 'con-bi-sd-perubahan-unsur', 'mcma', 'Menentukan perbuatan yang menunjukkan perubahan tokoh', 'menengah', 'penerapan', 'html', 'psg-bisd-perubahan-rio', null, '<p>Perbuatan apa saja yang menunjukkan perubahan sikap Rio?</p>', 'Klik pada setiap pilihan jawaban benar! Jawaban benar lebih dari satu.', '<p>Kedua perbuatan itu dilakukan Rio pada malam setelah lomba, yaitu saat ia mulai berubah.</p><p>Menarik selimut lalu tidur lagi adalah kebiasaan Rio yang lama, jadi justru menunjukkan keadaan sebelum ia berubah.</p>', '[{"key":"A","text":"<p>Menaruh jam weker di dekat bantal.</p>"},{"key":"B","text":"<p>Menarik selimut lalu tidur lagi.</p>","misconceptionId":"mis-bisd-perubahan-001"},{"key":"C","text":"<p>Menyiapkan seragam sebelum tidur.</p>"}]'::jsonb, null, array['A', 'C'], null, null, 'A, C', false, null, null),
  ('bisd-perubahan-010', 'sub-bahasa-indonesia-sd', 'top-bi-sd-inferensial', 'st-bi-sd-perubahan-unsur', 'con-bi-sd-perubahan-unsur', 'category', 'Membandingkan keadaan latar dahulu dan sekarang', 'lanjut', 'penalaran', 'html', 'psg-bisd-perubahan-kampung', null, '<p>Tentukan keadaan dahulu atau keadaan sekarang untuk setiap pernyataan berikut!</p>', 'Klik pada pilihan Dahulu atau Sekarang untuk setiap pernyataan.', '<p>P2 dan P4 berada pada bagian cerita Kakek tentang masa lalu: anak-anak bermain di pematang dan suara katak masih terdengar.</p><p>P1 dan P3 muncul setelah kalimat “Sekarang keadaannya sudah berbeda”, jadi keduanya keadaan sekarang.</p>', null, null, null, '[{"key":"D","label":"Dahulu"},{"key":"S","label":"Sekarang"}]'::jsonb, '[{"id":"p1","text":"<p>Jalan kampung dilapisi aspal halus.</p>","correctCategoryKey":"S","misconceptionId":"mis-bisd-perubahan-001"},{"id":"p2","text":"<p>Anak-anak bermain layang-layang di pematang sawah.</p>","correctCategoryKey":"D"},{"id":"p3","text":"<p>Sungai kecil di utara menyempit karena bangunan.</p>","correctCategoryKey":"S","misconceptionId":"mis-bisd-perubahan-001"},{"id":"p4","text":"<p>Suara katak terdengar sampai ke teras rumah.</p>","correctCategoryKey":"D"}]'::jsonb, 'p1: S; p2: D; p3: S; p4: D', false, null, null),
  ('bisd-ungkapan-001', 'sub-bahasa-indonesia-sd', 'top-bi-sd-inferensial', 'st-bi-sd-makna-ungkapan', 'con-bi-sd-makna-ungkapan', 'single', 'Menjelaskan makna ungkapan dalam teks fiksi', 'dasar', 'pemahaman', 'html', 'psg-bisd-ungkapan-ketuakelas', null, '<p>Apa arti ungkapan <strong>ringan tangan</strong> pada cerita tersebut?</p>', 'Pilih satu jawaban.', '<p>Kalimat sesudahnya menjelaskan: “Ia sering membantu piket walaupun bukan gilirannya.” Perbuatan itu menunjukkan sifat suka menolong.</p><p>Pilihan D mengartikan kata ringan sebagai cepat. Padahal yang ditekankan cerita adalah kesediaannya membantu, bukan kecepatannya.</p>', '[{"key":"A","text":"<p>Mudah marah kepada temannya.</p>","misconceptionId":"mis-bisd-ungkapan-005"},{"key":"B","text":"<p>Malas mengerjakan tugas piket.</p>","misconceptionId":"mis-bisd-ungkapan-001"},{"key":"C","text":"<p>Suka menolong orang lain.</p>"},{"key":"D","text":"<p>Cepat menyelesaikan pekerjaan.</p>","misconceptionId":"mis-bisd-ungkapan-001"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('bisd-ungkapan-002', 'sub-bahasa-indonesia-sd', 'top-bi-sd-inferensial', 'st-bi-sd-makna-ungkapan', 'con-bi-sd-makna-ungkapan', 'single', 'Menjelaskan makna ungkapan yang menyatakan sifat', 'menengah', 'penerapan', 'html', 'psg-bisd-ungkapan-ketuakelas', null, '<p>Apa maksud Sekar ketika berbisik, “Jangan <strong>besar kepala</strong>, Lih”?</p>', 'Pilih satu jawaban.', '<p>Sebelum bisikan itu, Galih mulai memerintah teman-temannya dan menjawab teguran dengan suara tinggi. Sekar mengingatkan agar Galih tidak sombong setelah terpilih.</p><p>Pilihan C adalah arti keras kepala, bukan besar kepala. Keduanya memakai kata kepala, tetapi maknanya berbeda.</p>', '[{"key":"A","text":"<p>Jangan menjadi sombong setelah terpilih.</p>"},{"key":"B","text":"<p>Jangan terlalu banyak berpikir sendiri.</p>","misconceptionId":"mis-bisd-ungkapan-001"},{"key":"C","text":"<p>Jangan bersikeras mempertahankan pendapat.</p>","misconceptionId":"mis-bisd-ungkapan-002"},{"key":"D","text":"<p>Jangan mudah tersinggung bila ditegur.</p>","misconceptionId":"mis-bisd-ungkapan-003"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('bisd-ungkapan-003', 'sub-bahasa-indonesia-sd', 'top-bi-sd-inferensial', 'st-bi-sd-makna-ungkapan', 'con-bi-sd-makna-ungkapan', 'single', 'Menjelaskan makna ungkapan yang menggambarkan keadaan', 'menengah', 'penerapan', 'html', 'psg-bisd-ungkapan-ketuakelas', null, '<p>Apa arti <strong>diam seribu bahasa</strong> pada cerita tersebut?</p>', 'Pilih satu jawaban.', '<p>Bu Guru bertanya siapa yang bertugas, tetapi tidak seorang pun menjawab. Ungkapan diam seribu bahasa berarti membisu sama sekali.</p><p>Pilihan A menebak dari suasana cerita, padahal Galih ternyata mengetahui persoalannya dan kemudian mengaku.</p>', '[{"key":"A","text":"<p>Anak-anak tidak mengetahui masalah yang terjadi.</p>","misconceptionId":"mis-bisd-ungkapan-003"},{"key":"B","text":"<p>Anak-anak tidak mampu menjawab dalam bahasa lain.</p>","misconceptionId":"mis-bisd-ungkapan-001"},{"key":"C","text":"<p>Anak-anak tidak mau mendengarkan penjelasan guru.</p>","misconceptionId":"mis-bisd-ungkapan-003"},{"key":"D","text":"<p>Anak-anak sama sekali tidak ada yang berbicara.</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('bisd-ungkapan-004', 'sub-bahasa-indonesia-sd', 'top-bi-sd-inferensial', 'st-bi-sd-makna-ungkapan', 'con-bi-sd-makna-ungkapan', 'single', 'Menjelaskan makna ungkapan tentang kerja keras', 'menengah', 'penerapan', 'html', 'psg-bisd-ungkapan-sapu', null, '<p>Apa arti ungkapan <strong>banting tulang</strong> pada teks tersebut?</p>', 'Pilih satu jawaban.', '<p>Kalimat sesudahnya menyebut kaki Pak Warno menempuh puluhan kilometer setiap pekan. Ungkapan banting tulang berarti bekerja keras tanpa mengenal lelah.</p><p>Pilihan D hanya menyebut satu contoh perbuatannya di dalam teks, bukan arti ungkapannya.</p>', '[{"key":"A","text":"<p>Bekerja sambil menahan rasa sakit.</p>","misconceptionId":"mis-bisd-ungkapan-001"},{"key":"B","text":"<p>Bekerja keras tanpa mengenal lelah.</p>"},{"key":"C","text":"<p>Bekerja tanpa menerima upah sedikit pun.</p>","misconceptionId":"mis-bisd-ungkapan-003"},{"key":"D","text":"<p>Berjualan keliling dari kampung ke kampung.</p>","misconceptionId":"mis-bisd-ungkapan-004"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('bisd-ungkapan-005', 'sub-bahasa-indonesia-sd', 'top-bi-sd-inferensial', 'st-bi-sd-makna-ungkapan', 'con-bi-sd-makna-ungkapan', 'single', 'Menjelaskan makna ungkapan tentang keadaan usaha', 'menengah', 'penerapan', 'html', 'psg-bisd-ungkapan-sapu', null, '<p>Apa arti ungkapan <strong>gulung tikar</strong> pada teks tersebut?</p>', 'Pilih satu jawaban.', '<p>Ungkapan itu muncul setelah sapu plastik membanjiri pasar. Kalimat berikutnya menyebut Pak Warno hampir ikut berhenti. Jadi gulung tikar berarti berhenti berusaha karena merugi.</p><p>Pilihan D mengartikan katanya satu per satu, yaitu menggulung tikar dagangan.</p>', '[{"key":"A","text":"<p>Pindah berjualan ke kota lain.</p>","misconceptionId":"mis-bisd-ungkapan-003"},{"key":"B","text":"<p>Berganti barang dagangan.</p>","misconceptionId":"mis-bisd-ungkapan-003"},{"key":"C","text":"<p>Berhenti berusaha karena merugi.</p>"},{"key":"D","text":"<p>Membereskan dagangan setiap sore.</p>","misconceptionId":"mis-bisd-ungkapan-001"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('bisd-ungkapan-006', 'sub-bahasa-indonesia-sd', 'top-bi-sd-inferensial', 'st-bi-sd-makna-ungkapan', 'con-bi-sd-makna-ungkapan', 'single', 'Menafsirkan makna ungkapan dalam larik puisi', 'menengah', 'penerapan', 'html', 'psg-bisd-ungkapan-puisi', null, '<p>Apa makna larik “Agar <strong>dapur kami tetap berasap</strong>”?</p>', 'Pilih satu jawaban.', '<p>Larik itu menjelaskan tujuan ibu bekerja keras sejak pagi. Dapur yang berasap menandakan ada yang dimasak, artinya kebutuhan makan keluarga tercukupi.</p><p>Pilihan C dan D mengartikan asap secara harfiah sehingga hubungan dengan kerja keras ibu menjadi hilang.</p>', '[{"key":"A","text":"<p>Keluarganya tetap dapat makan setiap hari.</p>"},{"key":"B","text":"<p>Rumahnya selalu ramai dikunjungi tamu.</p>","misconceptionId":"mis-bisd-ungkapan-003"},{"key":"C","text":"<p>Ibunya memasak memakai kayu bakar.</p>","misconceptionId":"mis-bisd-ungkapan-001"},{"key":"D","text":"<p>Dapurnya dipenuhi asap setiap pagi.</p>","misconceptionId":"mis-bisd-ungkapan-001"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('bisd-ungkapan-007', 'sub-bahasa-indonesia-sd', 'top-bi-sd-inferensial', 'st-bi-sd-makna-ungkapan', 'con-bi-sd-makna-ungkapan', 'single', 'Menalar makna ungkapan dari sikap tokoh dalam puisi', 'lanjut', 'penalaran', 'html', 'psg-bisd-ungkapan-puisi', null, '<p>Larik “Ibu tidak lekas <strong>naik darah</strong>” bermakna ibu tidak ….</p>', 'Pilih satu jawaban.', '<p>Larik itu muncul saat nilai anaknya turun. Larik berikutnya menyebut ibu berbicara dengan kepala dingin, yaitu dengan tenang. Berarti naik darah bermakna menjadi marah.</p><p>Bila ibu tidak lekas naik darah, ia tidak cepat marah walaupun kecewa.</p>', '[{"key":"A","text":"<p>cepat memuji anaknya</p>","misconceptionId":"mis-bisd-ungkapan-003"},{"key":"B","text":"<p>mudah memercayai orang</p>","misconceptionId":"mis-bisd-ungkapan-002"},{"key":"C","text":"<p>lekas menitikkan air mata</p>","misconceptionId":"mis-bisd-ungkapan-001"},{"key":"D","text":"<p>cepat menjadi marah</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('bisd-ungkapan-008', 'sub-bahasa-indonesia-sd', 'top-bi-sd-inferensial', 'st-bi-sd-makna-ungkapan', 'con-bi-sd-makna-ungkapan', 'mcma', 'Memilah ungkapan yang menyatakan sifat terpuji', 'menengah', 'penerapan', 'html', 'psg-bisd-ungkapan-ketuakelas', null, '<p>Ungkapan mana saja pada cerita tersebut yang menyatakan sifat terpuji?</p>', 'Klik pada setiap pilihan jawaban benar! Jawaban benar lebih dari satu.', '<p>Ringan tangan berarti suka menolong dan kepala dingin berarti tenang saat menghadapi masalah. Keduanya sifat terpuji.</p><p>Besar kepala berarti sombong. Ungkapan itu dipakai Sekar untuk menegur Galih, jadi maknanya justru kurang baik.</p>', '[{"key":"A","text":"<p>Ringan tangan.</p>"},{"key":"B","text":"<p>Kepala dingin.</p>"},{"key":"C","text":"<p>Besar kepala.</p>","misconceptionId":"mis-bisd-ungkapan-005"}]'::jsonb, null, array['A', 'B'], null, null, 'A, B', false, null, null),
  ('bisd-ungkapan-009', 'sub-bahasa-indonesia-sd', 'top-bi-sd-inferensial', 'st-bi-sd-makna-ungkapan', 'con-bi-sd-makna-ungkapan', 'mcma', 'Memilah ungkapan yang menggambarkan keadaan usaha', 'lanjut', 'penalaran', 'html', 'psg-bisd-ungkapan-sapu', null, '<p>Ungkapan mana saja pada teks tersebut yang menggambarkan keadaan sebuah usaha?</p>', 'Klik pada setiap pilihan jawaban benar! Jawaban benar lebih dari satu.', '<p>Gulung tikar berarti usaha berhenti karena merugi, sedangkan naik daun berarti menjadi terkenal dan banyak dicari. Keduanya menggambarkan keadaan usaha.</p><p>Buah tangan berarti oleh-oleh, yaitu barang yang dibawa pulang tamu, bukan keadaan usaha Pak Warno.</p>', '[{"key":"A","text":"<p>Buah tangan.</p>","misconceptionId":"mis-bisd-ungkapan-004"},{"key":"B","text":"<p>Gulung tikar.</p>"},{"key":"C","text":"<p>Naik daun.</p>"}]'::jsonb, null, array['B', 'C'], null, null, 'B, C', false, null, null),
  ('bisd-ungkapan-010', 'sub-bahasa-indonesia-sd', 'top-bi-sd-inferensial', 'st-bi-sd-makna-ungkapan', 'con-bi-sd-makna-ungkapan', 'category', 'Menilai ketepatan makna ungkapan', 'lanjut', 'penalaran', 'html', null, '<p>Setelah membaca ketiga teks di atas, Nadia menuliskan arti beberapa ungkapan di buku catatannya.</p>', '<p>Tentukan tepat atau tidak tepat untuk setiap arti yang ditulis Nadia!</p>', 'Klik pada pilihan Tepat atau Tidak Tepat untuk setiap pernyataan.', '<p>P1 dan P3 sudah tepat sesuai pemakaiannya pada teks.</p><p>P2 tidak tepat: buah tangan berarti oleh-oleh. Yang berarti hasil pemikiran adalah buah pikiran.</p><p>P4 tidak tepat: kepala dingin berarti tenang dan sabar. Bu Guru menasihati Galih dengan tenang, bukan dengan tersinggung.</p>', null, null, null, '[{"key":"T","label":"Tepat"},{"key":"X","label":"Tidak Tepat"}]'::jsonb, '[{"id":"p1","text":"<p>Ringan tangan berarti suka menolong.</p>","correctCategoryKey":"T"},{"id":"p2","text":"<p>Buah tangan berarti hasil pemikiran sendiri.</p>","correctCategoryKey":"X","misconceptionId":"mis-bisd-ungkapan-002"},{"id":"p3","text":"<p>Naik daun berarti mulai dikenal banyak orang.</p>","correctCategoryKey":"T"},{"id":"p4","text":"<p>Kepala dingin berarti mudah tersinggung.</p>","correctCategoryKey":"X","misconceptionId":"mis-bisd-ungkapan-002"}]'::jsonb, 'p1: T; p2: X; p3: T; p4: X', false, null, null),
  ('bisd-relevansi-001', 'sub-bahasa-indonesia-sd', 'top-bi-sd-evaluasi', 'st-bi-sd-relevansi-peristiwa', 'con-bi-sd-relevansi-peristiwa', 'single', 'Menghubungkan peristiwa dalam teks dengan pengalaman sehari-hari', 'dasar', 'pemahaman', 'html', 'psg-bisd-relevansi-puskesmas', null, '<p>Peristiwa pada cerita tersebut paling sesuai dengan kejadian sehari-hari berikut, yaitu ….</p>', 'Pilih satu jawaban.', '<p>Inti cerita adalah mendahulukan orang yang lebih membutuhkan tempat duduk, yaitu kakek yang berjalan dengan tongkat. Memberikan tempat duduk kepada nenek di bus adalah kejadian sehari-hari dengan nilai yang sama.</p><p>Pilihan A, B, dan C memang sering terjadi, tetapi tidak berhubungan dengan mendahulukan orang yang lebih membutuhkan.</p>', '[{"key":"A","text":"<p>seorang siswa meminjam pensil kepada teman sebangkunya</p>","misconceptionId":"mis-bisd-relevansi-001"},{"key":"B","text":"<p>seorang anak membeli jajan sepulang dari sekolah</p>","misconceptionId":"mis-bisd-relevansi-001"},{"key":"C","text":"<p>seorang siswa menyalin catatan milik teman sekelasnya</p>","misconceptionId":"mis-bisd-relevansi-001"},{"key":"D","text":"<p>seorang anak memberikan tempat duduknya kepada nenek di bus</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('bisd-relevansi-002', 'sub-bahasa-indonesia-sd', 'top-bi-sd-evaluasi', 'st-bi-sd-relevansi-peristiwa', 'con-bi-sd-relevansi-peristiwa', 'single', 'Menilai perbuatan tokoh yang layak ditiru', 'menengah', 'penerapan', 'html', 'psg-bisd-relevansi-puskesmas', null, '<p>Perbuatan Nia yang layak ditiru dalam kehidupan sehari-hari adalah ….</p>', 'Pilih satu jawaban.', '<p>Nia memperhatikan sekelilingnya, lalu memberitahukan kakek yang berdiri kepada ibunya. Dari situlah kakek itu akhirnya mendapat tempat duduk.</p><p>Pilihan A, C, dan D memang dilakukan Nia, tetapi ketiganya hanya kegiatan biasa saat mengantre, bukan perbuatan yang menolong orang lain.</p>', '[{"key":"A","text":"<p>mengambil nomor antrean di meja depan</p>","misconceptionId":"mis-bisd-relevansi-003"},{"key":"B","text":"<p>memberitahukan keadaan kakek kepada ibunya</p>"},{"key":"C","text":"<p>berdiri menunggu di dekat pintu ruang tunggu</p>","misconceptionId":"mis-bisd-relevansi-003"},{"key":"D","text":"<p>menunggu sampai nomornya dipanggil petugas</p>","misconceptionId":"mis-bisd-relevansi-003"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('bisd-relevansi-003', 'sub-bahasa-indonesia-sd', 'top-bi-sd-evaluasi', 'st-bi-sd-relevansi-peristiwa', 'con-bi-sd-relevansi-peristiwa', 'single', 'Memilih kebiasaan sehari-hari yang sesuai anjuran teks', 'menengah', 'penerapan', 'html', 'psg-bisd-relevansi-air', null, '<p>Kebiasaan di rumah yang sesuai dengan isi teks tersebut adalah ….</p>', 'Pilih satu jawaban.', '<p>Teks menganjurkan menampung air bekas cucian beras karena air itu masih dapat dipakai menyiram tanaman.</p><p>Pilihan C dan D justru kebalikan dari anjuran teks: keran menetes membuang belasan liter air, dan menyiram pada siang hari membuat air cepat menguap.</p>', '[{"key":"A","text":"<p>menampung air cucian beras untuk menyiram tanaman</p>"},{"key":"B","text":"<p>mencuci sepeda setiap pagi memakai air selang</p>","misconceptionId":"mis-bisd-relevansi-005"},{"key":"C","text":"<p>membiarkan keran menetes agar bak selalu penuh</p>","misconceptionId":"mis-bisd-relevansi-002"},{"key":"D","text":"<p>menyiram tanaman pada siang hari yang terik</p>","misconceptionId":"mis-bisd-relevansi-002"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('bisd-relevansi-004', 'sub-bahasa-indonesia-sd', 'top-bi-sd-evaluasi', 'st-bi-sd-relevansi-peristiwa', 'con-bi-sd-relevansi-peristiwa', 'single', 'Menilai alasan yang mendukung anjuran dalam teks', 'lanjut', 'penalaran', 'html', 'psg-bisd-relevansi-air', null, '<p>Alasan yang mendukung anjuran menyiram tanaman pada sore hari adalah ….</p>', 'Pilih satu jawaban.', '<p>Teks menyebut alasannya langsung: “Pada waktu itu air tidak cepat menguap.” Alasan itu sejalan dengan tujuan teks, yaitu menghemat air.</p><p>Pilihan lain terdengar masuk akal, tetapi tidak menjelaskan penghematan air dan tidak disebutkan di dalam teks.</p>', '[{"key":"A","text":"<p>tanaman lebih cepat tumbuh bila disiram sore hari</p>","misconceptionId":"mis-bisd-relevansi-004"},{"key":"B","text":"<p>petugas kebersihan lebih senggang pada sore hari</p>","misconceptionId":"mis-bisd-relevansi-004"},{"key":"C","text":"<p>air tidak cepat menguap sehingga tidak terbuang</p>"},{"key":"D","text":"<p>tanah menjadi lebih gembur bila disiram sore hari</p>","misconceptionId":"mis-bisd-relevansi-004"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('bisd-relevansi-005', 'sub-bahasa-indonesia-sd', 'top-bi-sd-evaluasi', 'st-bi-sd-relevansi-peristiwa', 'con-bi-sd-relevansi-peristiwa', 'single', 'Menilai pengalaman pribadi yang sejalan dengan isi teks', 'menengah', 'penerapan', 'html', 'psg-bisd-relevansi-air', null, '<p>Pengalaman berikut yang paling sesuai dengan pesan teks tersebut adalah ….</p>', 'Pilih satu jawaban.', '<p>Teks menyebut keran menetes membuang air belasan liter setiap hari. Melaporkan keran yang menetes berarti ikut mencegah air terbuang.</p><p>Pilihan B dan C berlawanan dengan anjuran teks, sedangkan pilihan A berhubungan dengan air minum, bukan dengan penghematan air.</p>', '[{"key":"A","text":"<p>Rani membeli air minum kemasan setiap jam istirahat.</p>","misconceptionId":"mis-bisd-relevansi-001"},{"key":"B","text":"<p>Dito mengisi bak mandi hingga airnya meluap.</p>","misconceptionId":"mis-bisd-relevansi-002"},{"key":"C","text":"<p>Sari mencuci piring dengan keran terbuka terus.</p>","misconceptionId":"mis-bisd-relevansi-002"},{"key":"D","text":"<p>Andi melaporkan keran kelas yang menetes kepada penjaga.</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('bisd-relevansi-006', 'sub-bahasa-indonesia-sd', 'top-bi-sd-evaluasi', 'st-bi-sd-relevansi-peristiwa', 'con-bi-sd-relevansi-peristiwa', 'single', 'Menghubungkan peristiwa cerita dengan kegiatan di lingkungan', 'menengah', 'penerapan', 'html', 'psg-bisd-relevansi-listrik', null, '<p>Kejadian pada cerita tersebut paling sesuai dengan kegiatan sehari-hari berikut, yaitu ….</p>', 'Pilih satu jawaban.', '<p>Warga berkumpul untuk menyelesaikan satu masalah bersama, yaitu dahan yang menimpa kabel listrik. Kerja bakti membersihkan saluran air memiliki bentuk yang sama: pekerjaan bersama demi kepentingan bersama.</p><p>Pilihan A, C, dan D sama-sama kegiatan bersama, tetapi bukan usaha mengatasi masalah yang mendesak.</p>', '[{"key":"A","text":"<p>lomba kebersihan antarkelas menjelang hari besar</p>","misconceptionId":"mis-bisd-relevansi-001"},{"key":"B","text":"<p>kerja bakti warga membersihkan saluran air</p>"},{"key":"C","text":"<p>rapat pemilihan ketua RT di balai desa</p>","misconceptionId":"mis-bisd-relevansi-001"},{"key":"D","text":"<p>arisan bulanan ibu-ibu di rumah tetangga</p>","misconceptionId":"mis-bisd-relevansi-001"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('bisd-relevansi-007', 'sub-bahasa-indonesia-sd', 'top-bi-sd-evaluasi', 'st-bi-sd-relevansi-peristiwa', 'con-bi-sd-relevansi-peristiwa', 'single', 'Menalar penerapan pesan teks pada perbuatan tokoh', 'lanjut', 'penalaran', 'html', 'psg-bisd-relevansi-listrik', null, '<p>Perbuatan Adi keesokan harinya menunjukkan bahwa ….</p>', 'Pilih satu jawaban.', '<p>Adi mengingat kalimat Pak RT bahwa pekerjaan berat menjadi ringan bila dikerjakan bersama. Keesokan harinya ia mengajak teman-temannya membersihkan selokan kelas.</p><p>Cerita tidak menyebut Adi ingin dipuji, takut ditegur, atau sudah terbiasa melakukannya. Ketiga pilihan itu hanya dugaan dari luar teks.</p>', '[{"key":"A","text":"<p>ia menerapkan kebiasaan bekerja bersama di sekolahnya</p>"},{"key":"B","text":"<p>ia ingin dipuji guru karena terlihat rajin bekerja</p>","misconceptionId":"mis-bisd-relevansi-003"},{"key":"C","text":"<p>ia takut ditegur Pak RT bila tidak ikut membantu</p>","misconceptionId":"mis-bisd-relevansi-003"},{"key":"D","text":"<p>ia memang biasa membersihkan selokan setiap pagi</p>","misconceptionId":"mis-bisd-relevansi-003"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('bisd-relevansi-008', 'sub-bahasa-indonesia-sd', 'top-bi-sd-evaluasi', 'st-bi-sd-relevansi-peristiwa', 'con-bi-sd-relevansi-peristiwa', 'mcma', 'Memilah kebiasaan yang sesuai anjuran teks', 'menengah', 'penerapan', 'html', 'psg-bisd-relevansi-air', null, '<p>Kebiasaan mana saja yang sesuai dengan anjuran pada teks tersebut?</p>', 'Klik pada setiap pilihan jawaban benar! Jawaban benar lebih dari satu.', '<p>Mandi memakai gayung dan memeriksa pipa bocor disebut teks sebagai cara ketiga dan cara keempat menghemat air.</p><p>Mencuci kendaraan dengan selang setiap hari justru memakai banyak air dan tidak dianjurkan teks.</p>', '[{"key":"A","text":"<p>Mandi memakai gayung.</p>"},{"key":"B","text":"<p>Mencuci kendaraan dengan selang setiap hari.</p>","misconceptionId":"mis-bisd-relevansi-005"},{"key":"C","text":"<p>Memeriksa pipa air yang bocor.</p>"}]'::jsonb, null, array['A', 'C'], null, null, 'A, C', false, null, null),
  ('bisd-relevansi-009', 'sub-bahasa-indonesia-sd', 'top-bi-sd-evaluasi', 'st-bi-sd-relevansi-peristiwa', 'con-bi-sd-relevansi-peristiwa', 'mcma', 'Menemukan perbuatan yang menunjukkan kerja sama warga', 'menengah', 'penerapan', 'html', 'psg-bisd-relevansi-listrik', null, '<p>Perbuatan mana saja yang menunjukkan warga saling membantu?</p>', 'Klik pada setiap pilihan jawaban benar! Jawaban benar lebih dari satu.', '<p>Membawa gergaji dan tali serta menyiapkan teh hangat adalah dua bentuk bantuan yang berbeda, tetapi keduanya menolong pekerjaan bersama malam itu.</p><p>Anak-anak menunggu di dalam rumah demi keselamatan mereka sendiri, jadi bukan bentuk membantu.</p>', '[{"key":"A","text":"<p>Beberapa bapak membawa gergaji dan tali.</p>"},{"key":"B","text":"<p>Ibu-ibu menyiapkan teh hangat di pos ronda.</p>"},{"key":"C","text":"<p>Anak-anak menunggu di dalam rumah.</p>","misconceptionId":"mis-bisd-relevansi-001"}]'::jsonb, null, array['A', 'B'], null, null, 'A, B', false, null, null),
  ('bisd-relevansi-010', 'sub-bahasa-indonesia-sd', 'top-bi-sd-evaluasi', 'st-bi-sd-relevansi-peristiwa', 'con-bi-sd-relevansi-peristiwa', 'category', 'Menilai kesesuaian contoh sehari-hari dengan peristiwa dalam teks', 'lanjut', 'penalaran', 'html', 'psg-bisd-relevansi-puskesmas', null, '<p>Apa contoh peristiwa sehari-hari yang sejalan dengan kejadian di puskesmas pada cerita tersebut? Tentukan sesuai atau tidak sesuai untuk setiap pernyataan berikut!</p>', 'Klik pada pilihan Sesuai atau Tidak Sesuai untuk setiap pernyataan.', '<p>P1 dan P2 sejalan dengan cerita: keduanya mendahulukan orang yang lebih membutuhkan tempat duduk, seperti yang dilakukan Nia dan pemuda di puskesmas.</p><p>P3 dan P4 berlawanan dengan pesan cerita. Menyerobot barisan mengabaikan giliran orang lain, dan menaruh tas di kursi menghalangi orang yang membutuhkan tempat duduk.</p>', null, null, null, '[{"key":"S","label":"Sesuai"},{"key":"T","label":"Tidak Sesuai"}]'::jsonb, '[{"id":"p1","text":"<p>Doni mempersilakan neneknya duduk di kursi ruang tunggu.</p>","correctCategoryKey":"S"},{"id":"p2","text":"<p>Bayu memberi tahu petugas bahwa ada penumpang lansia berdiri.</p>","correctCategoryKey":"S"},{"id":"p3","text":"<p>Sinta menyerobot barisan agar cepat mendapat giliran.</p>","correctCategoryKey":"T","misconceptionId":"mis-bisd-relevansi-002"},{"id":"p4","text":"<p>Rita menaruh tasnya di kursi agar tidak diduduki orang lain.</p>","correctCategoryKey":"T","misconceptionId":"mis-bisd-relevansi-002"}]'::jsonb, 'p1: S; p2: S; p3: T; p4: T', false, null, null),
  ('bisd-kesesuaian-001', 'sub-bahasa-indonesia-sd', 'top-bi-sd-evaluasi', 'st-bi-sd-kesesuaian-antarunsur', 'con-bi-sd-kesesuaian-antarunsur', 'single', 'Menilai kesesuaian warna dengan pesan utama teks', 'menengah', 'penerapan', 'html', 'psg-bisd-kesesuaian-poster', null, '<p>Mengapa kata “Cuci Tangan” pada poster dicetak dengan warna merah?</p>', 'Pilih satu jawaban.', '<p>Seluruh isi poster membahas cara mencuci tangan. Kata yang diberi warna berbeda adalah kata yang paling penting, yaitu ajakan mencuci tangan.</p><p>Pilihan B dan C hanya menganggap warna sebagai hiasan, padahal warna itu dipakai untuk menegaskan pesan.</p>', '[{"key":"A","text":"<p>Untuk menonjolkan pesan utama poster itu.</p>"},{"key":"B","text":"<p>Agar poster terlihat berwarna-warni dan indah.</p>","misconceptionId":"mis-bisd-kesesuaian-001"},{"key":"C","text":"<p>Karena warna merah paling disukai anak-anak.</p>","misconceptionId":"mis-bisd-kesesuaian-001"},{"key":"D","text":"<p>Untuk membedakan judul dari nomor urut gambar.</p>","misconceptionId":"mis-bisd-kesesuaian-003"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('bisd-kesesuaian-002', 'sub-bahasa-indonesia-sd', 'top-bi-sd-evaluasi', 'st-bi-sd-kesesuaian-antarunsur', 'con-bi-sd-kesesuaian-antarunsur', 'single', 'Menilai fungsi gambar terhadap isi teks', 'menengah', 'penerapan', 'html', 'psg-bisd-kesesuaian-poster', null, '<p>Apa fungsi enam gambar berurutan pada poster tersebut?</p>', 'Pilih satu jawaban.', '<p>Gambar-gambar itu berurutan dari membasahi tangan, menuang sabun, menggosok jari, sampai mengeringkan tangan. Setiap gambar diberi nomor urut dan tulisan penjelas.</p><p>Susunan seperti itu menunjukkan langkah yang harus dikerjakan berurutan, bukan sekadar hiasan.</p>', '[{"key":"A","text":"<p>Menghias bagian tengah poster agar menarik.</p>","misconceptionId":"mis-bisd-kesesuaian-001"},{"key":"B","text":"<p>Menunjukkan jenis kuman yang ada di tangan.</p>","misconceptionId":"mis-bisd-kesesuaian-003"},{"key":"C","text":"<p>Menandai jumlah keran yang ada di sekolah.</p>","misconceptionId":"mis-bisd-kesesuaian-003"},{"key":"D","text":"<p>Menunjukkan urutan langkah mencuci tangan.</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('bisd-kesesuaian-003', 'sub-bahasa-indonesia-sd', 'top-bi-sd-evaluasi', 'st-bi-sd-kesesuaian-antarunsur', 'con-bi-sd-kesesuaian-antarunsur', 'single', 'Menilai kesesuaian gambar tambahan dengan isi teks', 'lanjut', 'penalaran', 'html', 'psg-bisd-kesesuaian-poster', null, '<p>Apakah gambar kuman yang sedang menjauh sesuai dengan isi poster tersebut?</p>', 'Pilih satu jawaban.', '<p>Di sebelah gambar kuman tertulis “Kuman pergi, tubuh sehat”. Gambar kuman yang menjauh menggambarkan akibat baik setelah tangan dicuci, jadi sesuai dengan isi poster.</p><p>Pilihan D keliru karena poster membahas mencuci tangan, bukan tata cara makan.</p>', '[{"key":"A","text":"<p>Tidak sesuai, karena kuman tidak terlihat oleh mata.</p>","misconceptionId":"mis-bisd-kesesuaian-001"},{"key":"B","text":"<p>Sesuai, karena menggambarkan hasil mencuci tangan.</p>"},{"key":"C","text":"<p>Sesuai, karena warnanya sama dengan warna sabun.</p>","misconceptionId":"mis-bisd-kesesuaian-001"},{"key":"D","text":"<p>Tidak sesuai, karena poster membahas cara makan.</p>","misconceptionId":"mis-bisd-kesesuaian-005"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('bisd-kesesuaian-004', 'sub-bahasa-indonesia-sd', 'top-bi-sd-evaluasi', 'st-bi-sd-kesesuaian-antarunsur', 'con-bi-sd-kesesuaian-antarunsur', 'single', 'Menilai kesesuaian simpulan dengan data pada teks', 'menengah', 'penerapan', 'html', 'psg-bisd-kesesuaian-perpustakaan', null, '<p>Simpulan yang sesuai dengan catatan tersebut adalah ….</p>', 'Pilih satu jawaban.', '<p>Angka pengunjung tertinggi adalah 40 anak pada hari Jumat, sesuai kalimat “Hari Jumat tercatat paling banyak”.</p><p>Pilihan A ditolak oleh angka hari Rabu yang justru turun. Pilihan D keliru karena latihan pramuka dihubungkan teks dengan hari Rabu, bukan hari Kamis.</p>', '[{"key":"A","text":"<p>Jumlah pengunjung naik setiap hari sepanjang pekan.</p>","misconceptionId":"mis-bisd-kesesuaian-002"},{"key":"B","text":"<p>Buku kamus menjadi buku yang paling sering dipinjam.</p>","misconceptionId":"mis-bisd-kesesuaian-002"},{"key":"C","text":"<p>Pengunjung paling banyak tercatat pada hari Jumat.</p>"},{"key":"D","text":"<p>Latihan pramuka membuat pengunjung Kamis berkurang.</p>","misconceptionId":"mis-bisd-kesesuaian-003"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('bisd-kesesuaian-005', 'sub-bahasa-indonesia-sd', 'top-bi-sd-evaluasi', 'st-bi-sd-kesesuaian-antarunsur', 'con-bi-sd-kesesuaian-antarunsur', 'single', 'Menunjukkan data yang menolak sebuah simpulan', 'lanjut', 'penalaran', 'html', 'psg-bisd-kesesuaian-perpustakaan', null, '<p>Pernyataan “jumlah pengunjung selalu bertambah setiap hari” tidak sesuai dengan catatan tersebut karena ….</p>', 'Pilih satu jawaban.', '<p>Untuk menolak kata selalu, cukup ditunjukkan satu hari yang menyimpang. Pengunjung Selasa 30 anak, lalu Rabu turun menjadi 18 anak.</p><p>Pilihan B benar menurut data, tetapi justru tidak menolak pernyataan itu. Pilihan C dan D membahas hal lain.</p>', '[{"key":"A","text":"<p>pengunjung hari Rabu lebih sedikit daripada hari Selasa</p>"},{"key":"B","text":"<p>pengunjung hari Jumat paling banyak dalam sepekan</p>","misconceptionId":"mis-bisd-kesesuaian-002"},{"key":"C","text":"<p>buku cerita lebih sering dipinjam daripada kamus</p>","misconceptionId":"mis-bisd-kesesuaian-003"},{"key":"D","text":"<p>perpustakaan menambah rak baru pada akhir bulan</p>","misconceptionId":"mis-bisd-kesesuaian-003"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('bisd-kesesuaian-006', 'sub-bahasa-indonesia-sd', 'top-bi-sd-evaluasi', 'st-bi-sd-kesesuaian-antarunsur', 'con-bi-sd-kesesuaian-antarunsur', 'single', 'Menemukan kalimat yang tidak padu dalam paragraf', 'menengah', 'penerapan', 'html', 'psg-bisd-kesesuaian-melati', null, '<p>Kalimat yang tidak padu pada paragraf ketiga teks tersebut adalah ….</p>', 'Pilih satu jawaban.', '<p>Paragraf ketiga membahas bunga melati: waktu berbunga, mekarnya kuncup, harumnya, dan pemanfaatannya.</p><p>Kalimat tentang perbaikan lapangan memang mungkin benar, tetapi tidak membahas melati sama sekali. Karena itu kalimat tersebut tidak padu.</p>', '[{"key":"A","text":"<p>Kuncupnya mekar menjelang pagi hari.</p>","misconceptionId":"mis-bisd-kesesuaian-004"},{"key":"B","text":"<p>Bau harumnya tercium sampai ke ruang guru.</p>","misconceptionId":"mis-bisd-kesesuaian-004"},{"key":"C","text":"<p>Bunga melati juga dipetik untuk mengisi vas di ruang kepala sekolah.</p>","misconceptionId":"mis-bisd-kesesuaian-004"},{"key":"D","text":"<p>Lapangan sekolah akan diperbaiki pada liburan mendatang.</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('bisd-kesesuaian-007', 'sub-bahasa-indonesia-sd', 'top-bi-sd-evaluasi', 'st-bi-sd-kesesuaian-antarunsur', 'con-bi-sd-kesesuaian-antarunsur', 'single', 'Menilai kesesuaian judul dengan isi teks', 'lanjut', 'penalaran', 'html', 'psg-bisd-kesesuaian-melati', null, '<p>Judul lain yang sesuai untuk teks tersebut adalah ….</p>', 'Pilih satu jawaban.', '<p>Seluruh paragraf membahas melati di halaman sekolah: tempat tanamnya, cara merawatnya, masa berbunganya, dan siapa yang merawat. Judul pada pilihan B mewakili semuanya.</p><p>Pilihan A, C, dan D hanya diambil dari satu kalimat sehingga tidak mewakili isi teks.</p>', '[{"key":"A","text":"<p>Cara Membuat Pupuk Kandang</p>","misconceptionId":"mis-bisd-kesesuaian-005"},{"key":"B","text":"<p>Merawat Melati di Sekolah Kami</p>"},{"key":"C","text":"<p>Kegiatan Regu Piket Kelas Empat</p>","misconceptionId":"mis-bisd-kesesuaian-005"},{"key":"D","text":"<p>Rencana Perbaikan Lapangan Sekolah</p>","misconceptionId":"mis-bisd-kesesuaian-005"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('bisd-kesesuaian-008', 'sub-bahasa-indonesia-sd', 'top-bi-sd-evaluasi', 'st-bi-sd-kesesuaian-antarunsur', 'con-bi-sd-kesesuaian-antarunsur', 'mcma', 'Menilai unsur yang membantu pembaca memahami isi teks', 'menengah', 'penerapan', 'html', 'psg-bisd-kesesuaian-poster', null, '<p>Bagian mana saja pada poster yang membantu pembaca mengikuti langkah mencuci tangan?</p>', 'Klik pada setiap pilihan jawaban benar! Jawaban benar lebih dari satu.', '<p>Nomor urut menunjukkan langkah mana yang lebih dahulu, sedangkan tulisan pendek menjelaskan gerakan pada tiap gambar. Keduanya membantu pembaca mengikuti langkahnya.</p><p>Warna hijau pada gambar kuman berhubungan dengan akibat mencuci tangan, bukan dengan urutan langkahnya.</p>', '[{"key":"A","text":"<p>Warna hijau pada gambar kuman.</p>","misconceptionId":"mis-bisd-kesesuaian-003"},{"key":"B","text":"<p>Nomor urut pada setiap gambar.</p>"},{"key":"C","text":"<p>Tulisan pendek di bawah setiap nomor.</p>"}]'::jsonb, null, array['B', 'C'], null, null, 'B, C', false, null, null),
  ('bisd-kesesuaian-009', 'sub-bahasa-indonesia-sd', 'top-bi-sd-evaluasi', 'st-bi-sd-kesesuaian-antarunsur', 'con-bi-sd-kesesuaian-antarunsur', 'mcma', 'Menemukan informasi yang saling mendukung dalam teks', 'lanjut', 'penalaran', 'html', 'psg-bisd-kesesuaian-perpustakaan', null, '<p>Pasangan informasi mana saja pada teks tersebut yang saling mendukung?</p>', 'Klik pada setiap pilihan jawaban benar! Jawaban benar lebih dari satu.', '<p>Kegiatan membaca bersama yang diikuti dua kelas menjelaskan banyaknya pengunjung hari Jumat. Latihan pramuka menjelaskan sedikitnya pengunjung hari Rabu. Keduanya pasangan sebab dan akibat.</p><p>Pada pilihan B, kedua informasi memang ada di dalam teks, tetapi tidak saling menjelaskan.</p>', '[{"key":"A","text":"<p>Pengunjung Jumat paling banyak dan ada kegiatan membaca bersama.</p>"},{"key":"B","text":"<p>Buku kamus jarang dipinjam dan rak baru diisi buku cerita.</p>","misconceptionId":"mis-bisd-kesesuaian-003"},{"key":"C","text":"<p>Pengunjung Rabu paling sedikit dan ada latihan pramuka.</p>"}]'::jsonb, null, array['A', 'C'], null, null, 'A, C', false, null, null),
  ('bisd-kesesuaian-010', 'sub-bahasa-indonesia-sd', 'top-bi-sd-evaluasi', 'st-bi-sd-kesesuaian-antarunsur', 'con-bi-sd-kesesuaian-antarunsur', 'category', 'Menilai kesesuaian pernyataan dengan data pada teks', 'lanjut', 'penalaran', 'html', 'psg-bisd-kesesuaian-perpustakaan', null, '<p>Tentukan sesuai atau tidak sesuai untuk setiap pernyataan berikut berdasarkan catatan kunjungan tersebut!</p>', 'Klik pada pilihan Sesuai atau Tidak Sesuai untuk setiap pernyataan.', '<p>P1 tidak sesuai: dua kali 18 adalah 36, sedangkan hari Jumat tercatat 40 anak.</p><p>P2 sesuai: Kamis 32 anak, Senin 25 anak.</p><p>P3 tidak sesuai: buku pengetahuan berada di urutan kedua. Yang paling jarang dipinjam adalah buku kamus.</p><p>P4 sesuai: 30 − 18 = 12 anak.</p>', null, null, null, '[{"key":"S","label":"Sesuai"},{"key":"T","label":"Tidak Sesuai"}]'::jsonb, '[{"id":"p1","text":"<p>Pengunjung hari Jumat dua kali lipat pengunjung hari Rabu.</p>","correctCategoryKey":"T","misconceptionId":"mis-bisd-kesesuaian-002"},{"id":"p2","text":"<p>Pengunjung hari Kamis lebih banyak daripada hari Senin.</p>","correctCategoryKey":"S"},{"id":"p3","text":"<p>Buku pengetahuan menjadi buku yang paling jarang dipinjam.</p>","correctCategoryKey":"T","misconceptionId":"mis-bisd-kesesuaian-002"},{"id":"p4","text":"<p>Selisih pengunjung hari Selasa dan Rabu dua belas anak.</p>","correctCategoryKey":"S"}]'::jsonb, 'p1: T; p2: S; p3: T; p4: S', false, null, null),
  ('bisd-emosi-001', 'sub-bahasa-indonesia-sd', 'top-bi-sd-evaluasi', 'st-bi-sd-respons-emosional', 'con-bi-sd-respons-emosional', 'single', 'Menyimpulkan perasaan pembaca terhadap akhir cerita', 'menengah', 'penerapan', 'html', 'psg-bisd-emosi-sepeda', null, '<p>Perasaan apa yang paling mungkin dirasakan pembaca pada bagian akhir cerita tersebut?</p>', 'Pilih satu jawaban.', '<p>Pada akhir cerita, tokoh aku mengayuh sepeda peninggalan kakeknya dan seolah mendengar siulan Kakek di belakangnya. Bagian itu memadukan rasa kehilangan dengan kenangan yang manis sehingga menimbulkan rasa terharu.</p><p>Tidak ada kejadian yang menakutkan maupun mengecewakan pada bagian tersebut.</p>', '[{"key":"A","text":"<p>Takut.</p>","misconceptionId":"mis-bisd-emosi-001"},{"key":"B","text":"<p>Marah.</p>","misconceptionId":"mis-bisd-emosi-001"},{"key":"C","text":"<p>Terharu.</p>"},{"key":"D","text":"<p>Kecewa.</p>","misconceptionId":"mis-bisd-emosi-002"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('bisd-emosi-002', 'sub-bahasa-indonesia-sd', 'top-bi-sd-evaluasi', 'st-bi-sd-respons-emosional', 'con-bi-sd-respons-emosional', 'single', 'Menunjuk bagian teks yang menimbulkan perasaan tertentu', 'lanjut', 'penalaran', 'html', 'psg-bisd-emosi-sepeda', null, '<p>Bagian mana yang paling menimbulkan rasa sedih bagi pembaca?</p>', 'Pilih satu jawaban.', '<p>Rasa sedih paling kuat muncul pada paragraf keempat: Kakek meninggal, rumah menjadi sepi, dan tokoh aku berangkat sekolah dengan langkah pelan.</p><p>Pilihan A justru kenangan yang menyenangkan, sedangkan pilihan C dan D berada pada bagian ketika keadaan mulai membaik.</p>', '[{"key":"A","text":"<p>Kakek bersiul sepanjang jalan setiap pagi.</p>","misconceptionId":"mis-bisd-emosi-002"},{"key":"B","text":"<p>Kakek pergi selamanya dan rumah terasa sepi.</p>"},{"key":"C","text":"<p>Ayah memasang rantai baru pada sepeda itu.</p>","misconceptionId":"mis-bisd-emosi-002"},{"key":"D","text":"<p>Angin pagi menerpa wajah tokoh aku.</p>","misconceptionId":"mis-bisd-emosi-001"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('bisd-emosi-003', 'sub-bahasa-indonesia-sd', 'top-bi-sd-evaluasi', 'st-bi-sd-respons-emosional', 'con-bi-sd-respons-emosional', 'single', 'Menyimpulkan perasaan tokoh pada bagian tertentu', 'menengah', 'penerapan', 'html', 'psg-bisd-emosi-tenda', null, '<p>Perasaan apa yang muncul ketika suara gemerisik itu terdengar makin dekat?</p>', 'Pilih satu jawaban.', '<p>Bima menarik selimut sampai dagu, jantung tokoh aku berdegup kencang, dan tangannya gemetar memegang senter. Ketiganya menggambarkan suasana tegang.</p><p>Rasa haru dan bangga tidak muncul pada bagian ini, sedangkan bosan bertentangan dengan reaksi tubuh para tokoh.</p>', '[{"key":"A","text":"<p>Haru.</p>","misconceptionId":"mis-bisd-emosi-002"},{"key":"B","text":"<p>Bosan.</p>","misconceptionId":"mis-bisd-emosi-001"},{"key":"C","text":"<p>Bangga.</p>","misconceptionId":"mis-bisd-emosi-002"},{"key":"D","text":"<p>Tegang.</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('bisd-emosi-004', 'sub-bahasa-indonesia-sd', 'top-bi-sd-evaluasi', 'st-bi-sd-respons-emosional', 'con-bi-sd-respons-emosional', 'single', 'Menyimpulkan perubahan perasaan tokoh dalam cerita', 'menengah', 'penerapan', 'html', 'psg-bisd-emosi-tenda', null, '<p>Bagaimana perasaan ketiga anak setelah mengetahui asal suara itu?</p>', 'Pilih satu jawaban.', '<p>Teks menulis “Kami bertiga tertawa lega” setelah suara itu ternyata berasal dari seekor kucing kampung. Bima bahkan memberi kucing itu sisa rotinya.</p><p>Ketegangan pada bagian sebelumnya sudah berakhir, jadi pilihan C tidak lagi tepat untuk bagian ini.</p>', '[{"key":"A","text":"<p>Lega.</p>"},{"key":"B","text":"<p>Kecewa.</p>","misconceptionId":"mis-bisd-emosi-005"},{"key":"C","text":"<p>Ketakutan.</p>","misconceptionId":"mis-bisd-emosi-002"},{"key":"D","text":"<p>Malu.</p>","misconceptionId":"mis-bisd-emosi-005"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('bisd-emosi-005', 'sub-bahasa-indonesia-sd', 'top-bi-sd-evaluasi', 'st-bi-sd-respons-emosional', 'con-bi-sd-respons-emosional', 'single', 'Menyimpulkan perasaan yang dibangun sebuah puisi', 'menengah', 'penerapan', 'html', 'psg-bisd-emosi-puisi', null, '<p>Perasaan apa yang paling kuat tergambar pada puisi tersebut?</p>', 'Pilih satu jawaban.', '<p>Bait ketiga menyebut penyair kini tinggal jauh di kota, sedangkan rumah nenek hanya ada dalam ingatannya. Bait keempat menghadirkan kembali deritan pintu dan suara nenek saat matanya terpejam.</p><p>Gambaran seperti itu menunjukkan perasaan rindu terhadap nenek dan rumahnya.</p>', '[{"key":"A","text":"<p>Gembira.</p>","misconceptionId":"mis-bisd-emosi-002"},{"key":"B","text":"<p>Takut.</p>","misconceptionId":"mis-bisd-emosi-001"},{"key":"C","text":"<p>Rindu.</p>"},{"key":"D","text":"<p>Kesal.</p>","misconceptionId":"mis-bisd-emosi-001"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('bisd-emosi-006', 'sub-bahasa-indonesia-sd', 'top-bi-sd-evaluasi', 'st-bi-sd-respons-emosional', 'con-bi-sd-respons-emosional', 'single', 'Menunjuk larik yang paling menimbulkan perasaan tertentu', 'lanjut', 'penalaran', 'html', 'psg-bisd-emosi-puisi', null, '<p>Larik mana yang paling menimbulkan rasa rindu bagi pembaca?</p>', 'Pilih satu jawaban.', '<p>Larik itu muncul saat mata penyair terpejam. Suara nenek yang memanggil namanya hanya terdengar dalam ingatan, dan justru itulah yang membuat rasa rindu terasa paling kuat.</p><p>Pilihan A dan C hanya menggambarkan keadaan, sedangkan pilihan D menyebut sebab berjauhan tanpa menghadirkan sosok neneknya.</p>', '[{"key":"A","text":"<p>“Ada rumah kayu berpintu biru”.</p>","misconceptionId":"mis-bisd-emosi-004"},{"key":"B","text":"<p>“Dan suara nenek memanggil namaku”.</p>"},{"key":"C","text":"<p>“Menghitung ayam di halaman”.</p>","misconceptionId":"mis-bisd-emosi-004"},{"key":"D","text":"<p>“Tetapi aku tinggal jauh di kota”.</p>","misconceptionId":"mis-bisd-emosi-002"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('bisd-emosi-007', 'sub-bahasa-indonesia-sd', 'top-bi-sd-evaluasi', 'st-bi-sd-respons-emosional', 'con-bi-sd-respons-emosional', 'single', 'Menanggapi kesan yang dibangun pilihan kata penyair', 'lanjut', 'penalaran', 'html', 'psg-bisd-emosi-puisi', null, '<p>Larik “Dalam ingatan yang tak berdebu” menimbulkan kesan bahwa ….</p>', 'Pilih satu jawaban.', '<p>Debu biasanya menutupi barang yang lama tidak disentuh. Ingatan yang tak berdebu berarti kenangan itu masih sering diingat sehingga tetap jelas.</p><p>Pilihan A dan C mengartikan kata debu secara harfiah sehingga kesan yang dibangun penyair menjadi hilang.</p>', '[{"key":"A","text":"<p>rumah nenek selalu dibersihkan setiap hari</p>","misconceptionId":"mis-bisd-emosi-004"},{"key":"B","text":"<p>penyair lupa jalan menuju rumah neneknya</p>","misconceptionId":"mis-bisd-emosi-002"},{"key":"C","text":"<p>rumah kayu itu sudah lama dirobohkan</p>","misconceptionId":"mis-bisd-emosi-004"},{"key":"D","text":"<p>kenangan itu masih jelas dan tidak terlupakan</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('bisd-emosi-008', 'sub-bahasa-indonesia-sd', 'top-bi-sd-evaluasi', 'st-bi-sd-respons-emosional', 'con-bi-sd-respons-emosional', 'mcma', 'Menyimpulkan perasaan tokoh pada akhir cerita', 'menengah', 'penerapan', 'html', 'psg-bisd-emosi-sepeda', null, '<p>Pernyataan mana saja yang tepat tentang perasaan tokoh aku pada akhir cerita?</p>', 'Klik pada setiap pilihan jawaban benar! Jawaban benar lebih dari satu.', '<p>Tokoh aku membersihkan sepeda itu, mengayuhnya ke sekolah, dan seolah mendengar siulan Kakek. Kedua hal itu menunjukkan rasa senang sekaligus rasa dekat kembali dengan kakeknya.</p><p>Tidak ada kalimat yang menunjukkan ia takut menaiki sepeda tersebut.</p>', '[{"key":"A","text":"<p>Merasa dekat kembali dengan kakeknya.</p>"},{"key":"B","text":"<p>Merasa senang dapat memakai sepeda kakeknya.</p>"},{"key":"C","text":"<p>Merasa takut menaiki sepeda tua itu.</p>","misconceptionId":"mis-bisd-emosi-003"}]'::jsonb, null, array['A', 'B'], null, null, 'A, B', false, null, null),
  ('bisd-emosi-009', 'sub-bahasa-indonesia-sd', 'top-bi-sd-evaluasi', 'st-bi-sd-respons-emosional', 'con-bi-sd-respons-emosional', 'mcma', 'Menemukan kalimat yang menunjukkan perasaan takut', 'menengah', 'penerapan', 'html', 'psg-bisd-emosi-tenda', null, '<p>Kalimat mana saja yang menunjukkan tokoh aku sedang ketakutan?</p>', 'Klik pada setiap pilihan jawaban benar! Jawaban benar lebih dari satu.', '<p>Jantung berdegup kencang dan tangan gemetar adalah tanda tubuh saat merasa takut. Keduanya terjadi sebelum suara itu diketahui asalnya.</p><p>Tertawa lega terjadi setelah ketakutan berakhir, jadi kalimat itu justru menunjukkan perasaan yang berlawanan.</p>', '[{"key":"A","text":"<p>Kami bertiga tertawa lega.</p>","misconceptionId":"mis-bisd-emosi-002"},{"key":"B","text":"<p>Jantungku berdegup kencang.</p>"},{"key":"C","text":"<p>Aku memegang senter dengan tangan gemetar.</p>"}]'::jsonb, null, array['B', 'C'], null, null, 'B, C', false, null, null),
  ('bisd-emosi-010', 'sub-bahasa-indonesia-sd', 'top-bi-sd-evaluasi', 'st-bi-sd-respons-emosional', 'con-bi-sd-respons-emosional', 'category', 'Menilai reaksi pembaca terhadap akhir cerita', 'lanjut', 'penalaran', 'html', 'psg-bisd-emosi-tenda', null, '<p>Salma telah membaca cerita tersebut. Bagaimana reaksi yang wajar dirasakan saat membaca akhir cerita itu? Tentukan benar atau salah untuk setiap pernyataan berikut!</p>', 'Klik pada pilihan Benar atau Salah untuk setiap pernyataan.', '<p>P1 dan P2 benar: suara yang menakutkan itu ternyata berasal dari kucing kampung, dan ketiga anak tertawa lega.</p><p>P3 salah karena kucing itu justru duduk di depan tenda sampai pagi. P4 salah karena Kak Pembina menanggapinya sambil tersenyum, bukan memarahi mereka.</p>', null, null, null, '[{"key":"B","label":"Benar"},{"key":"S","label":"Salah"}]'::jsonb, '[{"id":"p1","text":"<p>Lega karena suara itu ternyata berasal dari seekor kucing.</p>","correctCategoryKey":"B"},{"id":"p2","text":"<p>Geli karena ketakutan mereka berakhir dengan tawa.</p>","correctCategoryKey":"B"},{"id":"p3","text":"<p>Sedih karena kucing itu pergi meninggalkan tenda mereka.</p>","correctCategoryKey":"S","misconceptionId":"mis-bisd-emosi-003"},{"id":"p4","text":"<p>Kecewa karena Kak Pembina memarahi mereka bertiga.</p>","correctCategoryKey":"S","misconceptionId":"mis-bisd-emosi-003"}]'::jsonb, 'p1: B; p2: B; p3: S; p4: S', false, null, null)
insert into public.packages (id, kind, slug, title, subject_id, series_id, level, description, summary, variant, variant_label, estimated_minutes, difficulty_range, skills, instructions, is_premium, is_published, sort_order, source_id, source_file) values
  ('pkg-latihan-bisd-kosakata-umum-khusus', 'latihan', 'bahasa-indonesia-sd-kosakata-umum-khusus', 'Kosakata Umum dan Khusus dalam Berbagai Bidang', 'sub-bahasa-indonesia-sd', 'series-latihan-tka-bahasa-indonesia-sd', 'SD', 'Menemukan makna kata khusus bidang pertanian, kesehatan, dan perbengkelan dari konteks kalimat, serta membedakannya dari kata umum yang dipakai sehari-hari.', '10 soal bergaya TKA untuk mengenali kosakata umum dan khusus pada tiga teks dari bidang yang berbeda.', 'adaptif', 'Latihan TKA', 30, 'dasar–lanjut', array['Menebak makna kata khusus dari kalimat di sekitarnya', 'Membedakan kata umum dan kata khusus dalam satu teks', 'Mengenali kata khusus milik satu bidang pekerjaan', 'Memilih kata umum yang mewakili beberapa kata khusus'], array['Baca teksnya sampai selesai sebelum menjawab.', 'Cari bukti jawabannya di dalam teks, bukan dari ingatan sendiri.', 'Periksa lagi pilihan yang mirip sebelum lanjut.'], false, true, 1, 'authored-tka-bahasa-indonesia-sd-bahasa-indonesia-sd-kosakata-umum-khusus', '01-kosakata-umum-khusus.json'),
  ('pkg-latihan-bisd-objek-kosakata', 'latihan', 'bahasa-indonesia-sd-objek-berdasarkan-kosakata', 'Menebak Objek dari Kosakata dalam Teks', 'sub-bahasa-indonesia-sd', 'series-latihan-tka-bahasa-indonesia-sd', 'SD', 'Mengenali benda yang dimaksud penulis dari kata-kata yang menggambarkan bentuk, bahan, bagian, dan kegunaannya, baik pada teks fiksi, teks informasi, maupun puisi.', '10 soal bergaya TKA untuk mengenali objek dari kosakata yang dipakai dalam cerita, teks informasi, dan puisi.', 'adaptif', 'Latihan TKA', 30, 'dasar–lanjut', array['Mengenali benda dari gambaran bentuk dan bahannya', 'Mengenali benda dari kegunaannya dalam teks', 'Membedakan dua benda yang digambarkan pada teks yang sama', 'Menemukan larik puisi yang menunjuk pada benda tertentu'], array['Baca teksnya sampai selesai sebelum menjawab.', 'Cari bukti jawabannya di dalam teks, bukan dari ingatan sendiri.', 'Periksa lagi pilihan yang mirip sebelum lanjut.'], false, true, 2, 'authored-tka-bahasa-indonesia-sd-bahasa-indonesia-sd-objek-berdasarkan-kosakata', '02-objek-berdasarkan-kosakata.json'),
  ('pkg-latihan-bisd-ikhtisar-bagan', 'latihan', 'bahasa-indonesia-sd-ikhtisar-dan-bagan', 'Menyusun Ulang Isi Teks dalam Ikhtisar dan Bagan', 'sub-bahasa-indonesia-sd', 'series-latihan-tka-bahasa-indonesia-sd', 'SD', 'Menyusun kembali isi teks menjadi bagan pengelompokan, bagan urutan langkah, dan ikhtisar satu kalimat, lalu memeriksa bagian bagan yang keliru.', '10 soal bergaya TKA untuk memindahkan isi teks ke dalam bagan dan ikhtisar tanpa mengubah maknanya.', 'adaptif', 'Latihan TKA', 30, 'dasar–lanjut', array['Memilih bagan yang sesuai dengan isi teks', 'Mengisi cabang bagan dengan contoh yang tepat', 'Menyusun langkah kerja menjadi bagan urutan', 'Menulis ikhtisar yang mewakili seluruh isi teks'], array['Baca teksnya sampai selesai sebelum menjawab.', 'Cari bukti jawabannya di dalam teks, bukan dari ingatan sendiri.', 'Periksa lagi pilihan yang mirip sebelum lanjut.'], false, true, 3, 'authored-tka-bahasa-indonesia-sd-bahasa-indonesia-sd-ikhtisar-dan-bagan', '03-ikhtisar-dan-bagan.json'),
  ('pkg-latihan-bisd-informasi-tersurat', 'latihan', 'bahasa-indonesia-sd-informasi-tersurat', 'Menemukan Informasi Tersurat dalam Teks', 'sub-bahasa-indonesia-sd', 'series-latihan-tka-bahasa-indonesia-sd', 'SD', 'Menemukan siapa, kapan, di mana, berapa, dan apa yang tertulis langsung di dalam fabel, teks sejarah sederhana, dan cerita kegiatan sehari-hari.', '10 soal bergaya TKA untuk menemukan informasi yang tertulis jelas pada teks fiksi dan teks informasi.', 'adaptif', 'Latihan TKA', 30, 'dasar–lanjut', array['Menemukan pelaku dan perbuatannya di dalam teks', 'Menemukan waktu, tempat, dan angka yang disebut teks', 'Membedakan isi teks dari pengetahuan sendiri', 'Memeriksa pernyataan yang mengubah sedikit isi teks'], array['Baca teksnya sampai selesai sebelum menjawab.', 'Cari bukti jawabannya di dalam teks, bukan dari ingatan sendiri.', 'Periksa lagi pilihan yang mirip sebelum lanjut.'], false, true, 4, 'authored-tka-bahasa-indonesia-sd-bahasa-indonesia-sd-informasi-tersurat', '04-informasi-tersurat.json'),
  ('pkg-latihan-bisd-ide-pokok', 'latihan', 'bahasa-indonesia-sd-ide-pokok-amanat-nilai', 'Menyimpulkan Ide Pokok, Amanat, dan Nilai dalam Teks', 'sub-bahasa-indonesia-sd', 'series-latihan-tka-bahasa-indonesia-sd', 'SD', 'Menyimpulkan ide pokok paragraf dan seluruh teks, membedakannya dari gagasan pendukung, serta menemukan amanat, sifat tokoh, peristiwa penting, dan nilai dalam cerita.', '10 soal bergaya TKA untuk menyimpulkan ide pokok, gagasan pendukung, amanat, dan nilai pada teks fiksi maupun teks informasi.', 'adaptif', 'Latihan TKA', 30, 'dasar–lanjut', array['Menentukan ide pokok tiap paragraf', 'Membedakan ide pokok dari gagasan pendukung', 'Menyimpulkan amanat dan nilai dalam cerita', 'Menyimpulkan sifat tokoh dari perbuatannya'], array['Baca teksnya sampai selesai sebelum menjawab.', 'Cari bukti jawabannya di dalam teks, bukan dari ingatan sendiri.', 'Periksa lagi pilihan yang mirip sebelum lanjut.'], false, true, 5, 'authored-tka-bahasa-indonesia-sd-bahasa-indonesia-sd-ide-pokok-amanat-nilai', '05-ide-pokok-amanat-nilai.json'),
  ('pkg-latihan-bisd-perubahan-unsur', 'latihan', 'bahasa-indonesia-sd-perubahan-objek-karakter-latar', 'Menyimpulkan Perubahan Objek, Karakter, dan Latar', 'sub-bahasa-indonesia-sd', 'series-latihan-tka-bahasa-indonesia-sd', 'SD', 'Menyimpulkan perubahan bentuk benda pada teks proses, perubahan sikap tokoh pada cerita, dan perubahan suasana tempat dari dahulu ke sekarang.', '10 soal bergaya TKA untuk menyimpulkan perubahan sederhana pada benda, tokoh, dan latar beserta penyebabnya.', 'adaptif', 'Latihan TKA', 30, 'dasar–lanjut', array['Menyimpulkan perubahan bentuk benda pada teks proses', 'Menemukan penyebab sebuah perubahan', 'Menyimpulkan perubahan sikap tokoh dalam cerita', 'Membandingkan keadaan latar dahulu dan sekarang'], array['Baca teksnya sampai selesai sebelum menjawab.', 'Cari bukti jawabannya di dalam teks, bukan dari ingatan sendiri.', 'Periksa lagi pilihan yang mirip sebelum lanjut.'], false, true, 6, 'authored-tka-bahasa-indonesia-sd-bahasa-indonesia-sd-perubahan-objek-karakter-latar', '06-perubahan-objek-karakter-latar.json'),
  ('pkg-latihan-bisd-makna-ungkapan', 'latihan', 'bahasa-indonesia-sd-makna-ungkapan', 'Menjelaskan Makna Ungkapan dalam Teks', 'sub-bahasa-indonesia-sd', 'series-latihan-tka-bahasa-indonesia-sd', 'SD', 'Menjelaskan makna ungkapan seperti ringan tangan, besar kepala, banting tulang, gulung tikar, dan naik daun berdasarkan kalimat tempat ungkapan itu dipakai.', '10 soal bergaya TKA untuk memahami makna ungkapan dalam cerita, kisah perajin, dan puisi.', 'adaptif', 'Latihan TKA', 30, 'dasar–lanjut', array['Menjelaskan makna ungkapan dari konteks kalimat', 'Membedakan makna ungkapan dari makna kata demi kata', 'Membedakan ungkapan bermakna baik dan bermakna kurang baik', 'Menafsirkan ungkapan dalam larik puisi'], array['Baca teksnya sampai selesai sebelum menjawab.', 'Cari bukti jawabannya di dalam teks, bukan dari ingatan sendiri.', 'Periksa lagi pilihan yang mirip sebelum lanjut.'], false, true, 7, 'authored-tka-bahasa-indonesia-sd-bahasa-indonesia-sd-makna-ungkapan', '07-makna-ungkapan.json'),
  ('pkg-latihan-bisd-relevansi-peristiwa', 'latihan', 'bahasa-indonesia-sd-relevansi-peristiwa', 'Menilai Relevansi Peristiwa dengan Kehidupan Sehari-hari', 'sub-bahasa-indonesia-sd', 'series-latihan-tka-bahasa-indonesia-sd', 'SD', 'Menilai peristiwa dalam teks dengan pengalaman sendiri: memilih contoh kejadian sehari-hari yang sejalan dengan isi teks dan menolak contoh yang justru berlawanan.', '10 soal bergaya TKA untuk menghubungkan peristiwa dalam teks dengan kejadian sehari-hari di rumah, sekolah, dan kampung.', 'adaptif', 'Latihan TKA', 30, 'dasar–lanjut', array['Memilih contoh kejadian sehari-hari yang sejalan dengan teks', 'Menilai perbuatan tokoh yang layak ditiru', 'Membedakan alasan yang mendukung dan yang tidak mendukung', 'Menerapkan pesan teks pada keadaan di sekolah dan rumah'], array['Baca teksnya sampai selesai sebelum menjawab.', 'Cari bukti jawabannya di dalam teks, bukan dari ingatan sendiri.', 'Periksa lagi pilihan yang mirip sebelum lanjut.'], false, true, 8, 'authored-tka-bahasa-indonesia-sd-bahasa-indonesia-sd-relevansi-peristiwa', '08-relevansi-peristiwa.json'),
  ('pkg-latihan-bisd-kesesuaian-antarunsur', 'latihan', 'bahasa-indonesia-sd-kesesuaian-antarunsur', 'Menilai Kesesuaian Antarunsur dan Antarinformasi', 'sub-bahasa-indonesia-sd', 'series-latihan-tka-bahasa-indonesia-sd', 'SD', 'Menilai kesesuaian gambar, warna, dan judul dengan isi teks, memeriksa simpulan terhadap data, serta menemukan kalimat yang tidak padu dalam paragraf.', '10 soal bergaya TKA untuk menilai apakah unsur dan informasi di dalam teks sudah saling cocok.', 'adaptif', 'Latihan TKA', 30, 'dasar–lanjut', array['Menilai fungsi gambar dan warna pada poster', 'Memeriksa simpulan terhadap data yang disajikan', 'Menemukan kalimat yang tidak padu dalam paragraf', 'Menilai kesesuaian judul dengan isi teks'], array['Baca teksnya sampai selesai sebelum menjawab.', 'Cari bukti jawabannya di dalam teks, bukan dari ingatan sendiri.', 'Periksa lagi pilihan yang mirip sebelum lanjut.'], false, true, 9, 'authored-tka-bahasa-indonesia-sd-bahasa-indonesia-sd-kesesuaian-antarunsur', '09-kesesuaian-antarunsur.json'),
  ('pkg-latihan-bisd-respons-emosional', 'latihan', 'bahasa-indonesia-sd-respons-emosional', 'Menyimpulkan Respons Emosional terhadap Teks Fiksi', 'sub-bahasa-indonesia-sd', 'series-latihan-tka-bahasa-indonesia-sd', 'SD', 'Menyimpulkan perasaan yang wajar muncul saat membaca cerita dan puisi, menunjuk bagian teks yang menimbulkannya, serta menolak reaksi yang tidak didukung isi teks.', '10 soal bergaya TKA untuk menanggapi cerita dan puisi secara emosional dengan bukti dari teksnya.', 'adaptif', 'Latihan TKA', 30, 'dasar–lanjut', array['Menyimpulkan perasaan pembaca terhadap bagian cerita', 'Menunjuk kalimat yang menimbulkan perasaan tertentu', 'Menanggapi kesan yang dibangun larik puisi', 'Menolak reaksi yang tidak sesuai akhir cerita'], array['Baca teksnya sampai selesai sebelum menjawab.', 'Cari bukti jawabannya di dalam teks, bukan dari ingatan sendiri.', 'Periksa lagi pilihan yang mirip sebelum lanjut.'], false, true, 10, 'authored-tka-bahasa-indonesia-sd-bahasa-indonesia-sd-respons-emosional', '10-respons-emosional.json')
