-- Latihan TKA Bahasa Indonesia SD
-- 10 paket, 100 soal, 30 bacaan. Satu paket untuk satu
-- subkompetensi pada matriks asesmen TKA SD (Pusmendik), mapel wajib Bahasa Indonesia.
--
-- Dihasilkan oleh scripts/build-bahasa-indonesia-sd.mjs dari
-- supabase/seed/bahasa-indonesia-sd/*.json. Jangan disunting langsung: ubah JSON-nya
-- lalu jalankan ulang skripnya. Aman dijalankan berulang di SQL Editor.

begin;

-- Mata pelajaran
on conflict (id) do update set slug = excluded.slug, name = excluded.name, short_name = excluded.short_name, level = excluded.level, description = excluded.description, sort_order = excluded.sort_order;

-- Seri dan produk
on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, is_active = excluded.is_active, sort_order = excluded.sort_order;
on conflict (id) do update set slug = excluded.slug, title = excluded.title, subject_id = excluded.subject_id, series_id = excluded.series_id, description = excluded.description, is_active = excluded.is_active, sort_order = excluded.sort_order;

-- Capaian (kompetensi)
on conflict (id) do update set subject_id = excluded.subject_id, slug = excluded.slug, name = excluded.name, description = excluded.description, sort_order = excluded.sort_order;

-- Materi (subkompetensi)
on conflict (id) do update set topic_id = excluded.topic_id, slug = excluded.slug, name = excluded.name, description = excluded.description, sort_order = excluded.sort_order;

-- Submateri (fokus latihan tiap paket)
on conflict (id) do update set subtopic_id = excluded.subtopic_id, name = excluded.name, description = excluded.description, sort_order = excluded.sort_order;

-- Bacaan
on conflict (id) do update set subject_id = excluded.subject_id, label = excluded.label, body_html = excluded.body_html, sort_order = excluded.sort_order;

-- Miskonsepsi yang dilacak pengecoh
on conflict (id) do update set label = excluded.label, description = excluded.description, insight = excluded.insight;

-- Soal
on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, concept_id = excluded.concept_id, type = excluded.type, competency = excluded.competency, difficulty = excluded.difficulty, reasoning_type = excluded.reasoning_type, content_format = excluded.content_format, passage_id = excluded.passage_id, stimulus = excluded.stimulus, question_text = excluded.question_text, instruction = excluded.instruction, explanation = excluded.explanation, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, requires_visual = excluded.requires_visual, visual_prompt = excluded.visual_prompt, visual_type = excluded.visual_type;

-- Paket latihan
on conflict (id) do update set kind = excluded.kind, slug = excluded.slug, title = excluded.title, subject_id = excluded.subject_id, series_id = excluded.series_id, level = excluded.level, description = excluded.description, summary = excluded.summary, variant = excluded.variant, variant_label = excluded.variant_label, estimated_minutes = excluded.estimated_minutes, difficulty_range = excluded.difficulty_range, skills = excluded.skills, instructions = excluded.instructions, is_premium = excluded.is_premium, is_published = excluded.is_published, sort_order = excluded.sort_order, source_id = excluded.source_id, source_file = excluded.source_file;

-- Urutan soal di dalam paket
on conflict (package_id, question_id) do update set package_id = excluded.package_id, question_id = excluded.question_id, position = excluded.position;

commit;
